 \label{thm:PTAS for sparse games}
For any $k$, there is a PTAS for the Nash equilibrium problem in
$k$-sparse bimatrix games.

\label{lemma: restated lipton markakis mehta}
Let $\G=(R,C)$ be a normalized bimatrix game and $(x,y)$ a Nash
equilibrium of $\G$. Let $\X$ be the distribution formed by
taking $t=\lceil 16 \log n /\epsilon^2 \rceil$ independent random
samples from $x$ and defining the uniform distribution on the
samples, and similarly define $\cal Y$ by taking samples from $y$.
Then with probability at least $1-\frac{4}{n}$ the following are
satisfied
\begin{enumerate}
\item the pair $(\X,\cal{Y})$ is an $\epsilon$-Nash equilibrium of $\G$; \label{assertion 1 in LMM restated}
\item $|e_i^{\text{\tiny T}} R \Y - e_i^{\text{\tiny T}} R y| \le \epsilon/2$, for all $i\in[n]$; \label{assertion 2 in LMM restated}
\item $|\X^{\text{\tiny T}} C e_j - x^{\text{\tiny T}} C e_j| \le \epsilon/2$, for all $j \in [n]$; \label{assertion 3 in LMM restated}
\end{enumerate}

 \label{claim:cardinality of good multisets is large}
The sets $\A$ and $\B$ satisfy
$$|\A| \ge \left(1-\frac{4}{n}\right)\left( \delta n \right)^t \text{~and~} |\B| \ge  \left(1-\frac{4}{n}\right)\left( \delta n \right)^t.$$

\label{claim: probability of success of linear support large} If $\X', \Y'$ are the uniform distributions over random multisets $A'$ and $B'$ then
\begin{align}
&\Pr \left[ (\X',\Y') \text{ is an $\epsilon$-Nash equilibrium} \right] \notag\\&~~~~~~~~~~~~~~~~~ =  \Omega \left(\delta^2 \cdot n^{-32 \log(1/\delta)/{\epsilon^2}}\right). \label{eq:large support games final probability}
\end{align}

 \label{lem: claim about the properties of strategy of the row player at eps-equilibrium}
Let $\epsilon <1$. If $(x,y)$ is an $\epsilon$-Nash equilibrium of the game $\G_S$, where $x$ is the mixed strategy of the row player and $y$ that of the column player, then the following properties are satisfied by $x$:
\begin{enumerate}
\item $x_i = 0$, for all $i \notin S$;

\item $\ell_1(x, u_S) \le 8 \epsilon$, where $u_S$ is the uniform distribution over $S$, and $\ell_1(x, u_S)$ represents the $\ell_1$ distance between distributions $x$, $u_S$.
\end{enumerate}

\label{claim:superpolynomially many disjoint balls}
There is a family of $\Omega\left(
n^{(.8-34\epsilon)\log_2 n}\right)$ disjoint such balls.

 \label{theorem: no subexponential oblivious PTAS}
For any constant $c\ge 0$, $\epsilon <1$, no oblivious $\epsilon$-approximation algorithm for anonymous games with $2$ strategies and $3$ player types has probability of success larger than $n^{-c} \cdot 2^{-\Omega(1 /
\epsilon^{1/3})}$.

 \label{theorem: structural result for approximate equilibria}
For every $\epsilon >0$, there exists some integer $k=O(1/\epsilon)$ such
that for any $n$-player $2$-strategy anonymous game with payoffs in
$[-1,1]$ there is an $\epsilon$-Nash equilibrium such that

\begin{enumerate}
\item either at most $k^3$ players randomize, and their mixed strategies are integer multiples of $1/k^2$; \label{item in structural result: a few players randomize}
\item or all players who randomize use the same mixed strategy, and this strategy is an integer multiple of $\frac{1}{kn}$.\label{item in structural result: many players randomize}
\end{enumerate}

 \label{lem: bound on l1 from bound on the sum of the half of them}
Let $\{a_i\}_{i=1}^{\ell}$ be real numbers satisfying the following properties for some $k \in \mathbb{R}_+$:
\begin{enumerate}
\item $a_1 \ge a_2 \ge \ldots \ge a_{\ell}$; \label{strange lemma:cond:1}

\item $\sum_{i=1}^{\ell}a_i =0$; \label{strange lemma:cond:2}

\item $\sum_{i=1}^{\ell/2}a_i \le k$. \label{strange lemma:cond:3}
\end{enumerate}
Then
\begin{align}
\sum_{i=1}^{\ell}|a_i| \le 4k. \label{eq:strange lemma:bound on l1 distance}
\end{align}

\label{claim: lower bound: players B and C cannot be both supported on strategy 1}
In every $\delta'$-Nash equilibrium with $\delta' < \delta$,
$$\Pr[\text{B plays $1$}]=0 \text{~or~}\Pr[\text{C plays $1$}]=0.$$

\label{claim:lower bound:many sets}
There exists a subset $T \subseteq \mathcal{T}^k_{\epsilon}$ such
that:
\begin{enumerate}
\item for every $\P, \Q \in T$: $d(\P,\Q) >0$; \label{item in lower bound construction:property 1}
\item $|T| \ge 2^{\Omega \left(\left({1 \over \epsilon}\right)^{1/3}\right)}$; \label{item in lower bound construction:property 2}
\end{enumerate}

 \label{thm:roos}
Let $\mathcal{P}:=(p_i )_{i=1}^n$ be an arbitrary set of probability
values in $[0,1]$ and $\mathcal{X}:=(X_i)_{i=1}^n$ a collection of
independent indicators with $\E[X_i]=p_i$, for all $i\in [n]$; also
let $X:=\sum_i X_i$. Then, for all $m \in \{0,\ldots,n\}$ and any $p
\in (0,1)$,
\begin{align}
Pr[X = m]  = \sum_{\ell = 0}^n \alpha_{\ell}(\mathcal{P}, p)\cdot
\delta^{\ell}\mathcal{B}_{n,p}(m), \label{eq:krawtchouk expansion}
\end{align}
where in the above $\alpha_0(\mathcal{P},p):=1$,
\begin{align}
\alpha_{\ell}(\mathcal{P},p):= \sum_{1 \le k(1) < \ldots < k(\ell)
\le n} \prod_{r=1}^{\ell}(p_{k(r)}-p),~~\text{for all }\ell \in
[n], \label{eq: krawtchouk coefficients}
\end{align}
and
$$\delta^{\ell}\mathcal{B}_{n,p}(m):=\frac{(n-\ell)!}{n!} \frac{\partial^{\ell}}{\partial p^{\ell}}\mathcal{B}_{n,p}(m),$$
and for the purposes of the last definition we interpret
$$\mathcal{B}_{n,p}(m):=b(m,n,p)$$ as a function of the arguments
$m,n,p$ in the natural way:
$$b(m,n,p):=
\begin{cases}
{n \choose m} p^m (1-p)^{n-m},~\text{for}~n,m \in Z_{+},~m \le n;\\
~~~0,~~~~~~~~~~~~~~~~~\text{otherwise}.
\end{cases}$$

\label{lemma:agreeing coefficients}
For sets $\P$ and $\Q$ satisfying property $(C_d)$, and for all $p$:
$$\alpha_{\ell}(\mathcal{P},p) = \alpha_{\ell}(\mathcal{Q},p),~~~\text{for all $\ell=0,\ldots,d$}.$$

 \label{theorem:binomial appx theorem for large guys}
Let $\mathcal{P}:=(p_i )_{i=1}^n \in [1/2,1)^n$ and $\mathcal{Q}:=(q_i)_{i=1}^n \in [1/2,1)^n$ be two collections of  probability values in $[1/2,1)$. Let also $\mathcal{X}:=(X_i)_{i=1}^n$ and $\mathcal{Y}:=(Y_i)_{i=1}^n$ be two collections of independent indicators with $\E[X_i]=p_i$ and $\E[Y_i]=q_i$, for all $i \in [n]$. If for some $d \in [n]$ Condition $(C_d)$ is satisfied, then
$$\left|\left|\sum_{i}{X_i}~;~\sum_{i}{Y_i} \right|\right|= 20(d+1)^{1/4} 2^{-(d+1)/2}.$$

\label{thm:main}
For any constant integer $k \geq 2$ and any odd integer $p \geq 1$ or $p = \infty$, there is an efficient reduction from $k$-SAT with $n$ variables and $m$ clauses to $\CVP_p$ (or $\SVP_\infty$) on a lattice of rank $n$ (with ambient dimension $n + O(m)$).

In particular, there is no $2^{(1-\eps) n}$-time algorithm for $\CVP_p$ for any odd integer $p \geq 1$ or $p =\infty$ (or $\SVP_\infty$) and any constant $\eps > 0$ unless SETH is false.

\label{thm:all_p_intro}
For any constant integer $k \geq 2$, there is an efficient reduction from $k$-SAT with $n$ variables and $m$ clauses to $\CVP_p$ on a lattice of rank $n$ (with ambient dimension $n + O(m)$) for any $p \geq 1$ such that
\begin{enumerate}
	\item \label{item:odd} $p$ is an odd integer or $p = \infty$;
	\item \label{item:all_but_finite} $p \notin S_k$, where $S_k$ is some finite set (containing all even integers $p \leq k-1$); or
	\item \label{item:p_plus_eps} $p = p_0 + \delta(n)$ for any $p_0 \geq 1$ and any $\delta(n) \neq 0$ that converges to zero as $n \to \infty$.
\end{enumerate}

In particular, if SETH holds then for any constant $\eps > 0$, there is no $2^{(1-\eps)n}$-time algorithm for $\CVP_p$ for any $p \geq 1$ such that
\begin{enumerate}
	\item $p$ is an odd integer or $p = \infty$;
	\item $p \notin S_k$ for some sufficiently large $k$ (depending on $\eps$); or
	\item $p = p_0 + \delta(n)$.
\end{enumerate}

\label{thm:maxcut}
For any $1 \leq p < \infty$, there is an efficient reduction from Max-$2$-SAT with $n$ variables to $\CVP_p$ on a lattice of rank $n$ (and dimension $n +m$, where $m$ is the number of clauses). 

In particular, for any constant $c > 0$, there is no $(\poly(n) \cdot 2^{c n})$-time algorithm for $\CVP_p$ unless there is a $2^{cn}$-time algorithm for Max-$2$-SAT, and there is no $2^{o(n)}$-time algorithm for $\CVP_p$ unless ETH fails.

The (randomized) Gap-Exponential Time Hypothesis ((randomized) Gap-ETH) is the hypothesis that there exist constants $\delta < 1$ and $\eps > 0$ such that no (randomized) algorithm solves $(\delta, 1)$-Gap-$3$-SAT instances with $n$ variables

in $2^{\eps n}$-time.

\label{def:gap-eth}

	\label{thm:isolating_implies_reduction}
If there exists a computable $(p, k)$-isolating parallelepiped for some $p = p(n) \in [1, \infty)$ and integer $k \geq 2$, then there exists a polynomial-time reduction from any (weighted-)Max-$k$-SAT instance with $n$ variables to a $\CVP_p$ instance of rank $n$.
\label{thm:max-k-sat-to-low-rank}

\label{lem:alpha_norm_thing}
For any $\vec{y} \in \{\pm 1\}^k$, weights $\alpha_0, \ldots, \alpha_k \geq 0$, and shift $t^* \in \R$,
\begin{equation*}

\| V\vec{y} - \vec{t}^*\|_p^p = \sum_{j=0}^k \alpha_{k-j}  \sum_{\ell=0}^{k} \binom{|\vec{y}|}{\ell} \binom{k-|\vec{y}|}{j - \ell}  \cdot \big|2|\vec{y}| + 2j - k-4\ell  - t^*\big|^p
\; ,
\end{equation*}
where $V := V(\alpha_0, \ldots, \alpha_k) \in \R^{2^k \times k}$ and $\vec{t}^* := \vec{t}^*(\alpha_0, \ldots, \alpha_k, t^*) $ as above.

In other words, $\| V\vec{y} - \vec{t}^*\|_p^p$ depends only on $|\vec{y}|$, and if $\vec{w} \in (\R^{\geq 0})^{k+1}$ is the vector such that $w_j = \| V\vec{y}' - \vec{t}^*\|_p^p$ for all $\vec{y}' \in \{\pm 1\}$ with $|\vec{y}'| = j$, then
\[
\vec{w} = M_k(p,t^*) \left(
	 \begin{array}{c}
	 \alpha_0 \\
	 \alpha_1\\
	 \vdots \\
	 \alpha_ k
	 \end{array}
\right)
\; ,
\]
where $M_k(p,t^*) \in \R^{(k+1) \times (k+1)}$ is given by 
\begin{equation}
\label{eq:M_def}
M_k(p,t^*)_{i,j} :=  \sum_{\ell=0}^{k} \binom{i}{\ell} \binom{k-i}{j-\ell}  \cdot \big|2i + 2j -k-4\ell - t^*\big|^p
\; .
\end{equation}

\label{lem:top_coeff}
For an integer $k \geq 1$ and an odd integer $p \geq 1$, the function $t^* \mapsto \det(M_k(p,t^*))$, where $M_k(p,t^*)$ is defined as in Eq.~\eqref{eq:M_def}, is a polynomial of degree at most $(k+1)p$ when restricted to the interval $t^* \in [-k,-k+2]$. Furthermore, the coefficient of $(t^*)^{(k+1)p}$ of this polynomial is exactly $2^k(2-2^k)$.

In particular, $t^* \mapsto \det(M_k(p,t^*))$ is a non-zero polynomial of degree $(k+1)p$ on the interval $t^* \in [-k,-k+2]$ for $k \geq 2$.

\label{lem:sum_of_exp}
For any $t^* \in \R$, integer $k \geq 1$, and $p \geq 1$, let 
\begin{equation}
		\label{eq:f_def}
			f_{k,t^*}(p) := \det(M_k(p,t^*))
			\; ,
\end{equation}
where $M_k(p,t^*)$ is as defined in Eq.~\eqref{eq:M_def}. Then, for fixed $k,t^*$, $f_{k,t^*}(p)$ is a Dirichlet polynomial. I.e., there are some real numbers $b_0,\ldots, b_{r}, c_0,\ldots, c_{r} \in \R$ (depending on $t^*$ and $k$) such that
	\begin{equation}
	\label{eq:sum_of_exp}
			f_{k,t^*}(p) = \sum_{i=0}^{r} b_i \exp(c_i p)
	\end{equation}
	for some finite $r$.

\label{lem:cvpp}
For every $p \in [1, \infty)$, there is a pair of polynomial-time algorithms $(P, Q)$ (in analogy to the definition of $\CVPP$) that behave as follows.
\begin{enumerate}
	\item On input an integer $n \geq 1$, $P$ outputs a basis $B_n \in\R^{d\times N}$ of a rank $N$ lattice $\lat_n \subset \R^d$, where $d = d(n) = O(n^2)$ and $N = N(n) = O(n^2)$.
	\item On input a Max-$2$-SAT instance with $n$ variables, $Q$ outputs a target vector $\vec{t} \in \R^d$ and a distance bound $r \geq 0$ such that $\dist_p(\vec{t}, \lat_n) \leq r$ if and only if the input is a `YES' instance.
\end{enumerate}

	\label{cor:infinity!}
For any constant $\eps > 0$ there is no $2^{(1-\eps)n}$-time algorithm for $\SVP_{\infty}$ or $\CVP_{\infty}$ assuming SETH, and there is no $2^{o(n)}$-time algorithm for $\SVP_{\infty}$ or $\CVP_{\infty}$ assuming ETH.
\label{cor:svp-cvp-infinity-seth}

\label{theo1.1}
 Let $\mu$ be a formal complexity measure on ${\cal B}_n$, and let $\mu(f) \geq t$ for some $f \in {\cal B}_n$.
 Then for at least $1/4$ of all functions $g \in {\cal B}_n$, $\mu(g) \geq t/4$.

\label{th:hardness_BCD_approx}
Assuming SETH, for all constants $\delta, c > 0$ there exists a constant $\eps = \eps(\delta, c)$ 
such that the running time of any $(1+\eps)$-approximate algorithm for bichromatic closest pair with mismatches or differences is $\Omega(n^{2-\delta})$. For mismatches the length of the strings is $d = c\log n$, for differences $d = c \log n \log \log n$.

\label{th:pointer_lower_bound_gen}
Consider a set $\mathcal{R}$ of $m$ geometric regions that satisfies the following two conditions for some parameters $\beta$, $t$, and $v$: 
\begin{itemize}
\setlength\itemsep{1pt} 
	\item every point in $\Q$ is contained in at least $t$
regions;
	\item the volume of the intersection of every $\beta$ regions is at most $v$.
\end{itemize}
Then for any pointer-machine data structure, if answering geometric stabbing queries can be done in time $g(m)+\Oh(output)$, where $g$ is an increasing function and $g(m) \le t$, then the space used is $S(m) = \Omega (t v^{-1} 2^{-\Oh(\beta)})$.

\label{lem:regions}
For any $\frac{8}{\sqrt{3}} \sqrt{\log n} \le k = o(\log n)$, there is a set $\D$, and an associated set of regions $\mathcal{R}$ that are the Hamming balls of radius $k$ centered at points in $\D$, such that:
\begin{enumerate}
\item The Hamming distance between each two strings in $\D$ is at least $\lfloor{ k (\frac{1}{4} - \alpha)\rfloor}$;
\item $\D$ has size $\Theta (p_\alpha \cdot(d/k)^{k})$;
\item Each string in $\Q$ belongs to at least $t = \Omega\left( p_\alpha 2^{k/4} {\dbinom{k}{k/4}} (d/k-2)^{k/4} \right)$ regions of $\mathcal{R}$.
\end{enumerate}

 \label{claim:p+s1}
The following properties hold:
\begin{enumerate}
\item $P \oplus S_1$ contains $\delta_1$ set bits.
\item  Among the $2z$ set bits of $S_1 \oplus S_2$, $z+(\delta_1-\delta_2)/2$ must match the bits of $P \oplus S_1$, and $z-(\delta_1-\delta_2)/2$ must mismatch.
\item The number of set bits in $P \oplus S_1$ that correspond to set bits in $S_1$ but not in $P$ is $\delta_1/2-k/4$.
\end{enumerate}

\label{th:dictionary-textindexing-HAM}
Let $0 < \eps < 1$ and $(1+\eps) k < d$. 
If there is a data structure for exact (resp., $(1+\eps)$-approximate) text indexing with $k$ mismatches that for a text of length $n$ has construction time $T_{c} (n)$, query time $T_q (n)$, and space $S(n)$, then there is a data structure for exact (resp., $(1+\eps)$-approximate) dictionary look-up with $k$ mismatches that for a dictionary of $d$-length strings of total length $n$ has construction time $T_{c} (3n + 2d) + \mathrm{poly} (d^{\log d})$, query time $T_q (3n + 2d)$, and space $S(3n + 2d)$.

\label{cor:SETH-text-indexing-HAM}
Assuming SETH, for any constant $\delta > 0$ there exists $d = \Theta(\log n)$, and $k = \Theta(\log n)$ such that 
any data structure for text indexing with $k$ mismatches for a string of length $n$ that can be constructed in polynomial time has query time $\Omega (n^{1-\delta})$.

\label{th:dictionary-textindexing-ED}
Let $0 < \eps < 1$ and $(1+\eps) k < d$. 
Suppose there is a data structure for exact (resp., $(1+\eps)$-approximate) text indexing with $k$ differences that for a text of length $n$ has construction time $T_{c} (n)$, query time $T_q (n)$, and space $S(n)$. Then there is a data structure for exact (resp., $(1+\eps)$-approximate) dictionary look-up with $k$ differences that for a dictionary of total length $n$ has construction time $T_{c} (3n+2d)$, query time $T_q (3n + 2d)$, and space $S(3n+2d)$.

\label{def:OV}
Given two sets $A,B$ of $n$ vectors in $\mathbb \{0,1\}^d$ as input, find a pair of vectors $a\in A$, $b\in B$ such that
$\ip{a}{b}=0$, where the inner product is taken in $\mathbb{Z}$.\footnote{Our definition is slightly different than some of the literature, for example, \cite{chen2019equivalence}, which is searching among pairs inside one set. Those two definitions are equivalent up to constant in complexities.}

Given two sets $A,B$ of $n$ points in $\mathbb R^d$ and a distance measure $\Delta$, find a pair of points $a\in A$, $b\in B$ such that 
\begin{align}
    \Delta(a,b)= \min_{a\in A,b\in B} \Delta(a,b).
\end{align}

Given two sets $A,B$ of $n$ points $\in \mathbb R^d$ and a distance measure $\Delta$, find a pair of points $a\in A$, $b\in B$ such that 
\begin{align}
    \Delta(a,b) \leq (1+\xi)\min_{a\in A,b\in B} \Delta(a,b).
\end{align}

\label{def:fg}
Let $p(n)$ and $q(n)$ be non-decreasing functions of $n$. Problem $\mathsf{P}$ is ($p,q$)-reducible to problem $\mathsf{Q}$, denoted as $(\mathsf{P},p)\leq_{\FG} (\mathsf{Q},q)$, if for every $\epsilon$, there exist $\delta>0$, an algorithm $R$ for solving $\mathsf{P}$ with access to an oracle for $\mathsf{Q}$, a constant $d$, and an integer $k(n)$, such that for every $n\ge 1$, the algorithm $R$ takes any instance of $\mathsf{P}$ of size $n$ and 
\begin{itemize}
    \item $R$ runs in at most $d\cdot (p(n))^{1-\delta}$-time, 
    \item $R$ produces at most $k(n)$ instances of $\mathsf{Q}$ adaptively, that is, the $j$th instance $X_j$ is a function of $\{(X_i,y_i)\}_{1\leq i<j}$ where $X_i$ is the $i$th instance produced and $y_i$ is the answer of the oracle for $\mathsf{Q}$ on instance $X_i$, and 
    \item the sizes $n_i$ of the instances $X_i$ for any choice of oracle answers $y_i$ obeys the inequality
    \begin{align}\label{eq:fgr}
        \sum_{i=1}^{k(n)} (q(n_i))^{1-\epsilon} \leq d\cdot (p(n))^{1-\delta}.
    \end{align}
\end{itemize}

\label{thm:classical_fg}
\begin{align}
    (\mathsf{CNF\text{-}SAT}_{n},2^n)\leq_{\FG} (\OV_{n_1,d_1},n_1^2)\leq_{\FG} (\BCP_{n_2,d_2},n_2^2)\leq_{\FG} (\CP_{n_3,d_3},n_3^2),
\end{align}
where $d_1=\Theta(\log n_1)$, $d_2=\Theta(\log n_2)$ and $d_3=(\log  n_3)^{\Omega(1)}$.

\label{def:oisgood}
Let $X:=\{x_1,\dots,x_n\}$ be an instance of some problem and $\ora_X$ be the corresponding quantum oracle. To realize $\ora_X$, we do not need to write down the whole $X$; instead, we can just design a quantum circuit to realize the mapping 
\begin{align}
    \ket{i}\ket{0} \xrightarrow{\ora_X} \ket{i}\ket{x_i}.
\end{align}

\label{def:qfgr}
Let $p(n)$ and $q(n)$ be nondecreasing functions of $n$. Let $\mathsf{P}$ and $\mathsf{Q}$ be two problems in the quantum query model and $\A_{\epsilon}$ be an $\epsilon$-oracle for $\mathsf{Q}$ with error probability $\epsilon\leq 1/3$. $\mathsf{P}$ is quantum ($p,q$)-reducible to $\mathsf{Q}$, denoted as $(\mathsf{P},p)\leq_{\QFG} (\mathsf{Q},q)$, if for every $\epsilon$, there exits a $\delta>0$, and algorithm $R$ with access to $\A_{\epsilon}$, a constant $d$, and an integer $k(n)$, such that for every $n\ge 1$, the algorithm $R$ takes any instance of $\mathsf{P}$ of size $n$ and satisfies the following: 
\begin{itemize}
    \item $R$ can solve $\mathsf{P}$ with success probability at least $2/3$ in time at most $d\cdot p(n)^{1-\delta}$.
    \item $R$ performs at most $k(n)$ quantum queries to $A_\epsilon$. Specifically, in the $j^{th}$ query, let $\mathbf{X}_j:= \{X_{1,j},X_{2,j},\dots\}$ be a set instances of $\mathsf{Q}$. Then, $R$ realizes the oracles $\{\ora_{X_{1,j}},\ora_{X_{2,j}},\dots\}$ in superposition and applies $A_{\eps}$ to solve the instances.
    \item The following inequality holds.
    \begin{align*}
        \sum_{j=1}^{k(n)}c(\mathbf{X}_j)\cdot q(n_j)^{1-\epsilon} \leq d\cdot p(n)^{1-\delta}, 
    \end{align*}
    where $c(\mathbf{X}_j)$ is the time required for $R$ to realize the oracles $\{\ora_{X_{1,j}},\ora_{X_{2,j}},\dots\}$ in superposition and $n_j := \max_{i}|X_{i,j}|$. 
\end{itemize}

\label{lem:sat_q_ov}
\begin{align}
    (\mathsf{CNF\text{-}SAT}_{n},2^{n/2})\leq_{\QFG} (\OV_{n_1,d_1},n_1),
\end{align}
where $n_1=2^{n/2}$ and $d_1=\Theta(n)$.

\label{lem:qbcp_to_cp}
For $d=\Theta(\log n)$,
\begin{align}
    (\BCP_{n,d},n)\leq_{\QFG} (\CP_{n',d'},n'),
\end{align}
where $n' = n^{O(1)}$ and $d'=(\log n)^{c}$ for some constant $c$ and all points have $\{0,1\}$ entries with the Hamming metric.

\label{def:contact_dim}
For any graph $G=(V,E)$, a mapping $\tau:V\rightarrow \R^d$ is said to realize $G$ if for some $\beta>0$, the following holds for every distinct vertices $u,v$:
\begin{align}
    \|\tau(u)-\tau(v)\|_2  =&~\beta ~ \text{if~} \{u,v\}\in E,\\
    \|\tau(u)-\tau(v)\|_2  > &~\beta ~ \text{otherwise.}\notag
\end{align}
The contact dimension of $G$, denoted by $\mathrm{cd}(G)$, is the minimum $d\in \N$ such that there exists $\tau:V\rightarrow \R^d$ realizing $G$.

 \label{lem:cover}
For any bipartite graph $G(A\dot \cup B, E_G)$ where $|A|=|B|=n$ and $E_G\ne \emptyset$, there exist side-preserving permutations $\pi_1,\dots, \pi_k:A\cup B\rightarrow A\cup B$ where $k\leq \frac{2n^2\ln n}{|E_G|}+1$ such that
\begin{align}
    \underset{i\in [k]}{\bigcup} E_{G_{\pi_i}} = E_{K_{n,n}}.
\end{align}
Moreover, such permutations can be found in $O(n^6\log n)$ time.

\label{lem:ov_q_bcp}
For $d=\Theta(\log n)$, 
\begin{align} 
    (\OV_{n,d},n)\leq_{\QFG} (\BCP_{n,d'},n),
\end{align}
where $d'=\Theta(\log n)$.

\label{thm:zov_map}
Let $b,\ell$ be two sufficiently large integers. There is a classical reduction $\psi_{b,\ell}:\{0,1\}^{b\cdot\ell}\rightarrow \Z^\ell$ and a set $V_{b,\ell}\subseteq \Z$, such that for every $x,y\in \{0,1\}^{b\cdot \ell}$,
\begin{align}\label{eq:zov_iff}
    \ip{x}{y}=0~\Leftrightarrow~\ip{\psi_{b,\ell}(x)}{\psi_{b,\ell}(y)}\in V_{b,\ell}
\end{align}
and
\begin{align}
    0\leq \psi_{b,\ell}(x)_i< \ell^{6^{\log^* (b)}\cdot b}
\end{align}
for all possible $x$ and $i\in [\ell]$. Moreover, the computation of $\psi_{b,\ell}(x)$ takes $\poly(b\cdot \ell)$ time, and the set $V_{b,\ell}$ can be constructed in $O\left( \ell^{O(6^{\log^* (b)}\cdot b)}\cdot \poly(b\cdot \ell) \right)$ time.

\label{lem:ov_2_zov}
For $d=\Theta(\log n)$,
\begin{align}
    (\OV_{n,d}, n)\leq_{\QFG} (\ZOV_{n,d'}, n).
\end{align}
where $d'=2^{O(\log^* n_2)}$.

\label{lem:zov_2_bcp}
For $d=2^{O(\log^* n)}$,
\begin{align}
    (\ZOV_{n,d}, n)\leq_{\QFG} (\BCP_{n,d'}).
\end{align}
where $d'=d^2+2$.

  \label{lemma:cp-ecp}
Let $m$ be the number of bits needed to encode each coordinate as a bit string and $d$ be the dimension.
Given an oracle $\ora$ for $\eCP$, there exists an algorithm $A^{\ora}$  that runs in time and query complexity $O(m+\log d )$ that solves the $\CP$.

\label{def:hypergrid}
Let $d, \epsilon, L>0$. A hypergrid $G_{d,\epsilon,L}$ in the space $[0,L]^d$ consists of all  $\eps$-boxes 
\begin{align}
    g := [a_1,b_1)\times [a_2,b_2)\times \cdots \times [a_d,b_d), 
\end{align}
such that
$b_1-a_1=\cdots =b_d-a_d=\epsilon/\sqrt{d}$ \footnote{The diagonal length of an $\eps$-box is $\epsilon$.}, and $a_i$ is divisible by $\epsilon$ for all $i\in [d]$.

\label{defn:kneighbor}
  Let $\epsilon\in \mathbb{R}$. Let $g_1, g_2$ be two $\eps$-boxes in a hypergrid where $\id(g_1) = (x_1,\dots,x_d)$ and $\id(g_2) = (x'_1,\dots,x'_d)$. We say that $g_1$ and $g_2$ are each other's \emph{$\epsilon$-neighbor} if 
\begin{align}
    \sqrt{\sum_{i=1}^d \|x_i-x'_i\|^2} \leq \epsilon
\end{align}

\label{obs:2step}
Let $p_1,p_2\in [0,L]^d$ be any two distinct points.  
\begin{itemize}
    \item If $p_1$ and $p_2$ are in the same $\epsilon$-box, then $\Delta(p_1, p_2) \leq \epsilon$.
    \item If $\Delta(p_1, p_2)\leq \epsilon$, then $g(\id(p_1))$ must be an $\epsilon$-neighbor of $g(\id(p_2))$. 
\end{itemize}

Let $\mathcal{F}$ be a family of permutations on $f:[n]\rightarrow [n]$. $\mathcal{F}$ is $\epsilon$-approximate $d$-wise independent if for any $x_1,\dots,x_d\in [n]$ and for all $y_1,\dots,y_d\in [n]$, 
\begin{align}
    &\frac{1-\epsilon}{n\cdot(n-1)\cdot (n-d+1)}\leq ~ \Pr\left[\bigwedge_{i=1}^n f_i(x_i) = y_i\right] \leq ~  \frac{1+\epsilon}{n\cdot(n-1)\cdot (n-d+1)}.
\end{align}

\label{lem:ehash}
Let $n$ be an even power of a prime number. For any $t\leq n$, $\epsilon>0$, there exists an $\epsilon$-approximate $t$-wise independent family $\mathcal{F}=\{\pi_j| j\in [R]\}$ of permutations $\pi_j: [n]\rightarrow [n]$ such that: 
\begin{itemize}
    \item $R = O\left( \left(n^{t^2}\cdot \epsilon^{-t}\right)^{3+o(1)}   \right)$; 
    \item given $i,j$, $\pi_j(i)$ can be computed in time $O(t\log^2 n)$.
\end{itemize}

In $\xieBCP$, we are given two sets $A,B$ of $n$ points $\in \mathbb R^d$, a distance measure $\Delta$, and $\xi$. The goal is to do the following
\begin{enumerate}
     \item If there exists a pair of points $a\in A$, $b\in B$ such that $\Delta(a,b) \leq \epsilon$, output the pair $(a,b)$.
     \item If for all pairs of points $a\in A$, $b\in B$, $\Delta(a,b) > (1+\xi)\epsilon$,  returns \textsf{no}.
 \end{enumerate}

\label{lemma:represent}
Let $g$ and $g'$ be $\frac{\xi\epsilon}{2\sqrt{d}}$-boxes. If $g$ and $g'$ are $\epsilon$-neighbors, then for all $p \in g$ and $p' \in g'$, 
  $\Delta(p, p') \leq (1+\xi)\epsilon$.

\label{thm:main_lbs}
    	The following unconditional lower bounds hold:
