\label{def:pac}
        Let $\mathcal{C}$ be a class of Boolean functions. We say that a randomized algorithm $A$ \emph{learns} $\mathcal{C}$ if, when $A$ is given oracle access to ${\rm EX}\cprn{f,\mathcal{D}}$ and inputs $1^n$, $\varepsilon$, and $\delta$, the following holds. For every $n$-variate function $f \in \mathcal{C}$, distribution $\mathcal{D}$ supported over $\bool^n$, and real-valued parameters $\varepsilon > 0$ and $\delta > 0$, $A^{{\rm EX}\prn{f,\mathcal{D}}}(1^n, \varepsilon, \delta)$ outputs  with probability at least $1-\delta$ over its internal randomness and the randomness of the example oracle ${\rm EX}\cprn{f,\mathcal{D}}$ a description of a hypothesis $h:\brkts{0,1}^n\to\brkts{0,1}$ such that
        \begin{align*}
            \Prob_{x\sim\mathcal{D}}\csqbra{f\cprn{x}=h\cprn{x}} \;\geq\; 1-\varepsilon.
        \end{align*}
        The \emph{sample complexity} of a learning algorithm is the maximum number of random examples from ${\rm EX}\cprn{f,\mathcal{D}}$ requested during its execution.

\label{def:fpt-reduction}
	Let $P\subseteq\Sigma^*\times\mathbb N,Q\subseteq\Gamma^*$ be two PPs.
	One says that $P$ is \emph{fpt-reducible} to $Q$, $P\fptreduction Q$, if there exists an $\FPT$-computable function $f\colon\Sigma^*\times\mathbb N\to\Gamma^*\times\mathbb N$ such that
	\begin{itemize}
		\item for all $(x,k)\in\Sigma^*\times\mathbb N$ we have that $(x,k)\in P\Leftrightarrow f(x,k)\in Q$,
		\item there exists a computable function $g\colon\mathbb N\to\mathbb N$ such that for all $(x,k)\in\Sigma^*\times\mathbb N$ and $f(x,k)=(x',k')$ we have that $k'\leq g(k)$.
	\end{itemize}

\label{def:wt}
	For every $t\geq 1$, we let $\W t\dfn [\p\WD\text-\PiForm t]^{\FPT}$. 
	The class $\W t$ forms the $t$-th level of the $\W{}$-hierarchy.

\label{theorem-wsat}
	For every $t\geq 1$ the following problems are $\W t$-complete under fpt-reductions.
	\begin{itemize}
		\item $\p\wsatpos{t,1}{}$ if $t$ is even and  $\p\wsatneg{t,1}{}$ if $t$ is odd.
		\item $\p\wsat{t,d}{}$ for every $t,d\geq 1$.
	\end{itemize}

\label{thm:WT-INC-W2}
There is an $\FO(\subseteq)$-formula $\varphi$ with $\forall\exists$-quantifier prefix for which 
the problem $\p\WTD_\varphi$ is $\W2$-complete.

\label{thm:WT-I}
\begin{enumerate}
\item For all $t\in\mathbb N$ there is an $\IND$-formula $\varphi_t$ such that  $\p\WTD_{\varphi_t}$ is $\W t$-complete.
\item There is  an $\IND$-formula  $\varphi_w$ such that  $\p\WTD_{\varphi_w}$ is $\W\Ptime$-complete.
\item There is a $\IND$-sentence $\varphi$, such that the problem $\p\WTD_\varphi$ is $\para\NP$-complete.
\item $[\p\WTD\text-\IND]^{\FPT}=\para\NP$.
\end{enumerate}

The following are equivalent:
\begin{enumerate}
    \item $\cc{\Sigma_2E}^A \not\subset$ i.o.-$\cc{SIZE}^A[2^{\Omega(n)}]$ for every oracle A;
    \item for $m = 2^{\Omega(n)}$, the $\cc{MissingString}$ problem can be solved by a uniform family of size-$2^{\poly(n)}$ depth-3 $\cc{AC}^0$ circuits.
