    \begin{itemize}
        \item For every $x \in X$, there are at least $m$ different $y \in Y$ with $(x, y) \in R$,
        \item for every $y \in Y$, there are at least $m'$ different $x \in X$ with $(x, y) \in R$,
        \item for every $x \in X$ and $i \in [n]$, there are at most $\ell$ different $y \in Y$ such that $(x, y) \in R$ and $x_i \neq y_i$,
        \item for every $y \in Y$ and $i \in [n]$, there are at most $\ell'$ different $x \in X$ such that $(x, y) \in R$ and $x_i \neq y_i$.
