{theorem}{maintheorem}   \label{thm:removing_algebraicity}

Let $\struct{B}$ be a countable structure over a finite relational signature. Then 
\begin{enumerate}
    \item \label{item:Bremovingalgebraicity} $\ordblowup{\struct{B}}$ is a countably infinite structure without algebraicity over a finite relational signature.
    \item \label{item:Bomegacat} If $\struct{B}$ is $\omega$-categorical, then so is $\ordblowup{\struct{B}}$.
    \item \label{item:BhomogRamsey} If $\struct{B}$ is homogeneous, then so is $\ordblowup{\struct{B}}$. In this case, $\struct{B}$ is Ramsey if and only if  $\ordblowup{\struct{B}}$ is Ramsey.
    \item \label{item:Bfinbounded} If $\struct{B}$ is finitely bounded, then so is $\smash{\ordblowup{\struct{B}}}$.
\end{enumerate}

Moreover, if $\struct{A}$ is a non-contractible reduct of $\struct{B}$, then 
\begin{enumerate}\addtocounter{enumi}{4}
    \item \label{item:ACSPinj} $\blowup{\struct{A}}$ is a non-contractible CSP-injective reduct of $\ordblowup{\struct{B}}$.
    \item \label{item:ADatalog} $\CSP(\struct{A})$ and $\CSP\blowup{\struct{A}}$ are Datalog-interreducible.
    \item \label{Amodelcomplcore} If $\struct{A}$ is $\omega$-categorical, then so is $\blowup{\struct{A}}$, and $\struct{A}$ is a  model-complete core if and only if  $\blowup{\struct{A}}$ is. 
    \item \label{AppconstructK3}  If the number of orbits of $d$-tuples of $\struct{A}$  grows slower than $2^{2^{d}}$, then $\struct{A}$ pp-constructs $\struct{K}_3$ if and only if $\blowup{\struct{A}}$ pp-constructs $\struct{K}_3$. 
\end{enumerate}

{corollary}{binaryInj}  \label{cor:binaryInj} 
  Let $\struct{A}$ be a relational structure that 
  does not pp-construct $\struct{K}_3$. Then $\blowupi{\struct{A}}$ has a binary injective polymorphism.

{theorem}{sandwichthmbasic}   \label{thm:main_theorem_sandwiches_basic}  
Let $\struct{A}$ be a reduct of a countable finitely bounded homogeneous structure $\struct{B}$.

Then there exists a reduct $\struct{A}'$ of a countable finitely bounded homogeneous structure $\struct{B}'$ such that 
$\struct{A}$ and $\struct{B}$ are pp-bi-interpretable with $\struct{A}'$ and $\struct{B}'$, respectively, and such that for all  $n\in \mathbb{N}$, there exists a finite PCSP template $(\struct{S}_1,\struct{S}_2)$ and gadget-reductions $\mathcal{J}$ and $\mathcal{J}'$ from $\CSP(\struct{A})$ to $\CSP(\struct{A}')$ and vice versa such that
\begin{enumerate} 
  \item \label{item:sandwichbasic1} $\struct{A}'$ is a cheese for $\PCSP(\struct{S}_1,\struct{S}_2)$;   thus, $\PCSP(\struct{S}_1,\struct{S}_2)$ reduces to $\CSP(\struct{A})$ via  $\mathcal{J}'$;
  \item \label{item:sandwichbasic2} $\mathcal{J}$ is correct as a reduction from $\CSP(\struct{A})$ to  $\PCSP(\struct{S}_1,\struct{S}_2)$ when limited to instances $\struct{X}$ with the property that $\struct{X}$ homomorphically maps to $\struct{A}$ if and only if it homomorphically maps to a substructure of $\struct{A}$ of domain size $\leq n$.  
\end{enumerate}

{theorem}{tpppconstruct}   \label{thm:temporal_phylo_pp_constr}  
 There is a tractable phylogeny CSP that:

\begin{enumerate}  
    \item \label{item:finite_reason_1} pp-constructs a finite-domain PCSP inexpressible in FPC; 
    \item \label{item:finite_reason_2} does  not pp-construct any finite-domain CSP inexpressible in FPC.
\end{enumerate}

{lemma}{pseudocyclic}  
\label{lemma:pseudocyclic}  
 Let $\struct{A}$ be a reduct of a linearly ordered structure $\struct{B}$ and $\struct{S}$ a finite substructure of $\struct{A}$. If $f\in \Pol(\struct{S},\struct{A})$ is pseudo-cyclic modulo $\Aut(\struct{B})$, then $f$ is cyclic.

