{theorem}{subcubeTheorem}
\label{thm:subcube-inverse-of-dense}
There exists an algorithm such that for $n, U > 3$, $\epsilon, \delta \in (0,1)$, and any invertible RDDL matrix $\LL \in \mathbb{R}^{n \times n}$ with integer entries in $[-U, U]$, the algorithm, with probability at least $1 - \delta$, computes a matrix $\ZZ$ such that $\ZZ \approxbar_{\epsilon} \LL^{-1}$ using $\Otil\big(n^{\omega + 0.5} \log(U \epsilon^{-1}) \log(\epsilon^{-1} \delta^{-1})\big)$ bit operations in expectation.

{theorem}{subcubeTheoremSparse}
\label{thm:subcube-inverse-of-sparse}
There exists an algorithm such that for $n, U > 3$, $\epsilon, \delta \in (0,1)$, and any invertible RDDL matrix $\LL \in \mathbb{R}^{n \times n}$ with $m$ nonzero integer entries in $[-U, U]$, the algorithm, with probability at least $1 - \delta$, computes a matrix $\ZZ$ such that $\ZZ \approxbar_{\epsilon} \LL^{-1}$ using $\Otil\big(m n^{1.5 + o(1)} \log^{O(1)}(U \kappa\delta^{-1}\epsilon^{-1})\big)$ bit operations.

\label{ex:norm-wise-bad}
Let $\vv=(10^{15},1)$, $\widetilde{\vv}=(10^{15}(1+\epsilon),0)$, and $\epsilon=10^{-5}$. Note that the second entry of $\vv$ and $\widetilde{\vv}$ are very different from each other.
Then
\begin{align}
\frac{\norm{\widetilde{\vv} - \vv}_1}{\norm{\vv}_1} = \frac{\epsilon\cdot 10^{15}+1}{10^{15}+1} = \frac{10^{10}+1}{10^{15}+1} \approx 10^{-5}.
\end{align}
This means that $\widetilde{\vv}$ approximates $\vv$ in a norm-wise manner, but entry-wise $\vv$ and $\widetilde{\vv}$ are very different vectors.
Therefore a bound on the norm does not necessarily provide bounds for the entries. For the norm bound to give guarantees for the entries, we would need to have $\epsilon \approx \frac{\vv_{\min}}{\vv_{\max}}$, where $\vv_{\min}$ and $\vv_{\max}$ are the smallest and largest entry of $\vv$ in terms of absolute value, respectively.

{lemma}{invertibleRDDL}
\label{lemma:rddl-invertible}
An RDDL matrix $\MM \in \R^{n \times n}$ is invertible if and only if its associated graph is connected to the dummy vertex.

\label{cor:sddm-inverse-bound}
   Let $\LL$ be an $n \times n$ invertible SDDM matrix with integer entries in $[-U, U]$, then
   \begin{align*}
       \| \LL^{-1} \|_2 = \frac{1}{\lambda_{\min}(\LL)} \le n^2.
   \end{align*}

\label{fact:approx}
   For nonnegative scalars $a, b, c$, and $d$, the following holds.
   \begin{itemize}
       \item If $a \approx_{\epsilon_1} b$ and $b \approx_{\epsilon_2} c$, then $a \approx_{\epsilon_1 + \epsilon_2} c$.
       \item If $a \approx_{\epsilon} c$ and $b \approx_{\epsilon} d$, then $a + b \approx_{\epsilon} c + d$.
       \item For $0 < \epsilon < 1/2$, if $(1-\epsilon) a \le b \le (1+\epsilon) a$, then $a \approx_{1.5\epsilon} b$.
   \end{itemize}
   The above properties generalize to vectors and matrices for entrywise approximations.

\label{lemma:at-least-on-large-entry}
Let $\MM \in \R^{n\times n}$ be an invertible RDDL matrix with integer entries in $[-U,U]$ and $\bb$ be a nonnegative vector.
There exists $i\in[n]$ with $(\MM^{-1} \bb)_i \geq \frac{1}{n U}\norm{\bb}_1$.

[Guarantees of the Threshold Decay framework] \label{lemma:ThresDec-guarantees}
   Given $\epsilon \in (0,1)$, integer $T\geq 10$, $U \ge 2$, an $n \times n$ invertible RDDL matrix $\LL$ with integer entries in $[-U, U]$, and a nonnegative vector $\bb$ with integer weights in $[0,U]$, let $\xxbar := \LL^{-1} \bb$ denote the exact solution vector, \callalg{ThresholdDecay} has the following guarantees for all $t \in [0, T]$: 
   \begin{enumerate}
       \item  \label{induction:bound-b}
           $
           \norm{\widehat{\bb}^{(t)}}_1 \leq \frac{1}{(nU)^{t}} \norm{\bb}_1
           $.
           Moreover, if $t > 0$, 
           $\norm{\bbhat^{(t)}}_1 \leq \frac{1}{(nU)} \norm{\bbhat^{(t-1)}}_1
           $.
       \item  \label{induction:xtil-approx}
           $\widetilde{\xx}^{(t)} \approxbar_{\epsilon t / (4T)} \xxbar_{[n] \setminus S^{(t)}}$. Note that we define $\widetilde{\xx}^{(0)}$ to be a zero dimensional vector.
       \item \label{induction:bound-xbar}
           For all $i \in S^{(t+1)}$, $\xxbar_i < \frac{1}{(nU)^{2}} \| \bbhat^{(t)} \|_1 \le \frac{1}{(nU)^{t+2}} \norm{\bb}_1$.
   \end{enumerate}

 [Correctness of the Threshold Decay framework]\label{thm:ThresDec-correctness}
Given $\epsilon \in (0,1)$, integer $T\geq 10$, $U \ge 2$, an $n \times n$ invertible RDDL matrix $\LL$ with integer entries in $[-U, U]$, 
and a nonnegative vector $\bb$ with integer weights in $[0,U]$, \callalg{ThresholdDecay} produces a vector $\xxtil$ and a set $A \subseteq [n]$ such that $\xxtil$ has support $A$, with the following properties hold:  
    \begin{itemize}
        \item For any $i \in [n]$ with $(\LL^{-1} \bb)_i \geq (nU)^{-(T+1)} \norm{\bb}_1$, we have $i \in A$. 
        \item Our output is an entrywise $\exp(\eps)$-approximation on $A$, i.e.,  $\xxtil_A \approxbar_{\epsilon} (\LL^{-1} \bb)_A$.
        \item Specifically, when $T = n$, we have $\xxtil \approxbar_{\epsilon} \LL^{-1} \bb$.
    \end{itemize}

\label{lemma:b-bound}
   In \callalg{ThresholdDecay}, for any integer $t \in [0, T-1]$, let 
   \[
   \bbbar^{(t+1)} := 
       \bb_{S^{\left( t +1 \right)}}
       -
       \LL_{S^{\left( t +1 \right)}, [n] \setminus S^{(t+1)}}
       \xxtil^{\left( t+1 \right)}
   \]
       denote the RHS of Step \ref{ThresDec:updateB}, the entries are either zero or bounded by 
   \begin{align*}
       \frac{1}{4(nU)^2} \norm{\widehat{\bb}^{(t)}}_1
       \le 
       \bbbar^{(t+1)}_i
       \le
       \frac{2}{n^2 U} \norm{\widehat{\bb}^{(t)}}_1
   \end{align*}
   for all $i \in S^{(t+1)}$. Furthermore, since $\bbhat^{(t+1)} \approx_{(\eps/8T)} \bbbar^{(t+1)}$, we have for all $i \in S^{(t+1)}$, 
   \begin{align*}
       \frac{1}{8(nU)^2} \norm{\widehat{\bb}^{(t)}}_1
       \le 
       \bbhat^{(t+1)}_i
       \le
       \frac{4}{n^2 U} \norm{\widehat{\bb}^{(t)}}_1.
   \end{align*}

\label{lemma:solution-of-neighbors}
Let $\LL$ be an invertible SDDM matrix with integer weights in $[-U,U]$.
Let $i,j\in[n]$ such that $\LL_{ij} \neq 0$. Then $\LL^{-1} \ee^{(i)} \leq nU \cdot \LL^{-1} \ee^{(j)}$.

\label{lemma:zero_out_error}
Let $\LL \in \R^{n\times n}$ be an invertible SDDM matrix with weights in $[-U, U]$,
$\bb \in \R^{n}$, and $\xx = \LL^{-1} \bb$. Let $\theta >0$ and $C \subseteq [n]$ such that $\xx_{C} \leq \theta$. Moreover 
let $\yy$ be the solution obtained by discarding entries in $C$ and
solving on the remaining entries, $F:=[n] \setminus C$, i.e.  
\begin{align*}
    \yy := \Mbegin
        \yy_{F} \\
        \yy_{C}
    \Mend 
    =
    \Mbegin
        \LL_{F, F}^{-1} \bb_{F} \\
        \mathbf{0}
    \Mend.
\end{align*}
Then
\[
\norm{
    \yy
    -
    \xx
}_{2}
\leq
n^3 U \theta.
\]

For $k \ge 1$, a vector $\pp \in \R^n$ is called a $k$-prediction for vector $\vv \in \R^n$ if for all $i \in [n]$, 
\begin{align*}
    \pp_i / (nU)^k \le \vv_i \le \pp_i.    
\end{align*}

\label{lemma:entrywise-SDDM-solver-with-prediction}
    Let $\LL, \bb, \eps$ be the inputs that satisfy the assumptions of \Cref{thm:ThresDec-correctness} and $\LL$ has $m$ nonzero entries. Given a vector $\pp$ that is a $k$-prediction vector for $\LL^{-1} \bb$, \callalg{PredictiveSDDMSolver} runs with
    $\Otil( k(m+n) \log^2 (U \eps^{-1} \delta^{-1}))$ bit operations and with probability $1-\delta$ outputs vector $\xxtil$ such that $\xxtil \approxbar_{\epsilon} \LL^{-1} \bb$.

\label{lemma:solution-of-neighbors-single-system}
Let $\LL$ be an $n\times n$ invertible SDDM matrix with integer weights in $[-U,U]$, and $\bb$ be a nonnegative vector of dimension $n$.
For any $i,j\in[n]$ with $\LL_{ij} \neq 0$, we have
\begin{align*}
    (nU)^{-1} \cdot (\LL^{-1} \bb)_j \le (\LL^{-1} \bb)_i \leq nU \cdot (\LL^{-1} \bb)_j.
\end{align*}

For an undirected graph $G = (V, E)$, let $F \subseteq S \subseteq V$, the (inner) boundary of $F$ with respect to the subgraph $S$ is
\begin{align*}
    \partial_S F := \{ v \in F : \exists w \in (S \setminus F), s.t., (v,w) \in E\}.
\end{align*}
For an $n \times n$ undirected matrix $\LL$, we define boundary with respect to the underlying graph $G = ([n], E)$ where $E = \{ (i,j) : \LL_{ij} \neq 0\}$. That is, for $F \subseteq S \subseteq [n]$,
\begin{align*}
    \partial_S F := \{ i \in F :  \exists j \in (S \setminus F), s.t., \LL_{ij} \neq 0\}.
\end{align*}
We write $\partial F := \partial_V F$ (or $\partial_{[n]} F$) when $S = V$ (or $S = [n]$).

\label{lemma:boundary-upper-bound}
   Let $\LL$ be an $n\times n$ invertible SDDM matrix with integer weights in $[-U,U]$, and $\bb$ be a nonnegative vector of dimension $n$, we denote $\xx := \LL^{-1} \bb$. Let $F$ be a set with $F \supseteq \{i \in [n] : \bb_i > 0 \}$, and let $C := [n] \setminus F$. Define the maximum entry of the reduced system in $F$ on $\partial F$, 
   \begin{align*}
       \Delta := \max_{u \in \partial F} (\LL_{F, F}^{-1} \bb_F)_u
   \end{align*}
   where we define the maximum to be zero if $\partial F = \emptyset$, then for any $i \in C$, we have $\xx_i \le n^3U \Delta$.

\label{lemma:find-near-pairs-with-fmm}
There exists an algorithm that
given any directed graph $G=(V,E,w)$ with $|V|=n$ and nonnegative integer $k$ computes the set of pairs $(i,j)$ with $d^{G}(i,j) \leq 2^k$ with $\Otil(n^{\omega})$ bit operations.

\label{lemma:all-close-pairs}
There exists an algorithm such that for any $\epsilon, \delta \in (0,1)$ and $n, U > 3$, given any invertible RDDL matrix $\LL \in \mathbb{R}^{n \times n}$ with integer entries in $[-U, U]$, its associated graph $G = ([n+1], E, w)$, and a random subset $S \subseteq [n]$ where each $i \in [n]$ is independently included in $S$ with probability $1/\sqrt{n}$, the algorithm—with probability at least $1 - \delta$ and using $\Otil\big(n^{\omega + 0.5} \log(U) \log(\delta^{-1} \epsilon^{-1})\big)$ bit operations—computes $\exp(\epsilon)$-approximations of $(\LL_{\overline{S}, \overline{S}}^{-1})_{g_i g_j}$ for all pairs $i, j \in \overline{S}$ satisfying $d^{G(\overline{S})}(i, j) \leq 2^k$, where:
\begin{itemize}
\item $\overline{S} = [n] \setminus S$,
  \item $2^k$ is the smallest power of two greater than $\sqrt{n} \log(n^2 \epsilon^{-1} \delta^{-1})$, and
  \item $i \mapsto g_i$ is the unique monotone mapping from $\overline{S}$ to $[|\overline{S}|]$.
\end{itemize}

\label{lemma:sparse-near-pair-compute}
There exists an algorithm such that for any $\epsilon, \delta \in (0,1)$ and $n, U > 3$, given any invertible RDDL matrix $\LL \in \mathbb{R}^{n \times n}$ with $m$ nonzero integer entries in $[-U, U]$, its associated graph $G = ([n+1], E, w)$, and a random subset $S \subseteq [n]$ where each $i \in [n]$ is independently included in $S$ with probability $1/\sqrt{n}$, the algorithm, with probability at least $1 - \delta$ and using $\Otil(m n^{1.5+o(1)}\log^{O(1)}(U \kappa\delta^{-1}\epsilon^{-1}))$ bit operations, computes $\exp(\epsilon)$-approximations of $(\LL_{\overline{S}, \overline{S}}^{-1})_{g_i g_j}$ for all pairs $i, j \in \overline{S}$ satisfying $d^{G(\overline{S})}(i, j) \leq 2^k$, where:
\begin{itemize}
\item $\kappa$ is the condition number $\LL$,
\item $\overline{S} = [n] \setminus S$,
  \item $2^k$ is the smallest power of two greater than $\sqrt{n} \log(n^2 \epsilon^{-1} \delta^{-1})$, and
  \item $i \mapsto g_i$ is the unique monotone mapping from $\overline{S}$ to $[|\overline{S}|]$.
\end{itemize}

\label{lemma:entries-of-inverse}
Let $\MM \in \R^{n\times n}$ be an RDDL matrix and $G=([n+1],E,w)$ be the graph associated with $\MM$.
For $i,j \in [n]$ with $i\neq j$, let $G^{(i,j)}$ be the graph with vertex set $[n+1] \setminus \{j\}$ obtained from $G$ as the following: (1) for all $k \in [n] \setminus \{i,j\}$, the weight of the edge from $k$ to $i$ is replaced by the weight of the edge from $k$ to $j$ plus the weight of the edge from $k$ to $n+1$; (2) the weight of the edge from $i$ to $n+1$ is replaced with the weight of the edge from $j$ to $i$;
(3) for all $k \in [n] \setminus \{i,j\}$, the weight of the edge from $i$ to $k$ is replaced by the weight of the edges from $j$ to $k$;
(4) for all $k \in [n] \setminus \{i,j\}$, the weight of the edge from $k$ to $n+1$ is replaced by the weight of the edge from $k$ to $i$;


Moreover for $i \in [n]$, let $G^{(i,i)}$ be the graph with vertex set $[n+1] \setminus \{i\}$ obtained from $G$ as the following: for all $k \in [n] \setminus \{i\}$, add the weight of the edge from $k$ to $i$ to the weight of the edge from $k$ to $n+1$.

Then if $\MM$ is invertible, for $i,j \in [n]$,
\[
\MM^{-1}_{ji} = \frac{\text{weighted number of spanning trees in $G^{(i,j)}$ oriented towards vertex $n+1$}}{\text{weighted number of spanning trees in $G$ oriented towards vertex $n+1$}}\,.
\]

\label{def:hitting-time}
    For a (directed or undirected and weighted or unweighted) graph $G=(V,E)$ and $s,t\in V$, we define the hitting time of $s$ to $t$, as the expected number of steps for a random walk starting from $s$ to reach $t$ for the first time. 
    More formally, let 
    \begin{align}
        W_{st}=\{w=(v_1,\ldots,v_k): k\in\N, \forall i\in [k], \forall j\in[k-1], v_i\in V, (v_j,v_{j+1}) \in E,v_j\neq t, v_1=s, v_k = t\},
    \end{align}
    be the set of all possible walks from $s$ to $t$ that visit $t$ only once. We set the probability of the random walk $w=(v_1,\ldots,v_k)$ equal to $\pr(w):= \pr(v_1,v_2) \pr(v_2,v_3) \cdots \pr(v_{k-1},v_k)$, where $\pr(u,v)$ is the probability of going from vertex $u$ to $v$ in one step. 
    We also denote the size of $w$ with $|w|$ which is the number of edges traversed in $w$, i.e., for $w=(v_1,\ldots,v_k)$, $|w|=k-1$. Then the hitting time of $s$ to $t$ is
    \begin{align}
        H(s,t):=\sum_{w\in W_{st}} \pr(w) \cdot |w|.
    \end{align}
    If there is no path from $s$ to $t$, i.e., $W_{st}=\emptyset$, then $H(s,t)=\infty$.

\label{def:altCQ}
    $\altCQ[k]$ refers to the class of circuits that can be decomposed into a product of $k+1$ circuits, starting with a Clifford circuit and alternating between Clifford and $\QNCZ$ circuits. More formally, a circuit family $\{C_n\}$ is in $\altCQ[k]$ if there exists a constant $d\in \NN$ such that for each $n\in \NN$, $C_n$ acts on $n$ qubits and can be written as the product $Q_k Cl_{k-1} Q_{k-2} \dots Cl_0$ where each $Q_j$ is a depth-$d$ circuit with two qubit gates, and each $Cl_j$ is a Clifford circuit. 
    $\altQC[k]$ is defined similarly but with the first circuit applied being a $\QNCZ$ circuit.

\label{thm:robust-cliffqnc-lb}
    Suppose $\psi$ is an $n$ qubit state satisfying:
    \begin{enumerate}
        \item The mutual information between any pair of qubits is at least $\alpha$
        \item  The mutual information between any two disjoint regions of size $s$ is at most $\beta$.
        \end{enumerate}
    for some constants $\alpha, \beta$ with $k < \alpha \leq \beta < k+ 1$, and integers $k\geq 0$, $s\geq 1$.  
If a Clifford circuit $C$ and a $\QNC$ circuit $U$ approximately prepares $\ket{\psi}$ to within trace distance $\eps$, then $U$ has depth at least $ \Omega\pbra{\log\min\cbra{ s , 1/\eps}}$. In particular, when $s = \omega(1)$ this state can not be prepared by $\altCQ[1]$ to within $o(1)$ error.

\label{thm:informal:cat-state-gluing-lb}
   Suppose $U\in \unitaries[2n]$ is a $2n$ qubit quantum circuit for $n\geq 2$ such that 
   \begin{align}
       \ket{\bCATn[2n]{\alpha}} = U \ket{\bCATn[n]{\beta}} \ot \ket{\bCATn[n]{\beta}}  \label{eq:catstate-gluing}
   \end{align}
   For some $\alpha, \beta \in [0,1]$. 
   If $H(\alpha) \neq 2 H(\beta)$, then $U$ requires depth $\Omega(\log n)$. Furthermore, if $\alpha$ and $\beta$ satisfy $\abs{H(\alpha) - 2H(\beta)} = \Omega(1)$ then even $\eps$-approximately preparing the state requires depth $\Omega(\log \min \{n , 1/\eps\})$.

\label{conj:nltsCQ}
   There exists a fixed constant $\eps > 0$, an explicit family of $O(1)$-local Hamiltonians $\{H^{(n)}\}$ with ground-energy $0$, where $H^{(n)} = \sum_{i =1}^m h^{(n)}_i$ acts on $n$ qubits and $m = \Theta(n)$ such that for any family of states $\{\psi_n\}$ satisfying 
   $\Tr(H^{(n)} \psi_n) < \eps n$, the state $\psi_n$ can not be prepared by an $\altCQ[1]$ circuit.

\label{fact:lightcone-on-state}
   Consider the circuit $U$ on $n$ qubits, and some subset $S\subseteq[n]$. For any $n$-qubit quantum state $\rho$
   \begin{align}
       \tr_{S^c} U \rho U^\dagger = \tr_{S^c} U (\rho_{\blc(S)} \otimes I_{\blc(S)^c})U^\dagger = \tr_{\blc(S) \setminus S} \cktblc[U]{S}\rho_{\blc(S)}\cktblc[U]{S}^\dagger \label{eq:state-lc-def}.
   \end{align}

\begin{align*}
    \MI[\rho]{A}{B} := \EE(\rho_A) + \EE(\rho_B) - \EE(\rho_{AB})
\end{align*}
For an $n$-qubit state $\rho$, the \QMI between two regions takes a real value in $[0,n]$.

The $n$-qubit Pauli group, denoted $\paulis[n]$, contains elements that are a tensor product of $n$ single-qubit Pauli matrices. 
\[\paulis[n] := \cbra{i^b \sigma_1 \ot \dots \ot \sigma_n : b \in \{0, 1, 2, 3\},\  \sigma_1, \dots, \sigma_n \in \{I, X, Y, Z\} }\]
Here, $I$ is the identity and $X, Y, Z$ are the single-qubit Pauli matrices.
\begin{align*}
    I = \begin{pmatrix}
        1 & 0 \\ 0 & 1 
    \end{pmatrix}, \quad
    X = \begin{pmatrix}
        0 & 1 \\ 1 & 0
    \end{pmatrix},
    \quad
    Y = \begin{pmatrix}
        0 & -i \\ i & 0
    \end{pmatrix},
    \quad
    Z = \begin{pmatrix}
        1 & 0 \\ 0 & -1
    \end{pmatrix}
\end{align*}

\label{lem:mi-lightcones}
    If $\psi = U \psi' U^\dagger$ and $\flc_U(\blc_U(i)) \cap \flc_U(\blc_U(j)) = \emptyset$ then
    \begin{align}
        \MI[\psi]{i}{j} \leq \ \MI[\psi']{\blc(i)}{\blc(j)} \leq\  \MI[\psi]{\flc(\blc(i))}{\flc(\blc(j))}.
    \end{align}

\label{claim:mi-near-stabilizer}
    If $\tnorm{\rho - \varphi} \leq \eps$ and $\varphi$ is a stabilizer state, then for each $A, B \in [n]$ disjoint subsets of qubits ($A \cap B = \emptyset$) there exists an integer $k$ such that 
    \begin{align}\abs{\MI[\rho]{A}{B} -k } = \abs{\MI[\rho]{A}{B} - \MI[\varphi]{A}{B} }  \leq 2 \eps \cdot (|A| + |B|) + 3H(\eps). \end{align}
    Where $H(\eps) = -\eps \log \eps - (1-\eps)\log(1-\eps)$ is the binary entropy function.

\label{claim:lb-mi-dist}
    Suppose $\psi = U \psi' U^\dagger$. If there exists $i,j \in [n]$ with nonintersecting backwards-forwards lightcones $\flc(\blc(i)) \cap \flc(\blc(j)) = \emptyset$ with respect to $U$, then there exists an integer $\ell$ such that
    \begin{align}
        \min_{k\in \ZZ}\abs{ \MI[\psi']{\blc(i)}{\blc(j)}  -k}  \geq \min \cbra{ \MI[\psi]{i}{j} - (\ell-1) \ ,\  \ell - \MI[\psi]{\flc\blc(i)}{\flc\blc(j)} }.
    \end{align}

\label{lem:intermediate:robust-lb}
    Suppose $n$-qubit state $\phi$ is prepared by a unitary $U$ acting on a stabilizer state $\phi^S$, $\phi = U \phi^S U^\dagger$. And suppose $\psi$ is an $n$ qubit state and $i\neq j \in [n]$ satisfying:
    \begin{enumerate}
        \item $\MI[\psi]{i}{j} \geq \alpha$, and
        \item $\MI[\psi]{\dlc{i}}{\dlc{j}} \leq \beta$
    \end{enumerate}
    for some $0 \leq \alpha \leq \beta \leq 1$. Let $\eps = \tnorm{\psi - \phi}$. If  $\eps \leq \pbra{\frac{\min\cbra{\alpha, 1- \beta}}{1 + 3 e}}^{\ln(4)}$, then $\dU \geq \Omega(\log(1/\eps))$.

\label{thm:robust-lb-with-params}
    Suppose $\psi$ is an $n$ qubit state satisfying:
    \begin{enumerate}
        \item \label{item:lem:MI-qubit-lowerbound} For each $i\neq j \in [n]$, $\MI[\psi]{i}{j} \geq \alpha$, and
        \item \label{item:lem:MI-subset-upperbound} For each $A, B\subseteq [n]: A\cap B = \emptyset$ and  $|A|, |B| < s$, $\MI[\psi]{A}{B} \leq \beta$.
    \end{enumerate}
    For some $k < \alpha \leq \beta < k+1$, and integers $k\geq 0, s \geq 1$. Suppose $\phi$  is an $n$-qubit state prepared by an $(n+a+a')$-qubit unitary $U$ as $\phi\ot \varphi\ot \proj{0^{a'}} = U \phi^S U^\dagger$ for an $(n+a+a')$-qubit stabilizer state $\phi^S$ and an $a$-qubit auxiliary state $\varphi$. Let $\eps = \tnorm{\psi - \phi}$. At least one of the following is true:
    \begin{enumerate}[(a)]
        \item \label{item:lem:Heps-bound} $\eps > \pbra{\frac{\min\cbra{\alpha, 1- \beta}}{1 + 3 e}}^{\ln(4)}$, or
        \item \label{item:lem:logdepth} $\dU \geq \frac{1}{4}\log(s)$, or 
        \item \label{item:lem:log-anc-bound} $\dU \geq \log(n/a)$, or 
