For an $n$-qubit pure quantum state $\ket{\psi}\in \CC^{2^n}$, we define $\calC_\ell(\psi)\sse \CC^{2^n}$ to be the subspace spanned by all pure states that are $\ell$-locally equivalent to $\psi$.
    \begin{align}
    \calC_\ell(\psi) := \textsf{span}\{\ket{\phi}:\phi_A = \psi_A \ \text{for each} \ A \sse [n] \ \text{with} \ |A|\leq \ell\}
\end{align}

    The \emph{distance} of a subspace $\calC$, denoted $d(\calC)$, is defined as the maximum integer $d$ such that for each region $A\sse [n]$ of size $|A|< d$, there exists a CPTP map $\textsf{Rec}$ that can recover any state in $\calC$
\begin{align}
    \textsf{Rec}(\Tr_A \phi) = \phi, && \text{for each} \ \ket{\phi} \in \calC
\end{align}
For notational convenience, the distance of $\calC_\ell(\phi)$ is denoted $d_\ell(\phi) = d(\calC_\ell(\phi))$.

Consider pairwise commuting projectors $\Pi_1, \dots \Pi_m$. Let the codespace $\calC$ be the $1$-eigenspace of $\Pi= \prod_i \Pi_i$. For each subset of qubits $M \sse [n]$, let $\partial(M)$ be the set of all $a\in [n]$ such that there is some $\Pi_i$ acting nontrivially on both $a$ and some $b \in M$, and let $\partial^+(M) = \partial(M) \setminus M$. If $M$ and $\partial^+(M)$ are both correctable regions, then there exists a unitary operator $U_{\partial(M)}$ acting only on $\delta(M)$ such that
\begin{align}
    U_{\partial(M)} \Pi U_{\partial(M)}^\dagger = \proj{\phi_M} \otimes \Pi_{M^c}.
\end{align}

\label{thm:le-code-contained-in-commproj-code}
    Suppose $\ket{\psi} = U \ket{\phi}$ for stabilizer state $\ket{\phi}$ and circuit $U$ with blowup $B$. For each integer $\ell \geq 1$, if $B < \pbra{d_\ell(\psi)/\ell}^{1/2}$
    then $\calC_\ell(\psi) = U \Cstab[B \ell](\phi)$.

\label{claim:code-blowup-containment}
   Suppose $\ket{\phi_1} = U \ket{\phi_0}$ for circuit $U$ with blowup $B$. Then
   \[ \calC_{B^2 \ell}(\phi_1)  \sse U \calC_{B\ell}(\phi_0) \sse  \calC_{\ell} (\phi_1) \]
   Furthermore, if $d_{\ell}(\phi_1) > B^2 \ell$ then 
   \begin{align*}
       \calC_\ell(\phi_1) = U \calC_{B\ell}(\phi_0).
   \end{align*}

\label{claim:distance-preserved}
    \begin{align}
       \frac{1}{B} d(U \calC) \leq d(\calC) \leq B \cdot d(U \calC) \label{eq:code-evolution-distance-relations}
    \end{align}
    Suppose $\ket{\phi_1} = U \ket{\phi_0}$ for circuit $U$ with blowup $B$. Then 
    \begin{align}
        \frac{1}{B} d_{\ell}(\phi_1) \leq d_{B\ell}(\phi_0) \leq B \cdot d_{B^2 \ell}(\phi_1). \label{eq:distance-bounds-lecodes}
    \end{align}

We say a subspace $\calC$ is $(\eps,\delta, \ell)$-robust for $0 \leq \eps \leq \delta \leq 1$ and integer $\ell\in [n]$ if for each $n$-qubit state $\ket{\phi}$ if $\ket{\phi}$ is $\ell$-locally $\eps$-close to $\calC$, then $\ket{\phi}$ is $\delta$ close to $\calC$. 
\begin{itemize}
    \item []\textbf{$\ell$-locally $\eps$-close:} for each $A\sse [n]$ with $|A|\leq \ell$ there exists a $\phi'\in \calC$ such that $\frac{1}{2}\tnorm{\phi_A - \phi'_A}\leq~\eps$.
    \item [] \textbf{$\delta$-close:} There exists a $\phi'\in \calC$ such that $\frac{1}{2}\tnorm{\phi - \phi'} \leq \delta$.
\end{itemize}

\label{def:appxrec}
    For a subset $S$ of a Hilbert space on $n$ qubits, we say that a region $A \sse [n] = A B$ of qubits is \emph{$\gamma$-recoverable} if there exists a unitary $U$ and a state $\ket{\tau}$ such that for each $\ket{\psi}\in S$,
    \begin{align}
        \norm{(U_{A'BC} \ot I_{A}) \ket{\psi}_{AB}\ket{0}_{A'C} - \ket{\psi}_{A'B}\ket{\tau}_{AC}} \leq \gamma.
    \end{align}
    For some ancillary register $C$. Note that $\ket{\tau}$ is fixed, independent of $\ket{\psi}$.

\label{claim:robustcode:local-set-contains-stabcode}
        For stabilizer state $\ket{\phi}$, let $\Cstab[\ell'](\phi)$ be the subspace of states that are stabilized by the $\ell'$-local stabilizers of $\ket{\phi}$, and let $S_{\ell'}(\phi)$ be the set of states that are $\ell'$ locally equivalent to $\phi$. If $S_{\ell'}(\phi)$ is $\gamma$-recoverable for all regions of size $< d$ for some $d> \ell'$ and $\gamma <\frac{1}{2\sqrt{2}}$, then
        \begin{align}
            \Cstab[\ell'](\phi) \cap \textsf{STAB} \sse S_{\ell'}(\phi). \label{eq:claim:local-set-contains-stabcode}
        \end{align}

\label{lem:disentangling-two}
    Suppose $\calC$ is the codespace corresponding to the $1$-eigenspace of pairwise commuting projectors $\{\Pi_i\}$. For each subset of qubits $M\sse [n]$, if together $M$ and its boundary $ M \cup \partial^+(M)$ is a correctable region, then there exists a unitary operator $U_{\partial_{\partial(M)^+}}$ acting only on $\partial^+(M)$ such that
    \begin{align}
        U_{\partial^+(M)}^\dagger\Pi U_{\partial^+(M)} = \proj{\eta_{MB}}\ot \Pi_{B'C}
    \end{align}
    For some decomposition of the Hilbert space on $\partial^+M$ into $\calH_{\partial^+(M)} = \calH_B \ot \calH_{B'}$,  $C = (M \cup \partial^+(M))^c$, and some fixed state $\ket{\eta_{MB}}$.

\label{cor:dl:prodstate}
    Suppose $\calC$ is a codespace as above, and $M$ a region of qubits such that $N(M) = M \cup \delta^+(M)$ is a correctable region. Then   for each $\rho \in \calC$, 
    \begin{align}
        \rho_{MC} = \rho_M \ot \rho_{C}.
    \end{align}
    Where $C = N(M)^c$.

\label{thm:cat-state-gluing-lb}
    Suppose $U\in \unitaries[2n]$ is a $2n$ qubit quantum circuit for $n\geq 2$ such that 
    \begin{align}
        U \proj{\bCATn[2n]{\alpha}} U^\dagger = \proj{\bCATn[n]{\beta}} \ot \proj{\bCATn[n]{\beta}}
    \end{align}
    For some $\alpha, \beta \in [0,1]$. If $H(\alpha) \neq 2 H(\beta)$, then $U$ requires depth $\Omega(\log n)$. Furthermore, this statement can be made robust as follows. Consider $V\in \unitaries[2n]$ such that
    \begin{align}
        V \proj{\bCATn[2n]{\alpha}} V^\dagger = \psi && \tnorm{\psi - \proj{\bCATn[n]{\beta}} \ot \proj{\bCATn[n]{\beta}}}\leq \eps.
    \end{align}
    Then $\depth(V) \geq \Omega\pbra{\log\min\cbra{n, \frac{1}{\eps}\cdot \abs{2 H(\beta) - H(\alpha)}^{\ln 4}}}$.

\label{thm:cat-state-gluing-eps-indep}
    Furthermore, if $H(\alpha) > 2 H(\beta)$ and our approximation is $\eps \leq 0.037 \cdot \pbra{H(\alpha) - 2H(\beta)}^{\ln 4}$ then any unitary $V\in \unitaries[2n]$ such that
    \begin{align}
        V \proj{\bCATn[2n]{\alpha}} V^\dagger = \psi && \tnorm{\psi - \proj{\bCATn[n]{\beta}} \ot \proj{\bCATn[n]{\beta}}}\leq \eps
    \end{align}
    has $\depth(V) \geq \Omega\pbra{\log n}$.

\label{def:affine-restriction}
We say that an axiom $\Axioms'$ is an
affine restriction of $\Axioms$ if there is a map $\rho : \{x_1,\dots,x_n\} \rightarrow \{x_1, \dots, x_n, \bar{x}_1, \dots, \bar{x}_n, 1, 0 \}$ such that $\Axioms \equiv \Axioms|_{\rho}$.

\label{lemma:affine_restriction}
Let $\Axioms, \Axioms'$ be axioms such that $\Axioms'$ is an affine restriction of $\Axioms$, and each axiom
of $\Axioms$ depends on a constant number of variables, then
\begin{enumerate}
	\item For any field $\Field$ it holds that $\Degree{\Axioms \PC \bot} \in \BigOmega{\Degree{\Axioms' \PC \bot}}$
	\item $\Degree{\Axioms \SOS \bot} \in \BigOmega{\Degree{\Axioms' \SOS \bot}}$
\end{enumerate}

\label{def:expander-graphs}
Let $G$ be a $d$-regular graph on $n$ vertices, and, let $\lambda_1 \geq \lambda_2 \ge \dots \geq \lambda_n$ denote eigenvalues of the adjacency matrix of $G$.
We say $G$ is an $\EnDeeLambda$-graph if $\ExpansionFactor{\Graph} := \underset{{\{2, \dots, n\}}}{\max}|\lambda_i| \leq \lambda$.

\label{lemma:expanders-mixing-lemma}
  Given an $\EnDeeLambda$-graph $G$, for any $S, T \subseteq \Vertices{G}$ we have
$$
  \left| \CutEdges{S}{T}{G} - \frac{d}{n}|S||T| \right|

  \le \lambda\sqrt{\Size{S}\Size{T} }
$$

\label{lemma:mult-chernoff}
Suppose $X_1, ..., X_n$ are identical independent random variables taking values in $\{0, 1\}$. Let $X$ denote their sum and let $\mu = n\Mean{}{X_1}$ denote the sum's expected value. Then, for any $0 < \delta < 1$, we have

\[ \Prob{|X - \mu| \geq \delta \mu} \leq 2\exp(-\delta^2\mu/3)\]

\label{lemma:lll}
Let $E_1,...,E_n$ be a set of events, and assume that the following hold:
\begin{enumerate}
\item The degree of the dependency graph given by $(E_1, \dots, E_n)$ is bounded by $d$.

\item For all $i \in [n]$, $\PProb{E_i}{\Dist} \leq \beta.$

\item $\beta \leq \frac{1}{4d}$.
\end{enumerate}
Then
\[ \Pr{\overset{n}{ \underset{i=1}{\bigcap}} \hspace{0.1cm}  \overline{E_i}}{\Dist} > 0\]

 \label{thm:embedding_top}
For every $D \in \mathbb{N}$ there exist $\alpha, \xi, C > 0$, such that the following holds. Suppose $G$ is a graph with $n$ vertices and $m \ge Cn$ edges such that for every pair of disjoint subsets $S, T \subseteq V(G)$ of size $|S|, |T| \ge \xi n$, we have
\begin{align*}
  \bigl| e_{G}(S, T) - |S||T|p \bigr| \le \xi |S||T| p \label{eq:props}
\end{align*}
where $p = m / \binom{n}{2}$. Then $G$ contains $H^{\sigma}$, where $H$ is any graph with maximum degree at most $D$, $H^\sigma$ has at most $\alpha n$ vertices, and $\sigma(e) \ge \log n$ for every $e \in E(H)$.

\label{thm:equivalence-PAP-AM-informal}
Let $S$ be a reasonably strong propositional proof system. Assuming that there is some $\delta >0 $ such that $\TSAT \not\in \ComplexityFont{io}\SIZE\left[2^{\delta n}\right]$, the following are equivalent:
\begin{enumerate}[label=(\roman*)] \itemsep=0pt
    \item \label{item:PAP}  the proof system $S$ is analyzable;
    \item \label{item:AM} for every unsatisfiable 3-CNF formula $\varphi$ over $n$ variables, every $S$-proof of the formula $\neg \Reff_{\poly(n)}(\varphi)$ requires size at least $2^{\Omega(n)}$.
\end{enumerate}

\label{thm:characterization-informal}
    Let $S$ be a reasonable propositional proof system that simulates Extended Frege. Then, for every sequence $\{ \varphi_n \}_{n\in\bbN}$ of unsatisfiable CNF formulas,
    \[ S \vdash_{\mathrm{poly}} \neg \varphi_n \qquad \text{ if and only if } \qquad S\vdash_{\mathrm{poly}}  \neg \Reff(\Reff(\varphi_n)).\]

\label{thm:aut-for-Ref-informal}
For every reasonable proof system $S$ that simulates Extended Frege as well as for Resolution itself,
\begin{enumerate}[label=(\roman*)] \itemsep=0pt
    \item $S$ is automatable if, and only if, $S$ is automatable exclusively on $\Reff$ formulas;
    \item $S$ is weakly automatable if, and only if, $S$ is weakly automatable exclusively on $\Reff$ formulas.
\end{enumerate}

\label{thm:prop-unprovable-informal}
Let $Q$ be a reasonable propositional proof system that simulates Resolution. If $\{ \varphi_n\}_{n\in\bbN}$ is a sequence of hard unsatisfiable CNF formulas for $Q$, where $\varphi_n$ has $n$ variables and size $|\varphi_n|=\poly(n)$, then
\begin{enumerate}[label=(\roman*)] \itemsep=0pt
    \item the formulas $\Reff_{n^2}(\varphi_n)$ over $N = \poly(n)$ variables are all unsatisfiable and require size $2^{N^{\Omega(1)}}$ to be refuted in Resolution;
    \item yet, $Q$ does not have polynomial-size refutations of the formulas $\Reff_{N^2}(\Reff_{n^2}(\varphi_n))$ stating quadratic lower bounds on $\Reff_{n^2}(\varphi_n)$.
\end{enumerate}

\label{thm:fo-unprovable-informal}
    Let $T$ be a consistent first-order theory extending Robinson Arithmetic by a set of polynomial-time recognizable axioms. Then, there exists a sequence of unsatisfiable propositional formulas $\{ \psi_{N} \}_{{N} \in \bbN}$ described uniformly by a polynomial-time algorithm, where $\psi_N$ has $N$ variables, such that
\begin{enumerate}[label=(\roman*)] \itemsep=0pt
    \item[(i)] Resolution refutations of the formula $\psi_{N}$ require size $2^{N^{\Omega(1)}}$;
    \item[(ii)] there exists $c > 0$ such that the theory $T$ cannot prove $\Omega(N^c)$ lower bounds on the Resolution size of
    these refutations; that is, there is $N_0 \in \bbN$ such that the lower bound expressed by the first-order sentence
    $\forall N\forall \pi \left(N > N_0 \land \operatorname{Ref}_{\Res}(\psi_N,\pi) \to |\pi| > N^c\right)$ is unprovable in $T$.
\end{enumerate}

\label{thm:translation}
    The theory $\PVO$ and the proof system Extended Frege correspond to each other. That is,
    \begin{enumerate}[label=(\roman*)] \itemsep=0pt
        \item $\PVO$ proves the soundness of $\EF$;
        \item if $\varphi(x)$ is a quantifier-free formula in the language $\calL_{\operatorname{BA}}(\PV)$ and $\PVO \vdash \forall x\varphi(x)$, then there exists a polynomial-time computable function $f$ such that for every $n \in \bbN$,  it holds that $f(1^n) : \EF \vdash \trans{\varphi}_n$.
    \end{enumerate}

\label{def:Reff-formulas}
Let $n, m, s \in \bbN$, and let $\Lit_n \coloneq \{x_1, \dots, x_n, \neg x_1, \dots, \neg x_n\}$ denote the of possible literals over $n$ variables. The $\Reff_s(\varphi)$ formula is built from the variables defined above, together with the conjunction of the following clauses:

{\allowdisplaybreaks
    \begin{axiomdef}{2}{Ref}
        & \left( \enable^B \land \res^B_{x_i} \land \lpoint^B_{B'} \land \lit^{B'}_\ell \right) \to \lit^{B}_\ell  &&\quad\text{ for }B, B'\in[s], B' < B, i\in[n], \ell \in \Lit_n \setminus \{ x_i\},\label{axiom:must-appear-after-res-left} \\
        & \left( \enable^B \land \res^B_{x_i} \land \rpoint^B_{B'} \land \lit^{B'}_\ell \right) \to \lit^{B}_\ell  &&\quad\text{ for }B, B'\in[s], B' < B, i\in[n], \ell \in \Lit_n \setminus \{\neg x_i\},\label{axiom:must-appear-after-res-right}\\
        & \left( \enable^B \land \weak^B_A \land \alit^A_\ell\right) \to \lit^B_\ell  &&\quad\text{ for }B\in[s], A\in[m], \ell\in \Lit_n,\label{axiom:must-appear-after-weak}\\
        & \left( \enable^B \land \derived^B \right ) \to \bigvee_{i\in[n]} \res^B_{x_i}  &&\quad\text{ for }B \in [s],\label{axiom:must-resolve} \\
        & \left( \enable^B \land \derived^B \right ) \to \bigvee_{\substack{B' \in [s] \\ B' < B}} \lpoint^B_{B'}  &&\quad\text{ for 
        }B \in [s],\label{axiom:must-point-left} \\
        & \left( \enable^B \land \derived^B \right ) \to \bigvee_{\substack{B' \in [s] \\ B' < B}} \rpoint^B_{B'}  &&\quad\text{ for }B \in [s],\label{axiom:must-point-right} \\
        & \left( \enable^B \land  \neg \derived^B \right) \to \bigvee_{A\in[m]} \weak^B_A  &&\quad\text{ for }B \in [s],\label{axiom:must-weaken} \\
        & \left( \enable^B \land  \lpoint^B_{B'} \right) \to \enable^{B'}  &&\quad\text{ for }B, B' \in [s], B' < B\label{axiom:must-enable-left} \\
        & \left( \enable^B \land  \rpoint^B_{B'} \right) \to \enable^{B'}  &&\quad\text{ for }B, B' \in [s], B' < B\label{axiom:must-enable-right} \\
        & \neg \lit^s_\ell &&\quad\text{ for }\ell \in \Lit_n ,\label{axiom:root-empty}\\
        & \enable^s. && \label{axiom:root-enabled}
    \end{axiomdef}
}

\label{def:satf}
Let $n, m \in \bbN$, let $\varphi$ denote the set of variables of the form $\alit^A_\ell$ as above and let $\alpha$  denote the set of variables $\alpha_i$ as above. The formula $\Satf(\varphi, \alpha)$ is the CNF formula over the variables in $\varphi$, $\alpha$ and additionally all the variables $\sat^A_\ell$ above consisting of the conjunction of the following clauses,
{\allowdisplaybreaks
\begin{axiomdef}{2}{Sat}
        & \neg\sat^A_\ell \lor \alit_\ell^A &&\quad\text{ for all }A\in[m]\text{ and }\ell\in \{x_1, \dots, x_n, \neg x_1, \dots, \neg x_n\},\label{sat-1}\\
        &\neg \sat^A_{x_i} \lor \alpha_i &&\quad\text{ for all }A \in [m]\text{ and } i \in [n],\label{sat-2}\\
        &\neg \sat^A_{\neg x_i} \lor \neg \alpha_i &&\quad\text{ for all }A \in [m]\text{ and } i \in [n],\label{sat-3}\\
        & \bigvee_{i \in [n]} \sat^A_{x_i} \lor \sat^A_{\neg x_i} &&\quad\text{ for all }A\in[m].\label{sat-4}
    \end{axiomdef}}

\label{prop:sat-to-native-Res}
For every CNF formula $\varphi$, the following statements hold:
\begin{enumerate}[label=(\roman*)] \itemsep=0pt
\item if $\varphi$ has a Resolution refutation of length $s$, then
$\Satf_{\restriction\varphi}$ has a Resolution refutation of length $O(s)$;
\item if $\Satf_{\restriction\varphi}$ has a Resolution refutation of length $s$, then 
$\varphi$ has a Resolution refutation of length $O(s)$.
\end{enumerate}

For a propositional proof system $Q$, we denote by $\FPAP_Q$ the \emph{search version of the Proof Analysis Problem for $Q$}, defined as follows.
\searchProblemStatement{$\FPAP_Q$ (search version of $\PAP_Q$)}{A CNF formula $\varphi$, a size parameter $s$ in unary and a proof $\pi$ such that $\pi : Q \vdash \neg \Reff_s(\varphi)$.}{Either a satisfying assignment for $\varphi$, if $\varphi \in \SAT$, or $0$ otherwise.}
Similarly to $\PAP_Q[s(n)]$, we define $\FPAP_Q[s(n)]$ to be the search problem where the size parameter is at least $s(n)$.

\label{lemma:rand-wr}
        Let $p \in [0, 1)$ and let $N$ be the number of variables of the $\Reff_s(\varphi)$ formula for some CNF formula $\varphi$ over $n$ variables. There exists a randomized algorithm $R$ taking as input $1^N$, and outputting an $\lfloor{s/2}\rfloor$-disabling restriction $\rho \in \{0, 1, * \}^{N}$, such that for every Resolution refutation $\pi$ of the formula $\Reff_s(\varphi)$, the following properties hold:
        \begin{enumerate}[label=(\roman*)]\itemsep=0pt
            \item the restriction $\rho$ does not falsify $\Reff_s(\varphi)$;
            \item with probability at least $p$, the block-width of $\pi_{\restriction \rho}$ is at most $O\left( \log |\pi| - \log (1 - p)\right)$;
            \item the running time of $R(1^N)$ is $O(N)$.
        \end{enumerate}

\label{lemma:det-wr}
    There exists a constant $c > 0$ and a deterministic algorithm taking as input a Resolution refutation $\pi$ of the formula $\Reff_s(\varphi)$ over $N$ variables and outputting a $d$-disabling restriction $\rho \in \{0,1, *\}^{N}$ with $d \leq c/2 \cdot \big( \sqrt{s\log |\pi|} \big)$ such that
    \begin{enumerate}[label=(\roman*)]\itemsep=0pt
        \item the restriction $\rho$ does not falsify $\Reff_s(\varphi)$;
        \item the block-width of $\pi_{\restriction \rho}$ is at most $c\cdot \big( \sqrt{s\log |\pi|} \big)$;
        \item the algorithm runs in time $\poly(|\pi|, s)$.
    \end{enumerate}

\label{lemma:extraction}
    There exists a deterministic algorithm $E$ such that for every $s\in\bbN$, every $\pi$ a purported Resolution refutation of $\Reff_s(\varphi)$ for a CNF formula $\varphi(x_1, \dots, x_n)$ with $m$ clauses, and every $\rho \in \{ 0,1,*\}^N$ a $d$-disabling restriction to the $N$ variables in $\Reff_s(\varphi)$, it holds that $E(\varphi, \rho, s, \pi)$ terminates in time $\poly(|\pi|, s, n, m)$ and provides exactly one of the following outputs:
    \begin{enumerate} \itemsep=0pt
        \item[(a)] an incorrect derivation step in $\pi$;
        \item[(b)] a clause $C \in \pi_{\restriction\rho}$ of block-width at least $1/3 \lfloor (s-d - n)/n\rfloor$;
        \item[(c)] a satisfying assignment for $\varphi$.
    \end{enumerate}

The following hold at the beginning of each iteration of the algorithm, when dealing with the clause $C$ in the traversal of $\pi$:
\begin{enumerate}
\itemsep=0pt
    \item[(i)] the reservation $\alpha$ falsifies $C$;
    \item[(ii)] a block $B \not\in D$ is only reserved in $\alpha$ if it is either mentioned in $C$ or its parent according to $\alpha$ is mentioned in $C$, and, in particular, $\bw(\alpha) - d\leq 3\bw(C)$;
    \item[(iii)] if $\alpha$ encodes any information about a block $B$ from layer $i$, and $B \not\in D$, then $\alpha$ also determines that $B$ contains exactly $i$ literals over the variables $x_1, \dots, x_i$ and no two literals for the same variable;
    \item[(iv)] the reservation $\alpha$ does not falsify any axiom of $\Reff_s(\varphi)$.
\end{enumerate}

\label{thm:CP90-PHP}
There exist a positive $\varepsilon_0 \in \bbQ$ and $n_0 \in \bbN$ such that
\[\PVO \vdash \forall n\forall\pi(\foReff(\PHP^n_{n-1}, \pi) \land n \geq n_0 \to ||\pi|| > \varepsilon_0 n).\]

\label{thm:lwb-for-Disj}
    For every positive constant $c \in \bbN$, there exist $n_0 \in \bbN$ such that 
    \[ \SOT \vdash \forall \varphi \forall \pi \forall n \leq \varphi \forall m \leq \varphi \left(n \geq n_0 \land  \operatorname{3-CNF}(\varphi, n, m) \land |\pi| \leq n^{c} \to \neg \foReff( \disj(\varphi, \PHP_n) ), \pi)\right) .\]

\label{cor:EF-proofs}
    For every positive constant $c \in \bbN$, there exists a polynomial-time computable function $t$ such that for every 3-CNF formula $\varphi$ over a large enough number $n$ of variables, $t(\varphi)$ outputs an Extended Frege proof $\pi$ such that
    \[ \pi:  \EF \vdash \neg \Reff_{n^{c}}\left(   \disj(\varphi, \PHP_n)    \right).\]

The following hold:
\begin{enumerate}[label=(\roman*)] \itemsep=0pt
    \item \Cref{conj:analyzability-requires-lbs} is true if, and only if, $\NP \neq \coNP$;
    \item \Cref{conj:original} is true if, and only if, $\P \neq \NP$.
\end{enumerate}

\label{thm:equivalence-PAP-AM}
Let $S$ be a propositional proof system that simulates Resolution, is constructively closed under modus ponens and contrapositions, and proves that Resolution is closed under restrictions. Assuming there exists a constant $\delta >0$ such that $\TSAT \not\in \ComplexityFont{io}\SIZE[2^{\delta n}]$, the following are equivalent:
\begin{enumerate}[label=(\roman*)] \itemsep=0pt
    \item \label{item:PAP}  the proof system $S$ is analyzable;
    \item \label{item:AM} there are constants $c > 0$, $n_0 \geq 1$ and $\varepsilon > 0$ such that for every unsatisfiable 3-CNF formula $\varphi$ over $n \geq n_0$ variables, every $S$-proof of the formula $\neg \Reff_{n^{c}}(\varphi)$ requires size at least $2^{\varepsilon n}$.
\end{enumerate}

\label{def:most-killing}
We will say that a restriction $\rho$ enjoys the \emph{most-killing property} with respect to a trace $\tau = ((b_1, X_1), \dots, (b_\ell, X_\ell))$ if it holds that for every $k \in[\ell]$, the block $i \in [s] \setminus \{ b_1, \dots, b_{k-1}\}$ that is the most frequent block mentioned in $W_{\restriction \rho_{k-1}}$ happens to be precisely $b_k$ and $\rho_k$ satisfies the following conditions.
\begin{enumerate}
\itemsep=0pt
    \item If $e_i$ appears positively in at least $1/3$ of all the clauses in $W_{\restriction \rho_{k-1}}$ that mention block $i$, then $\rho_k(e_i) = 1$ and $\rho_k(x) = *$ for every other variable $x \neq e_i$ in block $i$.

    \item If $e_i$ does \emph{not} appear positively in at least $1/3$ of all the clauses in $W_{\restriction \rho_{k-1}}$ that mention block $i$, then $\rho_k(e_i) = 0$ and for every other variable in block $i$, $\rho_k$ assigns values to them respecting the ordering in $X_i = ( e_i, x_{i,1}, x_{i, 2}, \dots)$ and with the following priority. For $j = 1, \dots, |X_i|-1$,
    \begin{enumerate}
    \itemsep=0pt
        \item if $x_{i, j}$ appears positively more often than negatively in $W_{\restriction \rho_{k-1, \{e_i, x_{i, 1}, \dots, x_{i, j-1}\}}}$, then $\rho_k(x_{i, j}) = 1$; 
        \item if $x_{i, j}$ appears negatively more often than positively in $W_{\restriction \rho_{k-1, \{e_i, x_{i, 1}, \dots, x_{i, j-1}\}}}$, then $\rho_k(x_{i, j}) = 0$.
    \end{enumerate}
\end{enumerate}

\label{lemma:induction-restriction-PV}
Let $c \in \bbN$. The following is provable in $\SOT$. For every CNF formula $\varphi$  over $n$ variables and $\pi$ a correct Resolution refutation of $\Reff_s(\varphi)$, let $w \coloneq c\cdot \left\lceil \sqrt{s \log |\pi|} \right\rceil$ and let $W$ denote the set of clauses in $\pi$ of block-width larger than $w$. Then, for every $\ell$, the formula $\Psi(\varphi, \pi, s, \ell)$ defined as follows holds: if $\ell \leq w/2$, then there exists a restriction $\rho \in \{ 0,1,*\}^N$, where $N$ is the number of variables of the $\Reff_s(\varphi)$ formula, a trace $\tau = ((b_1, X_1), \dots, (b_\ell, X_\ell))$ and $d \leq \ell$ such that:
\begin{enumerate}[label=(\roman*)]
\itemsep=0pt
    \item $\rho$ is $d$-disabling;
    \item $\rho$ has the most-killing property according to $\tau$;
    \item $(3s)^\ell \cdot |W_{\restriction \rho}| \leq |W| \cdot (3s- w + \ell)^\ell$.
\end{enumerate}

\label{lemma:exp-bound-PV}
In $\PVO$, for all $n,m,p \in \Log$, if $n < m$ and $p \geq 1$, it holds that
\[\biggl( 1 - \frac{n}{m}\biggr)^p \leq 2^{-\frac{n}{m}p}. \]

\label{def:reservation-invariant}
Let $\pi$ be a Resolution refutation of $\Reff_s(\varphi)$ for some CNF formula $\varphi(x_1, \dots, x_n)$, let $N$ be the number of variables of $\Reff_s(\varphi)$, $d \leq \operatorname{depth}(\pi)$, and let $\calC = (C_1, \dots, C_d)$ be a length-$d$ path in $\pi$ starting from $C_1 = \bot$. Let the $s$ blocks of $\Reff_s(\varphi)$ be arranged in a layered manner, so that there are $n$ layers, each containing $\lfloor s/n\rfloor$ blocks, with the remainder blocks left from the flooring operations collected all in the last layer, plus one additional layer on top with a single block corresponding to the root. We say that $\calC$ satisfies the \emph{reservation invariant} with respect to a sequence $A = (\alpha_1, \dots, \alpha_d)$ of restrictions $\alpha_i \in \{ 0,1,*\}^N$ if, for every $i \in [d]$,

\begin{enumerate}
\itemsep=0pt
    \item[(i)] the restriction $\alpha_i$ falsifies $C_i$;
    \item[(ii)] a block is only mentioned in $\alpha_i$ if it is either mentioned in $C_i$ or its parent according to $\alpha_i$ is mentioned in $C_i$, and, in particular, $\bw(\alpha_i)  \leq 3\bw(C_i)$;
    \item[(iii)] if $\alpha_i$ restricts some variable in block $B$ from layer $\ell$, then it does so in the following way: $B$ must contain exactly $\ell$ literals over the variables $x_1, \dots, x_\ell$ and no two literals for the same variable;
    \item[(iv)] the restriction $\alpha_i$ does not falsify any clause of $\Reff_s(\varphi)$;
    \item[(v)] the path determined by $\calC$ corresponds to $A$ in the following way: if $C_i$ was derived from $C_{i+1}$ by resolving over variable $v$, then $\alpha_{i+1}(v)$ is defined and $v$ appears in $C_{i+1}$ with polarity $1- \alpha_{i+1}(v)$.
\end{enumerate}

\label{lemma:induction-width-PV}
The following is provable in $\SOT$. For every CNF formula $\varphi$ over $n$ variables and $\pi$ a correct Resolution refutation of $\Reff_s(\varphi)$, for every $d$, the formula $\Psi(\varphi, \pi, s, d)$ defined as follows holds: if $1\leq d \leq \operatorname{depth}(\pi)$, then there exists a sequence $\calC = (C_1, \dots, C_d)$ of clauses of $\pi$ and a sequence $A = (\alpha_1, \dots, \alpha_d)$ of restrictions such that at least one of the following conditions holds:
\begin{enumerate}
\itemsep=0pt
    \item[(a)] there is $C_i \in \calC$ that satisfies $\bw(C_i) \geq 1/3 (\lfloor{s/n}\rfloor - 1 )$;
    \item[(b)] there is $C_i$ in and its corresponding restriction $\alpha_i$ that contain a satisfying assignment to $\varphi$;
    \item[(c)] the sequence $\calC$ is a path in $\pi$ starting at $C_1 = \bot$ and the reservation invariant holds for $\calC$ with respect to $A$.
\end{enumerate}

 \label{prop:mild-properties}
The following hold for every reasonably strong proof system $S$:
 \begin{enumerate}[label=(\roman*)]
 \itemsep=0pt
     \item the system $S$ is constructively closed under formula substitutions, i.e., given a proof of $\varphi(x_1, \dots, x_n)$ in size $s$ and formulas $\psi_1, \dots, \psi_n$, we can obtain a proof of $\varphi(\psi_1, \dots, \psi_n)$ in time $\poly(s, n, |\psi_1|, \dots, |\psi_n|)$;
     \item the system $S$ is constructively closed under \emph{modus ponens}, i.e., given an $S$-proof of $\varphi$ in size $s$ and an $S$-proof of $\varphi \to \psi$ in size $t$, we can obtain an $S$-proof of $\psi$ in time $\poly(s, t)$;
     \item the system $S$ is constructively closed under contrapositions, i.e., given an $S$-proof of $\neg \psi$ in size $s$ and an $S$-proof of $\varphi \to \psi$ in size $t$, we can obtain an $S$-proof of $\neg \varphi$ in time $\poly(s, t)$;
     \item the system $S$ \emph{implicationally simulates Resolution}: for every two CNF formulas $\varphi$ and $\psi$ such that Resolution performs the derivation $\varphi \vdash_\Res \psi$ in size $s$, there is an $S$-proof of $\varphi \to \psi$ in size $\poly(s)$.
 \end{enumerate}

\label{lemma:UB-consequence-basic}
Let $S \geq \Res$ be a propositional proof system closed under literal substitutions, modus ponens, contrapositions, and implicationally simulating Resolution.
Then, there exists $p(n, m, s) = \poly(n,m, s)$ such that for every $n$-variate CNF formula $\varphi$ with $m$ clauses, and every $t\geq p(n,m,s)$ if $S \vdash \neg \Reff_{t}(\Reff_s(\varphi))$ in size $\ell$, then $S \vdash \neg \varphi[2]$ in size $\poly(n, m, s, t, \ell)$.

\label{thm:fragment-characterization}
Let $S$ be a reasonably strong proof system. There is $p(n, m, s) =\poly(n,m, s)$ such that for every CNF formula $\varphi(x_1, \dots, x_n)$ with $m$ clauses, every $t \in \bbN$, and every $s \geq n^3$,
\begin{enumerate}[label=(\roman*)]
\itemsep=0pt
    \item if $S \vdash \neg \varphi$ in size $\ell$, then $S \vdash \neg \Reff_t(\Reff_{s}(\varphi_n))$ in size $\poly(n, m, s, t, \ell)$;
    \item if $S \vdash \neg \Reff_{p(n,m,s)}(\Reff_s(\varphi_n))$ in size $\ell$, then $S \vdash \neg \varphi_n$ in size $\poly(n, m, s, \ell)$.
\end{enumerate}
Furthermore, in both cases, given an $S$-proof of the left-hand side statement, one can obtain a proof of the right-hand side statement in polynomial time.

\label{thm:aut-on-Ref-EF}
Let $S$ be a reasonably strong proof system. Then, the following are equivalent:
\begin{enumerate}
    \item[(i)] $S$ is automatable;
    \item[(ii)] $S$ is automatable on $\Reff$ formulas.
\end{enumerate}

\label{thm:W-aut-on-Ref-EF}
Let $S$ be a reasonably strong proof system. Then, the following are equivalent:
\begin{enumerate}
    \item[(i)] $S$ is weakly automatable;
    \item[(ii)] $S$ is weakly automatable on $\Reff$ formulas.
\end{enumerate}

\label{thm:aut-on-Ref-Res}
The following hold for Resolution:
\begin{enumerate}
    \item[(i)] Resolution is automatable if, and only if, it is automatable on $\Reff$ formulas;
    \item[(ii)] Resolution is weakly automatable if, and only if, it is weakly automatable on $\Reff$ formulas.
\end{enumerate}

\label{cor:prop-unprovability}
For every propositional proof system $S \geq \Res$ implicationally simulating Resolution and closed under contrapositions and clause substitutions, if $S$ is not polynomially bounded, there exists a family of unsatisfiable CNF formulas $\{\psi_n\}_{n\in\bbN}$ on $N = \poly(n)$ variables and of size $|\psi_n| = \poly(n)$ such that
\begin{enumerate}
    \item[(i)] they require size at least $2^{N^{\Omega(1)}}$ to be refuted in Resolution;
    \item [(ii)] there is a polynomial $p(n)$ such that the formulas $\{ \neg \Reff_{p(n)}(\psi_n)\}_{n\in\bbN}$ are tautological but do not have polynomial-size proofs in $S$.
\end{enumerate}

\label{thm:fo-unprovable}
Let $T$ be a consistent first-order extending $\SOT$ with a set of axioms recognizable in polynomial time and admitting $\bbN$ as a model. Then, there exits a sequence of unsatisfiable propositional formulas $\{ \psi_{k, s} \}_{{k, s} \in \bbN}$ described uniformly by a polynomial-time algorithm given $k$ and $s$ in unary, where $\psi_{k,s}$  has $N = \poly(k, s)$ variables, and such that
\begin{enumerate} \itemsep=0pt
    \item[(i)] Resolution refutations of the formula $\psi_{k, s}$ require size $2^{N^{\Omega(1)}}$;
    \item[(ii)] there are constants $c >0$ and $N_0 \in \bbN$ such that the lower bound expressed by the first-order sentence $\forall k \forall s\forall \pi \left(  N > N_0 \land \operatorname{Ref}_{\Res}(\psi_{k, s}, \pi) \to |\pi| >  N^{c} \right)$ is independent of $T$.
\end{enumerate}

\label{cor:fo-unprovable}
    Let $T$ be a consistent first-order extending $\mathsf{Q}$ with a set of axioms recognizable in polynomial time. Then, there exits a sequence of unsatisfiable propositional formulas $\{ \psi_{k, s} \}_{{k, s} \in \bbN}$ described uniformly by a polynomial-time algorithm given $k$ and $s$ in unary, where $\psi_{k,s}$ has $N = \poly(k, s)$ variables, and such that
\begin{enumerate} \itemsep=0pt
    \item[(i)] Resolution refutations of the formula $\psi_{k, s}$ require size $2^{N^{\Omega(1)}}$;
    \item[(ii)] there is a constant $c > 0$ and $N_0 \in \bbN$ such that the lower bound expressed by the first-order sentence $\forall k \forall s\forall \pi \left(N > N_0 \land \operatorname{Ref}_{\Res}(\psi_{k, s}, \pi) \to |\pi| >  N^{c} \right)$ is unprovable in $T$, but true in $\bbN$.
\end{enumerate}

\label{def:clone}
    A \emph{clone} over $D$ is a set of operations $\mathcal{F} \subseteq \bigcup_{n \geq 1}\{f: D^n \to D\}$ for which the following holds:
    \begin{itemize}
        \item $\mathcal{F}$ contains the projection operation $\mathrm{proj}^n_i$ for every $n \geq 1$, $i \in [n]$.
        \item For every $m$-ary $g \in \mathcal{F}$ and $n$-ary $f_1, \ldots, f_m \in \mathcal{F}$, the $n$-ary function $g'$ defined by
        \[
        g': (x_1, \ldots, x_n) \mapsto g(f_1(x_1, \ldots, x_n), \ldots, f_m(x_1, \ldots, x_n))
        \]
        is also in $\mathcal{F}$.
    \end{itemize}

\label{def:2-3-minimal}
    A binary CSP instance $I = (V, \{R_u\}_{u \in V}, \{R_{u, v}\}_{u\neq v \in V})$ over domain $D$ is \emph{$(2,3)$-minimal} if 
    \begin{enumerate}
        \item[(a)] For every distinct $u, v\in V$, $R_{v,u} = \{(b, a) \mid (a, b) \in R_{u, v}\}$. 
        \item[(b)] For every distinct $u, v \in V$, $R_u = \{a \in D \mid \exists b \in D, (a, b) \in R_{u,v}\}$.
        \item[(c)] For every pairwise distinct $u,v,w \in V$ and $(a, b) \in R_{u,v}$, there exists $c \in R_w$ such that $(a, c) \in R_{u,w}$ and $(b, c) \in R_{v,w}$.
    \end{enumerate}

\label{lem:01all}
    Let $R \subset D^2$ be a binary relation. Then $R$ is preserved by the dual discriminator operation $d: D^3 \to D$ if and only if $R$ is of one of the following forms:
    \begin{itemize}
        \item $R = P \times Q$ for some $P, Q \subseteq D$.
        \item $R = (\{u\} \times Q) \cup (P \times \{v\})$ for some $u \in P \subseteq D$ and $v \in Q \subseteq D$.
        \item $R = \{(u, \pi(u)) \mid u \in P\}$ for some $P,Q \subseteq D$ and bijective $\pi: P \to Q$.
    \end{itemize}

\label{lem:greedy_correctness}
    Let $I = (V, \{R_u\}_{u \in V}, \{R_{u,v}\}_{u,v\in V})$ be a nontrivial (2,3)-minimal instance preserved by the dual discriminator operation. Let $u_0 \in V$, $a \in R_{u_0}$, $S$ be the set of variables fixed by assigning $a$ to $u_0$. For every $v \in S$, let $A_S(v)$ be the unique label that $v$ is fixed to by assigning $a$ to $u_0$. Let $A': V \backslash S \to D$ be any satisfying assignment for the induced (2,3)-minimal instance $I' = (V \backslash S, \{R_u\}_{u \in V \backslash S}, \{R_{u,v}\}_{u,v\in V \backslash S})$, then 
