    \item letting $\wv_s = s$ (with appropriate zero padding), we can update $\zv \gets \zv + \gamma s$. 
\end{itemize}

\label{lemma:innerproduct}
    We can compute and store both $\langle \xv, \vecv_a\rangle$ and $\langle \yv, \vecv_b \rangle$ using $O(\ell)$ local space, at most $O(\log m)$ local space during oracle calls, and $4$ calls to $\calO$.
    At the end, none of the global space registers will be changed.

\label{lemma:oneprime}
    For any $i \in [t]$ and $r, s \in \zo^\ell$, we have:
    \begin{align*}
        \underset{\substack{b_i, c_i \in \zo \\ \langle \xv + b_i \cdot \uv_a, \vecv_r \rangle \cdot \langle \yv + c_i \cdot \uv_b, \vecv_s \rangle \equiv \beta_i \pmod{p_i}}}{\sum} (-1)^{b_i+c_i} = \begin{cases}
            \alpha_i,\text{ if }(r, s) = (a, b), \\
            0,\text{ if }\langle \uv_a, \vecv_r \rangle \cdot \langle \uv_b, \vecv_s \rangle \equiv 0 \pmod{p_i}, \\
            \text{arbitrary, otherwise}.
        \end{cases}
    \end{align*}

\label{lemma:manyprimes}
    For any $r, s \in \zo^\ell$, we have:
    \[
    \underset{\substack{b_1, \ldots, b_t, c_1, \ldots, c_t \in \zo \\ \langle \xv + b_i \cdot \uv_{a}, \vecv_r \rangle \cdot \langle \yv + c_i \cdot \uv_{b}, \vecv_s \rangle \equiv \beta_i\pmod{p_i} \forall i\in [t]}}{\sum} (-1)^{\sum_{i \in [t]} (b_i+c_i)} = \begin{cases}
        \prod_{i \in [t]} \alpha_i,\text{ if }(r, s) = (a, b), \\
        0,\text{ else.}
    \end{cases}
    \]

\label{def:CIRcorrectness}
    We require that for any $a, b \in [n_\DB]$ and $x, y \in \calR$, it holds that:
    \begin{align*}
        \DB_{a || b} &= \sum_{\id \in [s]} \mathsf{AnswerAndReconstruct}(\DB, \GetSt^{\calO_{a, b}}(x, y), \id, x+\detqu(a, \id, 0), y+\detqu(b, \id, 1)).
    \end{align*}

We say a CIR scheme is \emph{space-efficient} if each of the following are true:
\begin{itemize}
    \item We can represent a valid element of $\calR$ on the catalytic tape in space $\tO(\log|\calR|)$, and we can perform arithmetic operations in $\calR$ in time $\poly\log|\calR|$ and additional space $O(\log\log |\calR|)$.
    \item $\GetSt^{\calO_{a,b}}$ is computable with catalytic registers $x, y$; it uses $O(\log \ndb)$ free space, and $O(|\state|)$ free space during every call to $\calO$; and
    \item $\mathsf{AnswerAndReconstruct}$ is computable with $O(\log \ndb)$ free space and runs in time $\poly(\ndb)$, provided that we can random access into $\DB$ in $O(\log \ndb)$ space.
\end{itemize}

\label{thm:abstracttep}
    Suppose the CIR scheme is space-efficient.
    Then, using the one-level algorithm above (where we implement the oracle $\calO_{a,b}$ using a recursive instantiation of the algorithm in the natural way), we get an algorithm for \tephl that uses $\tO(\log |\calR|)$ catalytic space, $O(h \cdot |\state| + h \log s +\ell)$ free space, and $O(s)^{h}\cdot \poly(2^\ell,\log|\calR|,|\state|)$ runtime.

Let $S \subseteq \Z_m \setminus \{0\}$. We say that a set of polynomials
$\cF=\{f_1,\ldots,f_k\}\subseteq \Z_m[z_1,\ldots,z_h]$
and a set of points $x=\{x_1,\ldots,x_k\}\subseteq \Z_m^{h}$
form a space-$s$ uniform polynomial $S$-matching family of size $k$ if
\begin{itemize}
  \item for all $i\in [k]$, $f_i(x_i)=0$;
  \item for all $i,j\in [k]$ such that $i\neq j$, $f_j(\mathbf{x}_i)\in S$.
  \item There is a space $s$ algorithm that prints $\cF$.
\end{itemize}

There is a space $O(d\log h)$ algorithm\footnote{The explicitness is not stated but is immediate from the construction.} that given $i\in [t]$ and $w$ prints an explicit multilinear polynomial $f_i(z_1,\ldots,z_h)\in \Z_{p_i}[z_1,\ldots,z_h]$ where $\deg(f_i)\le p_i^{e_i}-1$ and for $x\in \zo^h$:
\[
f_i(x) = \begin{cases}
    0 \mod p_i & \sum_i x_i \equiv w\mod p_i^{e_i}\\
    1 & \text{o.w.}
\end{cases}
\]

\label{cor:poly}
    There is a space $O(d\log h+\log m)$ algorithm that 
    prints an explicit degree $d$ multilinear polynomial $f_i(z_1,\ldots,z_h)\in \Z_{m}[z_1,\ldots,z_h]$ for $x\in \zo^h$:
    \[
    f_i(x) = \begin{cases}
        0 \mod m & \sum_i x_i = w\\
        s \mod m & \sum_i x_i < w
    \end{cases}
    \]
In the above, $\sum_i x_i$ is being computed over $\Z$.

\phantomsection\label{def:pseudoexp}
    For any collection of DNFs $F=\{D_i\}_{i \in [m]}$ a \emph{degree-$d$ pseudo-expectation} for $F$ is a linear function $\pe : \mathbb{R}[x] \rightarrow \mathbb{R}$ satisfying
    \begin{enumerate}
        \item $\pe[1] = 1$,
        \item $\pe [{\cal J}] \geq 0$ for every conical junta ${\cal J}$ of degree at most $d$,
        \item $\pe [D_i{\cal J}] \geq 0$ for every $D_i \in F$ and conical junta $J$ such that $\deg(D_i {\cal J}) \leq d$.
    \end{enumerate}
        A degree-$d$ \emph{$\Sigma_2$-pseudo-expectation} for $F$ is a family of degree-$d$ pseudo-expectations $\{\pe_G\}$, one for every $\Sigma_2$-weakening $G$ of $F$.

\phantomsection
\label{thm:PE}

   There exists $\Sigma_2$-pseudo-expectation for $\LOP$ of degree $(\frac{n}{400} - 1)$.

We say that a DNF $D$ is \emph{normalized} if 
\begin{enumerate}
\item Every term $t$ of $D$ is of the form $t=[\![S ]\!]_\pi$ for some set $S$ which includes $1$, and

\item All terms have the same support size, which we refer to as the \emph{support size of $D$}.
\end{enumerate}

\label{prop:everythingForPE}
  Let $N$ be normalized DNF with support size $k$ that is a weakening of $M_1$,
and let $R$ be the set of total orders rejected by $N$. 
  Then the following holds: 
  \begin{enumerate}



    \item $\pe[N]\geq 0$ if and only if $N$ has at least $k!$ terms, 
    \item Let $S_i$ be the set of total orders accepted by exactly $i$ terms in $N$, then $\pe[N]\geq 0$ if and only if $|R|\leq \sum_{i=2}^{\infty}(i-1)|S_i|$.
  \end{enumerate}

\label{lem:accept}
For a normalized DNF,
\begin{enumerate}
\item Total orders starting with 1 can only be accepted by terms $\bra{T}[\pi]$ with $\pi(1)=1$. 
\item Total orders with first element $i$ and second element 1 can only be accepted by terms $\bra{T}[\pi]$ with either $\pi(1)=1$ and $i\notin T$, or $\pi(1)=i$ and 
$\pi(2)=1$. 
\end{enumerate}

Let $z$ be an order on $[n]\setm 1$.
We call an unordered pair of distinct elements $(i,j)\in ([n]\setm1)^2$ a \emph{hitting pair} for $z$ if the following conditions hold:
 \begin{itemize}
   \item $N$ has a term $\bra{T_1}[\pi_1]$ such that $\pi_1(1)=i, \pi_1(2)=1, j\notin T_1$ and $i1(z\setm i)\rest T_1=\pi_1$.
   \item $N$ has a term $\bra{T_2}[\pi_2]$ such that $\pi_2(1)=j, \pi_2(2)=1, i\notin T_2$ and $j1(z\setm j)\rest T_2=\pi_2$.
 \end{itemize}

\label{hitting-count}
Any $(n-1) \times (n-1)$ $\{0,1\}$-matrix with $q > {n-1 \choose 2}$ $1$-entries outside of the diagonal must
contain at least $q - {n-1 \choose 2}$ hitting pairs.

\label{lem:JuntaNormalization1}
    Let the DNF $W$ be a weakening of $M_1$ and ${\cal J}$ be a conical junta. If $\pe[W{\cal J}]<0$ there exists $N$ and $t$ such that 
    \begin{enumerate}
        \item $N$ is the normalized form of $W$ given by \hyperref[lem:normalization]{Lemma~\ref*{lem:normalization}},
        \item $t=\bra{T}[\pi]$ such that  $1\in T$, $\pi(1)=1$, and the support size of $t$ is $\leq 2\deg({\cal J})+1$
        \item $\deg(Nt)\leq 2\deg(W) + 2\deg({\cal J})$, 
        \item $\pe[Nt]<0$. 
    \end{enumerate}

\label{lem:JuntaNormalization2}
  Let $t=\bra{T}[\pi^*]$ be a term of support size $\ell$ such that
  $1\in T$ and $\pi^*(1)=1$ , and let $N$ be a normalized DNF of support size $h$ that is a weakening of $M_1$.       
        Then there is a DNF $N'$ such that 
    \begin{enumerate}
        \item For every total order $x$, $N'(x)\Leftrightarrow N(x)\wedge t(x)$. Hence, $N'$ is a weakening of $M_1\wedge t$,
        \item $N'$ is normalized with support size at most $\ell +h-1$,
        and degree at most $\ell + h -2 \leq \deg(N) + \deg(t)$,

        \item $\pe[Nt]=\pe[N'+1-t]$.
    \end{enumerate}

\label{thm:PEwJunta}
   Let $t=\bra{T^*}[\pi^*]$ be a term of support size $\ell$ such that $\pi^*(1)=1$ , and let $N$ be a normalized DNF of support size $h$ that is a weakening of $M_1$. 
   If $\ell+h\leq n/100$, then $\pe[Nt]\geq 0$.

\label{def:weakening4}
    Let $Q$ and $R$ be two $\TF\Sigma_2^{dt}$ search problems and let $(f,g)$ be an $R$-formulation of $Q$.
    We say that $(f,g)$ is a \emph{weakening} if 
    \begin{itemize}
        \item $f$ is the identity,
        \item for each $b$, $g_b$ is a constant function.
    \end{itemize}
    In particular, weakenings are formulations that are always of size $n$ and depth $1$.

\label{prop:weaknening_equiv}
    Let $Q$ and $R$ be two $\TF\Sigma_2^{dt}$ search problems.
    Then the following are equivalent:
    \begin{itemize}
        \item There exists a weakening from $Q$ to $R$,
        \item $F_{R_n}$ is a $\Sigma_2$-weakening of $F_{Q_n}$ for every $n$.
    \end{itemize}

\phantomsection\label{lem:factorization}
    Let $Q$ and $R$ be two $\TF\Sigma_2^{dt}$ problems and let $(f,g)$ be an $R$-formulation of $Q$.
    Then there exists $P\in\TF\Sigma_2^{dt}$ such that $(f,g)$ decomposes into two reductions $Q\rightarrow P\rightarrow R$ and:
    \begin{itemize}
        \item the reduction $Q\rightarrow P$ is a weakening,
        \item the reduction $P\rightarrow R$ is a counter-example reduction.
    \end{itemize}

\label{prop:SA_proof_reduced_problem}
    Let $Q$ and $R$ be two $\TF\Sigma_2^{dt}$ search problems and let $(f,g)$ be an $R$-formulation of $Q$ of size $s(n)$ and depth $d(n)$.
    If $F_{R_m}$ admits an $\SA$-refutation of degree $d'(m)$, then $F_{R(f,g)_n}$ admits one of degree $d(n)(d'(s(n))+2)$.

\label{lem:c_reduc_and_tfnp}
    Let $Q, R \in \TF\Sigma_2^{dt}$.
    If $Q$ admits low-complexity counter-example $R$-formulation, then $\mathrm{Checkable}(Q)$ admits a low-complexity $\mathrm{Checkable}(R)$-formulation.

