    \begin{itemize}
        \item $\yes$ Case: There exists $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le k$ such that $\vec H\vec x=\vec u$.
        \item $\no$ Case: For every $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le \gamma k$, we have $\vec H\vec x\neq\vec u$.
    \end{itemize}

A $\gapmaxlinq$ instance $(\vec A,\vec b)$ consists of an $m \times n$ matrix $\vec A \in \F_q^{m \times n}$ and a vector $\vec{b} \in \F_q^m$.
The objective of the problem is to distinguish between the following cases.
\begin{itemize}
    \item $\yes$ Case: There exists $\vec{x}\in \F_q^n$ such that $\|\vec A\vec x-\vec b\|_0\le (1-c)m$.
    \item $\no$ Case: For every $\vec{x}\in \F_q^n$, $\|\vec A\vec x-\vec b\|_0> (1-s)m$.
\end{itemize}

\label{def:gmld}
    A $\gapmldq$ instance $(\vec H,\vec u,\ell)$ consists of a $d\times n$ matrix $\vec H \in \F_q^{d\times n}$, a target vector $\vec u \in \F_q^d$ and a value $\ell$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le \ell$ such that $\vec H\vec x=\vec u$.
        \item $\no$ Case: For every $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le \gamma\ell$, we have $\vec H\vec x\neq\vec u$.
    \end{itemize}

\label{def:gap-MLD}\label{def:gapkmld}
    A $\gapkmldq$ instance $(\vec H,\vec u)$ consists of a $d\times n$ matrix $\vec H \in \F_q^{d\times n}$, a target vector $\vec u \in \F_q^d$ and a parameter $k\in\mathbb{N}$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le k$ such that $\vec H\vec x=\vec u$.
        \item $\no$ Case: For every $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le \gamma k$, we have $\vec H\vec x\neq\vec u$.

    \end{itemize}

\label{def:gap-NCP}
    A $\gapkncpq$ instance $(\vec A,\vec t)$ consists of a $n\times d$ matrix $\vec A \in \F_q^{n\times d}$, a target vector $\vec t \in \F_q^n$ and a parameter $k\in\mathbb{N}$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec{x}\in \F_q^d$ such that $\|\vec A\vec x-\vec t\|_0\le k$.
        \item $\no$ Case: For every $\vec{x}\in \F_q^d$, $\|\vec A\vec x-\vec t\|_0> \gamma k$.
    \end{itemize}

\label{def:gap-CVP}
    A $\gapkcvpp$ instance $(\vec A,\vec t)$ consists of a $n\times d$ matrix $\vec A \in \Z^{n\times d}$, a target vector $\vec t \in \Z^n$ and a parameter $k\in\mathbb{N}$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec{x}\in \Z^d$ such that $\|\vec A\vec x-\vec t\|_p\le k$.
        \item $\no$ Case: For every $\vec{x}\in \Z^d$, $\|\vec A\vec x-\vec t\|_p> \gamma k$.
    \end{itemize}

\label{lem:maxlin2mld}
    There exists a polynomial-time reduction that takes as input a $\gapmaxlin$ instance $(\vec A,\vec b)$ where $\vec{A} \in \mathbb{F}_q^{m \times n}$, $\vec{b} \in \mathbb{F}_q^m$ and $0<s<c<1$. The reduction outputs a $\gapmldq$ instance $(\vec H,\vec u,\ell)$ where $\vec{H}\in \mathbb{F}_q^{d\times m}\ (d\le m)$, $\vec{u} \in \mathbb{F}_q^d$, $\ell = (1-c)m$ and $\gamma = \frac{1-s}{1-c}$. This reduction satisfies the following properties:
    \begin{itemize}
        \item \textbf{Completeness:} If there exist $\vec{x} \in \mathbb{F}_q^n$ and $\vec{e} \in \mathbb{F}_q^m$ such that $\|\vec{e}\|_0 \le (1-c)m$ and $\vec{A}\vec{x} + \vec{e} = \vec{b}$, then there exists $\vec x'\in\F_q^m$ with $\|\vec x'\|_0\le\ell$ such that $\vec H\vec x'=\vec{u}$.

        \item \textbf{Soundness:} If for every $\vec{x} \in \mathbb{F}_q^n$ and $\vec{e} \in \mathbb{F}_q^m$ satisfying $\vec{A}\vec{x} + \vec{e} = \vec{b}$, we have $\|\vec{e}\|_0 > (1-s)m$, then there is no $\vec x'\in\F_q^m$ with $\|\vec x'\|_0\le\gamma\ell$ such that $\vec H\vec x'=\vec{u}$.
    \end{itemize}

\label{lem:naive_group}
    For every $\varepsilon>0$, there exists a reduction that takes as input an integer $k\in\N$, a $\gapmldq$ instance $(\vec M,\vec u,\ell)$ where $\vec M\in \mathbb{F}_q^{d\times m}$, $\vec{u} \in \mathbb{F}_q^d$, and $\frac{k}{\varepsilon}<\ell<\frac{m}{\gamma}$. The reduction outputs a new matrix $\vec{M}_k\in\F_q^{d\times m'}$ in $(m')^{O(1)}$ time, which satisfies the following properties:
    \begin{itemize}
        \item \textbf{Size:} $m'= 2^{O(\frac{m \log k}{k})}$.

        \item \textbf{Completeness:}
        If there exists $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\ell$ such that $\vec M\vec x=\vec{u}$, then there exists $\vec y\in\F_q^{m'}$ with $\|\vec y\|_0\le k$ such that $\vec M_k\vec y=\vec{u}$.

        \item \textbf{Soundness:}
        If there is no $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\gamma\ell$ such that $\vec M\vec x=\vec{u}$, then for $\gamma' = \gamma-\varepsilon$, there is no $\vec{y}\in\F_q^{m'}$ with $\|\vec y\|_0\le\gamma' k$ such that $\vec M_k\vec y=\vec{u}$.
    \end{itemize}

A $(U,k,\alpha,\varepsilon)$-cover family  is a collection $\Scal\subseteq 2^{U}$ of subsets of $U$, such that
\begin{itemize}
    \item (C1) For every $S\in\Scal$, $|S|\le\frac{(1+\varepsilon)\alpha |U|}{k}$.
    \item (C2) For every $\tilde{S}\subseteq U$ with $|\tilde{S}|\le\alpha |U|$, there exists $\{T_1,\dots,T_k\}\subseteq\Scal$ such that $\bigcup_{i\in[k]}T_i=\tilde{S}$. Moreover, $T_i\cap T_j=\emptyset$ for every $i\neq j\in[k]$.
\end{itemize}

\label{lem:cover_group}
    There exists a reduction that takes as input an integer $k\in\N$, an $([m],k,\alpha,\varepsilon)$-cover family $\Scal\subseteq 2^{[m]}$, and a $\gapmldq$ instance $(\vec M,\vec u,\alpha m)$ where $\vec M\in \mathbb{F}_q^{d\times m}$, $\vec{u} \in \mathbb{F}_q^d$. The reduction outputs a new matrix $\vec{M}_k\in\F_q^{d\times m'}$ in $(m')^{O(1)}$ time, which satisfies the following properties:
    \begin{itemize}
        \item \textbf{Size:} $m'= |\Scal|\cdot q^{\frac{(1+\varepsilon)\alpha m}{k}}$.

        \item \textbf{Completeness:}
        If there exists $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\alpha m$ such that $\vec M\vec x=\vec{u}$, then there exists $\vec y\in\F_q^{m'}$ with $\|\vec y\|_0\le k$ such that $\vec M_k\vec y=\vec{u}$.

        \item \textbf{Soundness:}
        If there is no $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\gamma\alpha m$ such that $\vec M\vec x=\vec{u}$, then there is no $\vec{y}\in\F_q^{m'}$ with $\|\vec y\|_0\le\frac{\gamma}{1+\varepsilon} k$ such that $\vec M_k\vec y=\vec{u}$.
    \end{itemize}

