Let $g \sim \mathcal{N}(0, I_d)$. Then there exists a universal  constant $C>0$ such that for any $w \geq 1$,
 \begin{equation*}
     \Pr\p{\abs{\|g\|_2 - \sqrt{d}} \leq w} \geq 1- 2e^{-Cw^2} .
 \end{equation*}

\label{prop:rand_scalar_prod}
Let $n \geq 10$ and let $v_1, \cdots, v_n$  be independent, uniform samples from the unit sphere $\mathcal{S}^{d-1}$. Then there exists a universal constant $C>0$ such that
\begin{equation*}
    \Pr\p{\forall i\neq j \in [n]: \abs{\<v_i, v_j>} \leq C \sqrt{\frac{\log n}{d}}} \geq 1 - \frac{1}{n^3}.
\end{equation*}

\label{lem:expectation_product}
     Let  $u, v$  be independent, uniform samples from the unit sphere $\mathcal{S}^{d-1}$. Then for any integer $t >1$,
    \begin{align*}
        \E \<u, v>^{2t}  \leq \frac{2^t t!}{d^t}.
    \end{align*}

\label{lem:rand_dataset_kde} 
Fix an arbitrary $r >0 $. Let $K \subset \mathcal{S}_r$ be a set containing i.i.d. uniformly random samples  from $\mathcal{S}_r$. Then for any  $\alpha > 0$ and any $q \in  \mathcal{B}_{r}$ (which can be chosen from $K$), with high probability,
\begin{align*}
    \Omega(|K|) \leq \sum_{k \in K} e^{\alpha\langle k, q \rangle} \leq |K|e^{O\left(\alpha r^2\sqrt{\frac{\log |K|}{d}}\right)} + e^{\alpha r^2}.
\end{align*}

Assume that $r = \log^{o(1)} n$, $\log n \leq d \leq \log^a n$ for some constant $a > 1$ and $n^{-100} < \eps < n^{-c}$ for an arbitrarily small constant $c > 0$. Then the Softmax KDE problem \eqref{eq:streaming-kde} can be solved using
\begin{align*}
    \tilde{O}\qty(\qty(\frac{1}{\eps})^{1 - \frac{1}{a} + o(1)})
\end{align*}
memory, where $\tilde{O}(\cdot)$ suppresses $O(\poly\log(n))$ factors. Furthermore, this bound is tight for any $d \geq \log^a n$, $a > 2$, i.e. there is a
\begin{align*}
    \tilde{\Omega}\qty(\min\qty{n, \qty(\frac{1}{\eps})^{1 - \frac{1}{a} - o(1)}})
\end{align*}
lower bound for the streaming space complexity.

Assume that $r^2 = \Omega(\log n)$, i.e. $e^{r^2} = n^{\Omega(1)}$. Then the Softmax KDE problem \eqref{eq:streaming-kde} can be solved using
\begin{align*}
\tilde{O}\qty(\frac{e^{r^2(1 + o(1))}}{\eps})
\end{align*}
memory. Furthermore, this bound is almost tight for any $d = (\log n)^{1 + \Omega(1)}$, i.e. there is a
\begin{align*}
    \tilde{\Omega}\qty(\min\qty{n, \frac{e^{r^2(1 - o(1))}}{\eps}})
\end{align*}
lower bound for streaming space complexity.

\label{def:pseudorandom}
    For a ball $B = B(c, r) \subset \R^d$, a dataset $K \subset B$ and two positive parameters $\Delta = \Delta(d, n), \tau = \tau(d, n)$, we call $K$ $(B, \Delta, \tau)$\emph{-pseudo-random}

    if the following holds:
    \begin{gather}\label{eq:sp_caps}
        \forall q \in B \quad |\{k \in K \mid \<k - c, q - c> > \Delta r^2\}| \leq \tau |K|.
    \end{gather}
    When the ball $B$ or parameters $\Delta, \tau$ are clear from the context we omit them.

{lemma}{partition}[Performance guarantees of \Partition, \Cref{alg:partition}]
    \label{lem:ps_randomification}
    For any $r_0$, $\Delta \leq 1/3$ and any dataset $K \subset B(c, r)$, $|K| \leq n$, \Partition{} produces a decomposition $\mathcal{K}$ of $K$
    \begin{gather}

        \mathcal{K} = \bigsqcup_{i=1}^{N} K_i
    \end{gather}
    such that $K_i \subset B_i = B(c_i, r_i)$ and at least one of the two holds:
    \begin{itemize}
        \item $K_i$ is $(B_i, \Delta, \tau)$-pseudo-random.
        \item $r_i < r_0$. 
    \end{itemize}
    The algorithm is successful with probability at least $1 - \frac{1}{n^2}$, has runtime $O\!\left(\frac{d}{\Delta^{4}\tau^2} \cdot |K|\log\!\left(n\right) \cdot \frac{\log (r/r_0)}{\Delta^4} \right)$ and outputs a partition of size at most

    \begin{gather*}
         \qty(\frac{\log |K|}{\Delta^2\cdot \tau})^{O\qty(\frac{\log \frac{r}{r_0}}{\Delta^4})}
    \end{gather*}

\label{lem:ps_rand_coreset}
Assume that $K'$ is $(B(c', r'), \Delta, \tau)$-pseudo-random, $r' \leq r, \tau \leq \frac{1}{2}$, $|K'| \leq n$. Then there is a randomized procedure that runs in time $O(|K'|^2 \cdot d)$ and outputs $\tilde{K}' \subset K'$ such that with high probability $1 - \frac{1}{\poly(n)}$ for any fixed $\|q\|_2 \leq r$
\begin{align*}
    \qty|\expker(K', q) - 2\expker(\tilde{K}', q)| \leq O\left(e^{r^2(1 + \Delta)}\cdot \log n \cdot \frac{\exp(K', q)}{|K'|}\right) .
\end{align*}

\label{lem:small_r_coreset}
Assume that $K'$ is contained in $B(c', r')$, $r' \leq r / 2$, $|K'| \leq n$. Then there is a randomized procedure that runs in time $O(|K'|^2 \cdot d)$ and outputs $\tilde{K}'\subset K'$ such that with probability $1 - \frac{1}{\poly(n)}$ for any fixed $\|q\|_2 \leq r$
\begin{align*}
    \qty|\expker(K', q) - 2\expker(\tilde{K}', q)| \leq O\left(e^{r^2}\cdot \log n \cdot \frac{\exp(K', q)}{|K'|}\right) .
\end{align*}

\label{lem:variance_bound}
For any $t > (\log n)^{1 - o(1)}$, any fixed $k_j$ from a sphere of radius $r$, and for uniformly random i.i.d. draws of $v_1, \cdots, v_n$ from a sphere of radius $r$, we have
\begin{align*}
    \Var{\expker_{>t}(\{v_1, \cdots, v_n\}, k_j)} = O\qty(n\frac{(2r)^{4t}}{d^t t!}).
\end{align*}

\label{th:const_r_ub_lb_attn}
Assume that $r = \log^{o(1)} n$, $\log n \leq d \leq \log^a n$ for some constant $a > 1$ and $n^{-100} < \eps < n^{-c}$ for any constant $c > 0$. Then the Attention problem can be solved using
\begin{align*}
    \tilde{O}\qty(\qty(\frac{1}{\eps})^{1 - \frac{1}{a} + o(1)})
\end{align*}
memory. Furthermore, this bound is tight for any $d \geq \log^a n$, $a > 2$, i.e. there is a
\begin{align*}
    \tilde{\Omega}\qty(\min\qty{n, \qty(\frac{1}{\eps})^{1 - \frac{1}{a} - o(1)}})
\end{align*}
lower bound for the streaming space complexity.

 \label{th:big_r_ub_lb_attn}

Assume that $r^2 = \Omega(\log n)$, i.e. $e^{r^2} = n^{\Omega(1)}$. Then the Attention problem can be solved using
 \begin{align*}
     \tilde{O}\qty(\frac{e^{r^2(1 + o(1))}}{\eps})
 \end{align*}
 memory. Furthermore, this bound is almost tight for any $d = (\log n)^{1 + \Omega(1)}$ and $r^2 < \frac{\log n}{2}$, i.e. there is a
 \begin{align*}
     \tilde{\Omega}\qty(\min\qty{n, \frac{e^{r^2(1 - o(1))}}{\eps}})
