	\label{def:triDist}
	The triangular discrimination, also known as the Le Cam divergence, between two probability distributions $p_0$ and $p_1$ on $\calX$ is defined by 
    \[\TD(p_0,p_1)  \coloneqq  \frac{1}{2}\sum_{x \in \calX} \frac{(p_0(x)-p_1(x))^2}{p_0(x)+p_1(x)}.\]

	\label{prop:JS-vs-SD}
    For any two probability distributions $p_0$ and $p_1$, the following inequalities hold\emph{:}
	\[\sum_{v=1}^{\infty} \frac{\SD(p_0,p_1)^{2v}}{\ln{2}\cdot 2v(2v-1)}=1-\binH\left(\frac{1-\SD(p_0,p_1)}{2}\right) \leq \JS_2(p_0,p_1) \leq \SD(p_0,p_1),\] 
	where the binary entropy function $\binH(x) \coloneqq -x\log_2(x)-(1-x)\log_2(1-x)$.

\label{def:HelDist}
The squared Hellinger distance between two probability distributions $p_0$ and $p_1$ on $\calX$ is defined by
$\Hsquare(p_0,p_1)  \coloneqq  \frac{1}{2} \sum_{x \in \calX} (\sqrt{p_0(x)}-\sqrt{p_1(x)})^2 = 1-\innerprod{P_0}{P_1}$, where $\ket{P_0} \coloneqq \sum_{x}\sqrt{p_0(x)}\ket{x}$ and $\ket{P_1} \coloneqq \sum_{x} \sqrt{p_1(x)}\ket{x}$.

\label{lemma:QJS-leq-traceDist}
For any quantum states $\rho_0$ and $\rho_1$, 
\[\QJS(\rho_0,\rho_1) \leq \ln{2}\cdot \td(\rho_0,\rho_1).\]

\label{fact:mutualInfo-JSD}
For any distributions $p_0$ and $p_1$, let $T$ be a binary indicator variable that chooses the value of $x$ according to $p_i$ if $T=i$ where $i\in\binset$, as well as let $X$ be a random variable associated with a uniform mixture distribution between $p_0$ and $p_1$. Then, we obtain 
\[\JS(p_0,p_1)=I(T;X)=\H(T)-\H(T|X)=1-\H(T|X).\]

	\label{def:QSDP}
    Let $Q_0$ and $Q_1$ be polynomial-size quantum circuits that act on $m(n)$ qubits and having $n$ specified output qubits, where $m$ is polynomial in $n$. For $i\in\binset$, let $\rho_i$ denote the quantum state obtained by running $Q_i$ on state $\ket{0^n}$ and tracing out the non-output qubits. Let $\alpha$ and $\beta$ denote efficiently computable functions. Then promise that one of the following cases will occur: 
	\begin{itemize}[topsep=0.33em, itemsep=0.33em, parsep=0.33em]
		\item \emph{Yes:} A pair of quantum circuits $(Q_0,Q_1)$ such that $\td(\rho_0,\rho_1) \geq \alpha(n)$; 
		\item \emph{No:} A pair of quantum circuits $(Q_0,Q_1)$ such that $\td(\rho_0,\rho_1) \leq \beta(n)$.
	\end{itemize}

	\label{def:QEDP}
    Let $Q_0$ and $Q_1$ be quantum circuits that act on $m(n)$ qubits and having $n$ specified output qubits, where $m$ is polynomial in $n$. For $i \in \binset$, let $\rho_i$ be the state obtained by running $Q_i$ in $\ket{0^n}$ and tracing out the non-output qubits. Let $g:\bbN\rightarrow\bbR^+$ be an efficiently computable function. Then promise that one of the following cases will occur: 
\begin{itemize}[topsep=0.33em, itemsep=0.33em, parsep=0.33em]
	\item \emph{Yes:} A pair of quantum circuits $(Q_0,Q_1)$ such that $\S(\rho_0)-\S(\rho_1) \geq g(n)$;
	\item \emph{No:} A pair of quantum circuits $(Q_0,Q_1)$ such that $\S(\rho_1)-\S(\rho_0) \geq g(n)$.
\end{itemize}

\label{thm:QTD-vs-td}
For any quantum states $\rho_0$ and $\rho_1$, it holds that
\[\td^2(\rho_0,\rho_1) \leq \measQTD(\rho_0,\rho_1) \leq \QTD(\rho_0,\rho_1) \leq \td(\rho_0,\rho_1).\]

\label{thm:QTD-vs-QJS}
For any quantum states $\rho_0$ and $\rho_1$, it holds that
\[\frac{1}{2}\QTD^2(\rho_0,\rho_1) \leq \QJS(\rho_0,\rho_1) \leq \QTD(\rho_0,\rho_1).\]

\label{thm:QTD-vs-B}
For any quantum states $\rho_0$ and $\rho_1$, it holds that
\[\frac{1}{2}\Bsquare(\rho_0,\rho_1) \leq \measQTD(\rho_0,\rho_1) \leq \Bsquare(\rho_0,\rho_1) \text{ and } \frac{1}{2} \Bsquare(\rho_0,\rho_1) \leq \QTD(\rho_0,\rho_1) \leq \B(\rho_0,\rho_1).\]

\label{prop:conds-QTD-eq-QSD}
For any quantum states $\rho_0$ and $\rho_1$, the equality $\QTD(\rho_0,\rho_1)=\td(\rho_0,\rho_1)$ holds if and only if these states satisfy the following conditions: 
\begin{enumerate}[label={\upshape(\roman*)}, topsep=0.33em, itemsep=0.33em, parsep=0.33em]
    \item \label{thmitem:conds-QTD-eq-QSD-classical} $(\rho_0-\rho_1)(\rho_0+\rho_1)^{-1}(\rho_0-\rho_1)=(\rho_0+\rho_1)$; 
    \item $(\rho_0-\rho_1)^{\dagger}(\rho_0-\rho_1)=\frac{\Tr\left[(\rho_0-\rho_1)^{\dagger}(\rho_0-\rho_1)\right]}{|\supp{\rho_0-\rho_1}|}I$;
    \item For any $k\in\supp{\rho_0-\rho_1}$, 
    \[\sign\rbra*{\lambda_k(\rho_0-\rho_1)}=\sign\rbra*{\lambda_k\big( (\rho_0+\rho_1)^{-1/2}(\rho_0-\rho_1)(\rho_0+\rho_1)^{1/2} \big)},\] where $\lambda_k(A)$ is the $k$-th eigenvalue of the matrix $A$. 
\end{enumerate}

\label{lemma:QSDsquare-leq-QTD}
For any quantum states $\rho_0$ and $\rho_1$, 
\[\td(\rho_0,\rho_1)^2 \leq \measQTD(\rho_0,\rho_1) \leq \QTD(\rho_0,\rho_1).\]

\label{lemma:QTDsquare-leq-QJS}
For any quantum states $\rho_0$ and $\rho_1$, 
$\frac{1}{2}\QTD^2(\rho_0,\rho_1) \leq \QJS(\rho_0,\rho_1)$.

\label{lemma:QJS-leq-QTD}
For any quantum states $\rho_0$ and $\rho_1$, 
$\QJS(\rho_0,\rho_1) \leq \QTD(\rho_0,\rho_1)$.

\label{thm:QJSP-is-QSZK-complete}
Let $\alpha(n)$ and $\beta(n)$ be efficiently computable functions such that $0 \leq \beta < \alpha \leq 1$, where $n$ denotes the number of qubits used by quantum states $\rho_0$ and $\rho_1$. Then, the following holds\emph{:}
\[ \text{For any } \alpha(n)-\beta(n) \geq 1/\poly(n), \QJSP[\alpha,\beta] \text{ is in } \QSZK. \]
Furthermore, $\QJSP[\alpha,\beta]$ is \QSZK{}-hard if $\alpha(n) \leq 1-2^{-n^{1/2-\epsilon}}$ and $\beta(n) \geq 2^{-n^{1/2-\epsilon}}$ for some constant $\epsilon\in(0,1/2)$ and sufficiently large $n$.

\label{thm:measQTDP-is-QSZK-complete}
Let $\alpha(n)$ and $\beta(n)$ be efficiently computable functions such that $0 \leq \beta < \alpha \leq 1$, where $n$ denotes the number of qubits used by quantum states $\rho_0$ and $\rho_1$. Then, it holds that\emph{:}
\begin{enumerate}[label={\upshape(\arabic*)}, topsep=0.33em, itemsep=0.33em, parsep=0.33em]
    \item For any $\alpha(n)-\beta(n) \geq 1/O(\log{n})$, $\measQTDP[\alpha,\beta]$ is in \QSZK{}; 
    \item \label{thmitem:QTDP-in-QSZK} For any $\alpha^2(n)-\beta(n) \geq 1/O(\log{n})$, $\QTDP[\alpha,\beta]$ is in \QSZK{}.
\end{enumerate}
Furthermore, $\measQTDP[\alpha,\beta]$ and $\QTDP[\alpha,\beta]$ are \QSZK{}-hard if $\alpha(n) \leq 1-2^{-n^{1/2-\epsilon}}$ and $\beta(n) \geq 2^{-n^{1/2-\epsilon}}$ for some constant $\epsilon\in(0,1/2)$ and sufficiently large $n$.

\label{corr:simple-QSZKhardness-QEDP}    
There exists a constant $\epsilon\in(0,1/2)$ such that 
$\QEDP[g(n)]$ is \QSZK{}-hard when $g(n) \leq \frac{\ln{2}}{2} \big( 1-2^{(n-3)^{1/2-\epsilon}+1} \big)$ for sufficiently large $n$.

\label{lemma:measQTD-polarization}
Given quantum circuits $Q_0$ and $Q_1$ that prepare quantum states $\rho_0$ and $\rho_1$, respectively, there exists a deterministic procedure that takes as input $(Q_0,Q_1,\alpha,\beta,k)$, where $\alpha > \beta$, and outputs quantum circuits $\tilde{Q}_0$ and $\tilde{Q}_1$, which prepare quantum states $\tilde{\rho}_0$ and $\tilde{\rho}_1$, respectively. The resulting states satisfy\emph{:} 
\begin{align*}
    \measQTD(\rho_0,\rho_1) \geq \alpha  \quad &\Longrightarrow \quad  \measQTD(\trho_0,\trho_1) \geq 1-2^{-k},\\
    \measQTD(\rho_0,\rho_1) \leq \beta  \quad &\Longrightarrow \quad  \measQTD(\trho_0,\trho_1) \leq 2^{-k}. 
\end{align*}
Here, the states $\trho_0$ and $\trho_1$ are defined over $\widetilde{O}\Big( n k^{O\big(\frac{\beta \ln(2/\alpha)}{\alpha-\beta}\big)} \Big)$ qubits. Furthermore, when $k \leq O(1)$ or $\alpha - \beta \geq \Omega(1)$, the time complexity of the procedure is polynomial in the size of $Q_0$ and $Q_1$, $k$, and $\exp\big(\frac{\beta \log(1/\alpha)}{\alpha-\beta}\big)$.

\label{lemma:QTD-polarization}
Given quantum circuits $Q_0$ and $Q_1$ that prepare quantum states $\rho_0$ and $\rho_1$, respectively, there exists a deterministic procedure that takes as input $(Q_0,Q_1,\alpha,\beta,k)$, where $\alpha^2 > \beta$, and outputs quantum circuits $\tilde{Q}_0$ and $\tilde{Q}_1$, which prepare quantum states $\tilde{\rho}_0$ and $\tilde{\rho}_1$, respectively. The resulting states satisfy\emph{:}  
\begin{align*}
    \QTD(\rho_0,\rho_1) \geq \alpha  \quad &\Longrightarrow \quad  \QTD(\trho_0,\trho_1) \geq 1-2^{-k},\\
    \QTD(\rho_0,\rho_1) \leq \beta  \quad &\Longrightarrow \quad  \QTD(\trho_0,\trho_1) \leq 2^{-k}. 
\end{align*}
Here, the states $\trho_0$ and $\trho_1$ are defined over $\widetilde{O}\Big( n k^{O\big(\frac{\beta \ln(2/\alpha^2)}{\alpha^2-\beta}\big)} \Big)$ qubits. Furthermore, when $k \leq O(1)$ or $\alpha^2 - \beta \geq \Omega(1)$, the time complexity of the procedure is polynomial in the size of $Q_0$ and $Q_1$, $k$, and $\exp\big(\frac{\beta \log(1/\alpha^2)}{\alpha^2-\beta}\big)$.

\label{lemma:measQTDP-in-QSZK}
Let $\alpha(n)$ and $\beta(n)$ be efficiently computable functions satisfying $0 \leq \beta < \alpha \leq 1$. Then, the following holds\emph{:}
\begin{enumerate}[label={\upshape(\roman*)}, topsep=0.33em, itemsep=0.33em, parsep=0.33em]
    \item For any $\alpha(n) - \beta(n) \geq 1/O(\log{n})$,  $\measQTDP[\alpha,\beta]$ is in \QSZK{}.
    \item For any $\alpha^2(n) - \beta(n) \geq 1/O(\log{n})$, $\QTDP[\alpha,\beta]$ is in \QSZK{}.
\end{enumerate}

\label{lemma:measQTD-no-error-reduction}
Given quantum circuits $Q_0$ and $Q_1$ that prepare the quantum states $\rho_0$ and $\rho_1$, respectively, there exists a deterministic procedure that, on input $(Q_0,Q_1,l)$, produces new quantum circuits $\tilde{Q}_0$ and $\tilde{Q}_1$ preparing the states $\trho_0$ and $\trho_1$, respectively. 
These states are defined as $\trho_b=2^{-l+1}\sum_{b_1\oplus\cdots\oplus b_l=b} \rho_{b_1}\otimes \cdots \otimes \rho_{b_l} \text{ for } b\in\binset$, and satisfy the following identities\emph{:}
\[\measQTD(\trho_0,\trho_1) = \measQTD(\rho_0,\rho_1)^l \quad \text{and} \quad \QTD(\trho_0,\trho_1) = \QTD(\rho_0,\rho_1)^l.  \]

\label{lemma:measQTD-yes-error-reduction}
Given quantum circuits $Q_0$ and $Q_1$ that prepare the quantum states $\rho_0$ and $\rho_1$, respectively, there exists a deterministic procedure that, on input $(Q_0,Q_1,l)$, produces new quantum circuits $\tilde{Q}_0$ and $\tilde{Q}_1$ preparing the states $\trho_0$ and $\trho_1$. These states are defined as $\trho_b \coloneqq \rho_b^{\otimes l}$ for $b\in\binset$, and satisfy the inequalities\emph{:} 
\[1-\exp\rbra*{-\frac{l}{2} \cdot \measQTD(\rho_0,\rho_1)} \leq \measQTD(\trho_0, \trho_1)  \leq 2l \cdot \measQTD(\rho_0,\rho_1).\]

\label{lemma:QTD-yes-error-reduction}
Given quantum circuits $Q_0$ and $Q_1$ that prepare the quantum states $\rho_0$ and $\rho_1$, respectively, there exists a deterministic procedure that, on input $(Q_0,Q_1,l)$, produces new quantum circuits $\tilde{Q}_0$ and $\tilde{Q}_1$ preparing the states $\trho_0$ and $\trho_1$. These states are defined as $\trho_b \coloneqq \rho_b^{\otimes l}$ for $b\in\binset$, and satisfy the inequalities\emph{:} 
\[1-\exp\rbra*{-\frac{l}{2} \cdot \QTD(\rho_0,\rho_1)^2} \leq \QTD(\trho_0, \trho_1)  \leq \sqrt{2l} \cdot \sqrt{\QTD(\rho_0,\rho_1)}.\]

\label{thm:easy-regimes-for-QSZK}
For any efficiently computable functions $\alpha$ and $\beta$, we have the following easy regimes for \QSZK{} in terms of \coQSDP{}: 
\begin{enumerate}[label={\upshape(\roman*)}, topsep=0.33em, itemsep=0.33em, parsep=0.33em]
    \item \label{thmitem:QSZK-easy-regimes-PP} $\coQSDP[\alpha,\beta]$ is in \PP{} when $1-2^{-n/2-1} \leq \alpha(n) \leq 1$ and $0 \leq \beta(n) \leq 2^{-n/2-1}$. 
    \item \label{thmitem:QSZK-easy-regimes-NQP} $\coQSDP[1,0]$ is in \NQP{}. 
\end{enumerate}

\label{sav1}\cite{Sav02}  There exists a family of functions 
\[\{G_i: \{0, 1\}^{4^i} \rightarrow \{0, 1\} \}_{i \in \mathbb{N}} \quad{} \text{ such that}\]
 \begin{itemize}
\item[(i)] $G_i$ and $\overline{G_i}$ each have uDNF representations in which each clause has size at most $s_i = 3^i$;
\item[(ii)] $D(G_i) \geq \frac{4^i + 2}{3} = \Omega (s_i^{\gamma})$, where $\gamma = \log_3 (4) > 1$.
