\label{main-theorem}
Let $2 \leq d \leq {\frac  {c\sqrt{\log n}} {\log \log n}}$, where $c>0$ is an absolute constant, and $\BalancedSipser_d$ be the explicit $n$-variable read-once monotone depth-$d$
formula described in Section \ref{sec:sipser}.  Then any circuit $C$ of depth at most $d-1$ and size at most $S = 2^{n^{{\frac 1 {6(d-1)}}}}$ over $\{0,1\}^n$ agrees with $\BalancedSipser_d$ on at most $({\frac 1 2} + n^{-\Omega(1/d)})\cdot 2^n$ inputs.

\label{thm:killBKS}
There are functions $d(n)=\omega_n(1)$ and $S(n) = \exp((\log n)^{\omega_n(1)})$ such that there is a monotone $f: \{0,1\}^n \to \{0,1\}$ with total influence $\Inf(f) = O(\log n)$, but any circuit $C$ that
has depth $d(n)$ and agrees with $f$ on at least $({\frac 1 2} + o_n(1)) \cdot 2^n$ inputs in $\{0,1\}^n$ must have size greater than $S(n)$.

\label{fact:chernoff}
Let $\bZ_1,\ldots,\bZ_n$ be independent random variables satisfying $0 \le \bZ_i \le 1$ for all $i\in [n]$.  Let $\bS = \bZ_1 + \cdots + \bZ_n$, and $\mu = \E[\bS]$.  Then for all $\gamma\ge 0$,
\begin{align*}
\Pr[\bS \ge (1+\gamma)\mu] &\le \exp\left(-\frac{\gamma^2}{2+\gamma}\cdot \mu\right)  \\
\Pr[\bS \le (1-\gamma)\mu] & \le \exp\left(-\frac{\gamma^2}{2}\cdot \mu\right).
\end{align*}

 \label{fact:totally-standard}
Let $\delta = \delta(n) > 0$ and $n\in \N$, and suppose $\delta n = o_n(1)$. The following inequalities hold for sufficiently large $n$:
\[ 1-\delta n \le (1-\delta)^n \le 1-\lfrac1{2}\delta n.\]

\label{def:restriction}
A \emph{restriction} $\rho$ of a finite base set $\{x_\alpha\}_{\alpha\in\Omega}$ of Boolean variables is a string $\rho \in \{0,1,\ast\}^{\Omega}$.  (We sometimes equivalently view a restriction $\rho$ as a function $\rho: \Omega \to \{0,1,\ast\}.$)  Given a function $f : \zo^{\Omega} \to \zo$ and restriction $\rho \in \{0,1,\ast\}^\Omega$, the \emph{$\rho$-restriction} of $f$ is the function $(f \uhr \rho) : \zo^{\Omega}\to\zo$ where
\[ (f\uhr \rho)(x) =  f(x\uhr \rho), \quad  \text{and } (x\uhr \rho)_\alpha := \left\{
\begin{array}{cl}
x_\alpha & \text{if $\rho_\alpha = \ast$} \\
\rho_{\alpha} & \text{otherwise}
\end{array}
\right. \ \  \text{for all $\alpha\in \Omega$}.
\]
Given a distribution $\calR$ over restrictions $\{0,1,\ast\}^{\Omega}$ the \emph{$\calR$-random restriction} of $f$ is the random function $f \uhr \brho$ where $\brho\leftarrow \calR$.

Let $\rho,\rho'\in \{0,1,\ast\}^{\Omega}$ be two restrictions. Their \emph{composition}, denoted $\rho\rho'\in \{0,1,\ast\}^{\Omega}$, is the restriction defined by
\[ (\rho\rho')_\alpha = \left\{
\begin{array}{cl}
\rho_\alpha & \text{if $\rho_\alpha \in \{0,1\}$} \\
\rho'_\alpha & \text{otherwise.}
\end{array}
\right.\]
Note that $\rho \rho'$ is a refinement of $\rho$.

\label{def:projection}
The \emph{projection operator} $\proj$ acts on functions $f : \zo^{A\times [\ell]} \to \zo$ as follows. The \emph{projection of $f$} is the function $(\proj\,f) : \zo^A \to \zo$ defined by
\[
(\proj\,f)(y) = f(x) \quad \text{where $x_{a,i} = y_a$ for all $a\in A$ and $i\in [\ell]$.}
\]
Given a restriction $\rho \in \{0,1,\ast\}^{A\times [\ell]}$, the \emph{$\rho$-projection of $f$} is the function $(\proj_\rho\,f) : \zo^A \to\zo$ defined by
\[
(\proj_\rho\,f)(y) = f(x) \quad \text{where $x_{a,i} =$}
\left\{
\begin{array}{cl}
y_a & \text{if $\rho_{a,i} = \ast$} \\
\rho_{a,i} & \text{otherwise}
\end{array}
\right. \quad \text{for all $a\in A$ and $i \in [\ell]$.}
\]
Equivalently, $(\proj_\rho\,f) \equiv (\proj\,(f\uhr\rho))$. Given a distribution $\calR$ over restrictions in $\{0,1,\ast\}^{A\times [\ell]}$, the associated random projection operator is $\proj_\brho$ where $\brho \leftarrow \calR$, and for $f : \zo^{A\times [\ell]}\to\zo$ we call $\proj_\brho\,f$ its \emph{$\calR$-random projection}.

\label{def:calR-init}
The distribution $\calR_{\init}$ over restrictions $\rho$ in $\{0,1,\ast\}^{A_{d-1}\times [m]} \equiv \{0,1,\ast\}^{n}$ (recall that $w_{d-1} = m$) is defined as follows: independently for each $a \in A_{d-1}$,
\begin{equation}
\brho_b \leftarrow \left\{
\begin{array}{ll}
\{1\}^{m} & \text{with probability $\lambda$} \\
\{\ast_{1/2}, 1_{1/2} \}^{m} \setminus \{ 1\}^{m}  & \text{with probability $q$} \\
\{ 0_{1/2}, 1_{1/2} \}^{m} \setminus \{ 1\}^{m} & \text{with probability $1-\lambda-q$}.
\end{array}
\right.
\label{eq:initial}
\end{equation}

\label{def:main-projection}
Let $\tau \in \{\bullet,\circ,\ast\}^{A_k}$ where $2\le k \le d-1$. We define a distribution $\calR(\tau)$ over refinements $\brho \in \{\bullet,\circ,\ast\}^{A_k}$ of $\tau$ as follows. Independently for each $a \in A_{k-1}$, writing $S_a = S_a(\tau)$ to denote $\tau_a^{-1}(\ast) = \{ i \in [w_{k-1}] \colon \tau_{a,i} = \ast\}$ and $\brho(S_a)$ to denote the substring of $\brho_a$ with coordinates in $S_a$,
\begin{itemize}
\item If $\hat{\tau}_a = \circ$ (i.e.~if $\tau_{a,i} = \bullet$ for some $i\in [w_{k-1}]$) or if $S_a$ is not $k$-acceptable\ignore{\lnote{Check that this change does not affect typicality implies typicality (it shouldn't)}}, then
\[  \brho(S_a) \leftarrow \{ \bullet_{t_k}, \circ_{1-t_k}\}^{S_a}.\]
\item If $\hat{\tau}_a = \ast$ (i.e.~if $\tau_{a,i} \in \{\ast,\circ\}^{w_{k-1}} \setminus \{\circ\}^{w_{k-1}}$) and $S_a$ is $k$-acceptable, then
\begin{equation} \brho(S_a) \leftarrow \left\{
\begin{array}{ll}
\circ^{S_a} & \text{with probability $\lambda$} \\
\{ \ast_{t_k}, \circ_{1-t_k}\}^{S_a} \setminus \{ \circ\}^{S_a} & \text{with probability $q_a$}   \\
\{ \bullet_{t_k}, \circ_{1-t_k}\}^{S_a} \setminus \{ \circ\}^{S_a} & \text{with probability $1-\lambda - q_a$},
\end{array}
\right.\label{eq:OW-restriction}
\end{equation}
where
\begin{equation} q_a := \frac{(1-t_k)^{|S_a|} -\lambda}{t_{k-1}} \ \text{\ is chosen to satisfy } (1-t_k)^{|S_a|} = \lambda + q_a t_{k-1}. \label{eq:def-of-qa}
\end{equation}
\end{itemize}
(Note that if $\hat{\tau}_a = \bullet$ then $\tau_{a,i} = \circ$ for all $i\in [w_{k-1}]$, and so $\tau_a$ cannot be refined further.)

For all $a\in A_{k-1}$ and $i\in [w_{k-1}]$ such that $\tau_{a,i} \in \{\bullet,\circ\}$, we set $\brho_{a,i} = \tau_{a,i}$ and so $\brho$ is indeed a refinement of~$\tau$.

\label{prop:complete-to-uniform}
Consider $f,g : \zo^n \to \zo$.  Let $\bX \leftarrow \{ 0_{1/2}, 1_{1/2}\}^{n}$. Let $\bY \leftarrow \{0_{1-t_1},1_{t_1}\}^{w_0}$ if $d$ is even, and $\bY\leftarrow \{0_{t_1}, 1_{1-t_1}\}^{w_0}$ if $d$ is odd.  Then
\[ \Pr[f(\bX) \ne g(\bX)] = \Pr[(\mathbf{\Psi}(f))(\bY) \ne (\mathbf{\Psi}(g))(\bY)]. \]

\label{lem:OW-trick-initial}
Let $\brho\leftarrow\calR_\init$ and $\bY \leftarrow \{ 0_{1-{t_{d-1}}}, 1_{t_{d-1}} \}^{(\hat{\brho})^{-1}(\ast)}$ \ignore{\lnote{This used to say $\bY \leftarrow \{0_{1-t},1_t\}^{A_{d-1}}$ but that is misleading (though the lemma is still formally correct). We will only be hitting the $\ast$'s of $\hat\rho$ with the $t$-biased distribution.}}, and consider the string $\bX \in \{0,1\}^{n} \equiv \zo^{A_{d-1} \times [m]}$ defined as follows:
\[ \bX_{a,i} = \left\{
\begin{array}{cl}
\bY_a & \text{if $\brho_{a,i} = \ast$} \\
\brho_{a,i} & \text{otherwise}
\end{array}
\quad \text{for all $a\in A_{d-1}$ and $i\in [m]$.}
\right.\]
The string $\bX$ is distributed according to the uniform distribution $\{ 0_{1/2},1_{1/2}\}^{n}$. (Recalling Remark~\ref{rem:complete-dead-blocks} we have that $\brho_{a,i} = \ast$ if and only if $\hat\brho_a =\ast$, and so $\bY_a$ in the equation above is indeed well-defined.)

\label{lem:OW-trick-subsequent}
For $2\le k \le d-1$ let $\tau \in \{0,1,\ast\}^{A_k}$, $\brho\leftarrow\calR(\tau)$, and
\[
\begin{cases}
\bY \leftarrow \{0_{1-t_{k-1}},1_{t_{k-1}}\}^{(\hat\brho)^{-1}(\ast)} & \text{~if~}d - k \equiv 0 \mod 2\\
\bY \leftarrow \{0_{t_{k-1}},1_{1-t_{k-1}}\}^{(\hat\brho)^{-1}(\ast)} & \text{~if~}d - k \equiv 1 \mod 2.
\end{cases}
\]
For each $a \in A_{k-1}$, writing $S_a = S_a(\tau)$ to denote $\tau_a^{-1}(\ast) = \{ i \in [w_{k-1}] \colon \tau_{a,i} = \ast\}$ and $\brho(S_a)$ to denote the substring of $\brho_a$ with coordinates in $S_a$, we consider the string $\bZ_a \in \{0,1\}^{S_a}$ defined as follows:
\[ \bZ_{a,i} = \left\{
\begin{array}{cl}
\bY_a & \text{if $\brho_{a,i} = \ast$} \\
\brho_{a,i} & \text{otherwise}
\end{array}
\quad \text{for all $i\in S_a$.}
\right.\]
The string $\bZ_a$ is distributed according to
\[
\begin{cases}
\{ 0_{t_k},1_{1-{t_k}}\}^{S_a} & \text{~if~}d - k \equiv 0 \mod 2\\
\{ 0_{1-t_k},1_{t_k}\}^{S_a} & \text{~if~}d - k \equiv 1 \mod 2,
\end{cases}
\]
and furthermore, $\bZ_a$ and $\bZ_{a'}$ are independent for any two distinct $a,a' \in A_{k-1}$.  (Again, recalling Remark~\ref{rem:complete-dead-blocks} we have  that $\brho_{a,i} = \ast$ if and only if $\hat\brho_a =\ast$, and so $\bY_a$ in the equation above is indeed well-defined.)

\label{lem:OW-trick-subsequent}
For $2\le k \le d-1$ where $d-k \equiv 0 \mod 2$ let $\tau \in \{0,1,\ast\}^{A_k}$, $\brho\leftarrow\calR(\tau)$, and $\bY \leftarrow \{0_{1-t_{k-1}},1_{t_{k-1}}\}^{(\hat\brho)^{-1}(\ast)}$\ignore{\lnote{Again the exponent here used to be $A_{k-1}$}}.  For each $a \in A_{k-1}$, writing $S_a = S_a(\tau)$ to denote $\tau_a^{-1}(\ast) = \{ i \in [w_{k-1}] \colon \tau_{a,i} = \ast\}$ and $\brho(S_a)$ to denote the substring of $\brho_a$ with coordinates in $S_a$, we consider the string $\bX_a \in \{0,1\}^{S_a}$ defined as follows:
\[ \bX_{a,i} = \left\{
\begin{array}{cl}
\bY_a & \text{if $\brho_{a,i} = \ast$} \\
\brho_{a,i} & \text{otherwise}
\end{array}
\quad \text{for all $i\in S_a$.}
\right.\]
The string $\bX_a$ is distributed according to $\{ 0_{t_k},1_{1-{t_k}}\}^{S_a}$, and furthermore, $\bX_a$ and $\bX_{a'}$ are independent for any two distinct $a,a' \in A_{k-1}$.  (Again, recalling Remark~\ref{rem:complete-dead-blocks} we have  that $\brho_{a,i} = \ast$ if and only if $\hat\brho_a =\ast$, and so $\bY_a$ in the equation above is indeed well-defined.)

\label{prop:preserve-dist}
Let $\brho^{(d)} \leftarrow\calR_\init$ and $\brho^{(k)}\leftarrow\calR(\hat{\brho^{(k+1)}})$ for $2\le k \le d-1$.  Let
\[  \bY^{(1)} \leftarrow
\begin{cases}
 \{ 0_{1-t_1}, 1_{t_1}\}^{(\hat{\brho^{(2)}})^{-1}(\ast)} & \text{~if $d$ is even}\\
 \{ 0_{t_1}, 1_{1-t_1}\}^{(\hat{\brho^{(2)}})^{-1}(\ast)} & \text{~if $d$ is odd},\\
\end{cases}
\]
and for $2 \le k \le d-1$ consider random strings $\bY^{(k)} \in \zo^{(\hat{\brho^{(k+1)}})^{-1}(\ast)}$ defined inductively from $k=2$ up to $d-1$ as follows:
\begin{equation}
\bY^{(k)}_{a,i} = \left\{
\begin{array}{cl}
\bY^{(k-1)}_a & \text{if $\brho^{(k)}_{a,i} = \ast$}  \\
\brho^{(k)}_{a,i} & \text{otherwise}
\end{array}
\right.\quad \text{for all $a\in A_{k-1}$ and $i \in [w_{k-1}]$ s.t.~$\hat{\brho^{(k+1)}}_{a,i} = \ast$}.
\label{eq:def-of-Y}
\end{equation}
Then the string $\bX \in \{0,1\}^n \equiv \zo^{A_{d-1}\times [m]}$ defined by
\[ \bX_{a,i} = \left\{
\begin{array}{cl}
\bY^{(d-1)}_a & \text{if $\brho_{a,i} = \ast$} \\
\brho^{(d)}_{a,i} & \text{otherwise}
\end{array}
\quad \text{for all $a\in A_{d-1}$ and $i\in [m]$}
\right.\]
is distributed according to the uniform distribution $\{0_{1/2},1_{1/2}\}^n$.

\label{prop:preserve-dist}
Let $d \ge 2$ be even. (A symmetric argument establishes the dual claim for odd values of $d$.) Let $\brho^{(d)} \leftarrow\calR_\init$ and $\brho^{(k)}\leftarrow\calR(\hat{\brho^{(k+1)}})$ for $2\le k \le d-1$.  Let
\[ \bY^{(1)} \leftarrow \{ 0_{1-t_1}, 1_{t_1}\}^{(\hat{\brho^{(2)}})^{-1}(\ast)},\]
and for $2 \le k \le d-1$ consider random strings $\bY^{(k)} \in \zo^{(\hat{\brho^{(k+1)}})^{-1}(\ast)}$ defined inductively from $k=2$ up to $d-1$ as follows:
\begin{equation}
\bY^{(k)}_{a,i} = \left\{
\begin{array}{cl}
\bY^{(k-1)}_a & \text{if $\brho^{(k)}_{a,i} = \ast$}  \\
\brho^{(k)}_{a,i} & \text{otherwise}
\end{array}
\right.\quad \text{for all $a\in A_{k-1}$ and $i \in [w_{k-1}]$ s.t.~$\hat{\brho^{(k+1)}}_{a,i} = \ast$}.
\label{eq:def-of-Y}
\end{equation}
Then the string $\bX \in \{0,1\}^n \equiv \zo^{A_{d-1}\times [m]}$ defined by
\[ \bX_{a,i} = \left\{
\begin{array}{cl}
\bY^{(d-1)}_a & \text{if $\brho_{a,i} = \ast$} \\
\brho^{(d)}_{a,i} & \text{otherwise}
\end{array}
\quad \text{for all $a\in A_{d-1}$ and $i\in [m]$}
\right.\]
is distributed according to the uniform distribution $\{0_{1/2},1_{1/2}\}^n$.

Let $d$ be even and consider $\BalancedSipser_d$. (A symmetric argument establishes the dual claim for odd values of $d$.) Let $\brho^{(d)} \leftarrow\calR_\init$ and $\brho^{(k)}\leftarrow\calR(\hat{\brho^{(k+1)}})$ for $2\le k \le d-1$.  Let $\bY^{(1)} \leftarrow \{ 0_{1-t_1}, 1_{t_1}\}^{w_0}$, and consider random strings $\bY^{(k)} \in \zo^{A_k}$ defined inductively from $k=2$ up to $d$ as follows:
\begin{equation}
\bY^{(k)}_{a,i} = \left\{
\begin{array}{cl}
\bY^{(k-1)}_a & \text{if $\brho^{(k)}_{a,i} = \ast$}  \\
\brho^{(k)}_{a,i} & \text{otherwise}
\end{array}
\right.\quad \text{for all $a\in A_{k-1}$ and $i \in [w_{k-1}]$}.
\label{eq:def-of-Y}
\end{equation}
Then the string $\bY^{(d)} \in \zo^{n}$ is distributed according to the uniform distribution $\{ 0_{1/2},1_{1/2}\}^{n}$.

For any $\eta\sse \calY$ and assignment $\pi \in \zo^{\eta}$, the restriction $(\eta \mapsto\pi) \in \{0,1,\ast\}^{A\times [w]}$ to the variables in $\calX$ is defined as follows: for all $a \in A$ and $i\in [w]$,
\[ (\eta\mapsto\pi)_{a,i} = \left\{
\begin{array}{cl}
\pi(y_a) & \text{if $y_a \in \eta$} \\
\ast & \text{otherwise.}
\end{array}
\right.\]

\label{def:proj-tree}
Let $G : \zo^{A\times [w]}\to\zo$ be a DNF over $\calX$,  where we assume a fixed but arbitrary ordering on its terms, and likewise on the literals within each term. The \emph{canonical projection decision tree} $\Tree(G) : \zo^A\to\zo$ associated with $G$ is defined recursively as follows:
\begin{enumerate}
\item If $G \equiv 1$ (i.e.~if $G(X) = 1$ for all $X\in\zo^{A \times [w]}$) output the trivial decision tree $\Tree(G) \equiv 1$, and likewise, if $G \equiv 0$ output $\Tree(G) \equiv 0$.
\item Otherwise, let $T$ be the first term in $G$ such that $T \not\equiv 0$, and let
\[ \eta = \big\{ y_a \colon x_{a,i} \text{ occurs in $T$ for some $i\in [w]$}\big\} \sse \calY \]
\item $\Tree(G)$ queries all the variables in $\eta$ in its first $|\eta|$ levels.
\item For each path $\pi \in \zo^{\eta}$, recurse on $G \uhr (\eta\mapsto\pi)$.
\end{enumerate}

\label{fact:weights}
Fix $\tau \in \{0,1,\ast\}^{A_k}$, and  write $S_a = S_a(\tau)$ to denote $\tau_a^{-1}(\ast) = \{ i \in [w_{k-1}] \colon \tau_{a,i} = \ast\}$.  Then $\Prx_{\brho\leftarrow\calR(\tau)}[\brho = \rho] = \xi(\rho)$ for all $\rho\in \{0,1,\ast\}^{A_k}$, where $\xi : \{0,1,\ast\}^{A_k} \to [0,1]$ is the probability mass function:
\[  \xi(\rho) = \mathop{\prod_{a\in A_{k-1}}}_{S_a \ne \emptyset} \zeta_a(\rho(S_a)), \]
and $\rho(S_a)$ denotes the substring of $\rho_a$ with coordinates in $S_a$, and $\zeta_a : \{0,1,\ast\}^{S_a} \to [0,1]$ is the probability mass function:
\begin{align*}
  \zeta_a(\varrho)
  &=
  \begin{cases}
       \ds
     \lambda
     &\text{if } \varrho = \{1\}^{S_a},\\
     \ds
     q_a \cdot \frac{{t_k}^{|\varrho^{-1}(\ast)|}(1-t_k)^{|\varrho^{-1}(1)|}}{1-(1-t_k)^{|S_a|}}
     &\text{if } \varrho \in \{\ast,1\}^{S_a} \setminus \{1\}^{S_a},\\
     \ds
(1-\lambda-q_a) \cdot  \frac{{t_k}^{|\varrho^{-1}(0)|}(1-t_k)^{|\varrho^{-1}(1)|}}{1-(1-t_k)^{|S_a|}}
     &\text{if } \varrho \in \{0,1\}^{S_a} \setminus \{1\}^{S_a}.
  \end{cases}
\end{align*}

\label{fact:init-weights}
$\Prx_{\brho\leftarrow\calR_\init} [\brho = \rho] = \xi(\rho)$ for all $\rho\in \{0,1,\ast\}^{A_{d-1}\times [m]}$ (recall that $w_{d-1} = m$), where $\xi : \{0,1,\ast\}^{A_{d-1} \times [m]} \to [0,1]$ is the probability mass function:
\[  \xi(\rho) = \prod_{a\in A_{d-1}}\zeta(\rho_a), \]
and $\zeta : \{0,1,\ast\}^{m} \to [0,1]$ is the probability mass function:
\begin{align*}
  \zeta(\varrho)
  &=
  \begin{cases}
       \ds
     \lambda
     &\text{if } \varrho = \{1\}^{m},\\
     \ds
     q \cdot \frac{p}{1-p}
     &\text{if } \varrho \in \{\ast,1\}^{m} \setminus \{1\}^{m},\\
     \ds
(1-\lambda-q) \cdot  \frac{p}{1-p}
     &\text{if } \varrho \in \{0,1\}^{m} \setminus \{1\}^{m}.
  \end{cases}
\end{align*}

\label{thm:different-alternation} For $2\leq d \leq  {\frac {c\sqrt{\log n}}{\log \log n}}$, let $C : \zo^{n} \to \zo$ be a depth-$d$ circuit of size $S \le 2^{{\frac 1 2}n^{{\frac 1 {6(d-1)}}}}$ and unbounded bottom fan-in.
\begin{enumerate}
\item If the top gate of $C$ is an $\AND$, then $\mathbf{\Psi}(C)$ is $(1/S)$-close (with respect to the uniform distribution on $\{0,1\}^n$) to a width-$n^{{\frac 1 {4(d-1)}}}$ CNF with probability $1-\exp\big(-\Omega\big(n^{\frac 1 {{6}(d-1)}}\big)\big)$.
\item If the top gate of $C$ is an $\OR$, then $\mathbf{\Psi}(C)$ is $(1/S)$-close to a width-$n^{{\frac 1 {4(d-1)}}}$ DNF with probability  $1-\exp\big(-\Omega\big(n^{\frac 1 {{6}(d-1)}}\big)\big)$.
\end{enumerate}

\label{lem:combine}
Suppose that $3 \leq d \leq {\frac {c\log w}{\log \log w}}$.
For $2 \le k \le d-1$ and $\ell\in \N$, let $C : \zo^{A_{k+1}} \to\zo$ be a size-$S$ depth-$\ell$ circuit with bottom fan-in $w^{1/5}$.\ignore{ Let $\tau \in \{\bullet,\circ,\ast\}^{A_{k+1}}$ be typical.} For any $\tau \in \{\bullet,\circ,\ast\}^{A_{k+1}}$, with probability at least $1-S\cdot 4^{-w^{1/5}}\ignore{ - e^{-\Omega(w^{1/6})}}$ over $\brho\leftarrow\calR(\tau)$, we have that $\proj_{\brho}\,C$ is a depth-$(\ell-1)$ circuit with  bottom fan-in $w^{1/5}$, and has the same number of gates at distance at least two from the input variables as~$C$.

\label{prop:bounded-bottom-fan-in}
For $2 \leq d \leq {\frac {c\sqrt{\log n}}{\log \log n}}$,
let $C : \zo^{A_{d}} \to \zo$ be a depth-$d$ circuit with bottom fan-in $\frac1{5} m$ and size $S \le 2^{w^{1/5}}$.  Then $\mathbf{\Psi}(C)$ is computed by a depth-$(w^{1/5})$ decision tree with probability $1-e^{-\Omega(w^{1/{5}})}$.

\label{lem:truncate}
Let $C : \zo^n \to \zo$ be a circuit and let $\eps > 0$. There exists a circuit $C' : \zo^n\to\zo$ such that
\begin{enumerate}
\item The size and depth of $C'$ are both at most that of $C$;
\item The bottom fan-in of $C'$ is at most $\log(S/\eps)$;
\item $C$ and $C'$ are $\eps$-close with respect to the uniform distribution.
\end{enumerate}

\label{prop:different-alternation}
For $2 \leq d \leq  {\frac {c\sqrt{\log n}}{\log \log n}}$,
let $C : \zo^{A_d} \to \zo$ be a depth-$d$ circuit of size $S \le 2^{\frac1{2}w^{1/5}}$ and unbounded bottom fan-in.
\begin{enumerate}
\item If the top gate of $C$ is an $\AND$, then $\mathbf{\Psi}(C)$ is $(1/S)$-close to a width-$(w^{1/5})$ CNF with probability $1-e^{-\Omega(w^{1/5})}$.
\item If the top gate of $C$ is an $\OR$, then $\mathbf{\Psi}(C)$ is $(1/S)$-close to a width-$(w^{1/5})$ DNF with probability $1-e^{-\Omega(w^{1/5})}$.
\end{enumerate}

 \label{def:typical}
Let $\tau \in \{\bullet,\circ,\ast\}^{A_k}$ where $2\le k \le d-1$.  We say that $\tau$ is \emph{typical} if it satisfies:
\begin{enumerate}
\item For every $a\in A_{k-1}$ the set $\tau^{-1}_a(\ast) \sse [w_{k-1}]$ is $k$-acceptable, where we recall from Definition~\ref{def:acceptable} that this means
\[ |\tau^{-1}_a(\ast)| = qw \pm w^{\gradual(k,d)} \quad \text{where $\gradual(k,d) := \frac1{3} + \frac{d-k-1}{12d}$}. \] (Note  that $\frac1{3} \le \gradual(k,d) \le \frac{5}{12} < \frac1{2}$ for all $d\in \N$ and $2\le k \le d-1$.) We observe that by Definition \ref{def:lift}, this condition implies that for every $\alpha \in A_{k-2}$, we have
\begin{equation}
\hat{\tau}_\alpha \in \{ \ast, \circ \}^{w_{k-2}}.  \label{eq:old-prop-2-of-typicality}
\end{equation}
\item For every $\alpha \in A_{k-2}$,
\[ |(\hat{\tau}_\alpha)^{-1}(\ast)| \ge w_{k-2}- w^{4/5}. \]
\end{enumerate}
We note that (\ref{eq:old-prop-2-of-typicality}) and Condition (2)  together imply that
\[ \hat{\hat{\tau}}_\alpha  = \ast  \quad \text{for all $\alpha\in A_{k-2}$.} \]

 [Condition (1) of typicality] \label{lemma:condition1-initial}
Fix $a\in A_{d-2}$. Then
\[ \Pr\big[|\btau_a^{-1}(\ast)| = qw \pm  w^{1/3}\big] \ge 1- e^{-{\tilde{\Omega}}(w^{1/6})}. \]

 \label{lemma:condition2-initial}
Fix $\alpha \in A_{d-3}$. Then
\[ \Pr\big[\hat\btau_\alpha \in \{ \ast,1\}^{w_{d-3}} \big] \ge \ignore{1- w e^{-qw} = }1- e^{-{\Omega}(\sqrt{w})}. \]

 \label{lemma:condition3-initial}
Fix $\alpha \in A_{d-3}$.  Then
\[ \Pr\big[|(\hat\btau_\alpha)^{-1}(\ast)| <  w_{d-3}-w^{4/5} \big] \le e^{-\Omega(\sqrt{w})}.\]

\label{lemma:haha}
Fix $2 \le k \le d-2$ and let $\tau \in \{\bullet,\circ,\ast\}^{A_{k+1}}$ be typical.  For each $a\in A_{k-1}$ we write $S_a = S_a(\tau)$ to denote $(\hat\tau_a)^{-1}(\ast)$ (note that this is a subset of $[w]$).  Then for $\brho\leftarrow \calR(\tau)$,  we have that $\hat\brho_a$ (which is a string in $\{\bullet,\circ,\ast\}^{w}$) satisfies:
\[  \left\{
\begin{array}{ll}
 \hat\brho_a = \{\circ\}^{w} & \text{with probability~$\prod_{i\in S_a} (1-\lambda-q_{a,i})$}  \\
 (\hat\brho_a)^{-1}(\bullet) \ne \emptyset & \text{with probability~$1-(1-\lambda)^{|S_a|}$}  \\
 \hat\brho_a \in \{ \circ,\ast\}^{w} \setminus \{\circ\}^{w} & \text{otherwise,}
\end{array}
\right.
\]
 independently for all $a \in A_{k-1}$. (Recall that $\hat\tau_a \in \{\ast,\circ\}^{w} \setminus \{\circ\}^{w}$ for all $a\in A_{k-1}$ since $\tau$ is typical.) This implies that
\[ \hat{\hat\brho}_a = \left\{
\begin{array}{ll}
 \bullet & \text{with probability~$\prod_{i\in S_a} (1-\lambda-q_{a,i})$}  \\
\circ& \text{with probability~$1-(1-\lambda)^{|S_a|}$}  \\
\ast & \text{otherwise}
\end{array}
\right.
\]
 independently for all $a \in A_{k-1}$. (Recall that $\hat{\hat\tau}_a = \ast$ for all $a\in A_{k-1}$ since $\tau$ is typical.)

 [Condition ({2}) of typicality] \label{lemma:condition3-yields}
For $2\le k \le d-2$  let $\tau \in \{ \bullet,\circ,\ast\}^{A_{k+1}}$ be typical and fix $\alpha \in A_{k-2}$. Then
