A \emph{quantum computationally secure commitment scheme} for an alphabet
$\Gamma$ is a collection of polynomial-time computable functions
$\{f_n\,:\,n\in\natural\}$ taking the form
\begin{equation}
  f_n:\Gamma\times\{0,1\}^{p(n)} \rightarrow \{0,1\}^{q(n)},
\end{equation}
for polynomially bounded functions $p$ and $q$, such that the following
conditions hold:
\begin{mylist}{\parindent}
\item[1.]
  \emph{Unconditionally binding property.}
  For every choice of $n\in\natural$, $a,b\in\Gamma$, and
  $r,s\in\{0,1\}^{p(n)}$, one has that $f_n(a,r) = f_n(b,s)$ implies $a=b$.
\item[2.]
  \emph{Quantum computationally concealing property.}
  For every $a\in\Gamma$ and $n\in\natural$, define
  \begin{equation}
    \rho_{a,n} = \frac{1}{2^{p(n)}}\sum_{r\in\{0,1\}^{p(n)}}
    \ket{f_n(a,r)}\bra{f_n(a,r)}.
  \end{equation}
  For every choice of $a,b\in\Gamma$ the ensembles
  $\{\rho_{a,n}\,:\,n\in\natural\}$ and $\{\rho_{b,n}\,:\,n\in\natural\}$
  are quantum computationally indistinguishable.
\end{mylist}

Let $P$ and $Q$ be probability distributions over $S$. We define the following distance measures between distributions.
\begin{align*}
\text{Total variation distance:}& \quad \VR(P,Q) \defeq \max_{T \subseteq S}  \sum_{s \in T}\big(P(s) - Q(s)\big) = \frac{1}{2}\sum_{s\in S} |P(s) - Q(s)|.  \\
\text{Hellinger distance:}& \quad \h(P,Q) \defeq 
\frac{1}{\sqrt{2}} \sqrt{\sum_{s \in S}\left(\sqrt{P(s)}-\sqrt{Q(s)}\right)^2 } . 
\end{align*}

\label{fact:relation-inf}
Let $P$ and $Q$ be probability distributions. Then
\begin{align*}
&\quad \frac{1}{\sqrt{2}}\VR(P,Q) \leq \h(P,Q) \leq \sqrt{ \VR(P,Q)}. 
\end{align*}

\label{fact:prod} 
$\VR(P\otimes Q, P' \otimes Q')   \leq  \VR(P, P') + \VR(Q, Q').$
Additionally, if $Q= Q'$ then $\VR(P\otimes Q, P' \otimes Q')  = \VR(P, P')$.

\label{def:entropy}
Let $XYZ \in \X \times \Y \times \Z$ be correlated random variables. We define the following measures, where $\log(\cdot)$ denotes the base $2$ logarithm.
\begin{align*}
\text{Mutual information:}& \quad  \I(X:Y) \defeq \sum_{xy} \Pr(XY=(x,y)) \log \(\frac{\Pr(XY=(x,y))}{\Pr(X=x)\Pr(Y=y)}\) .\\
\text{Conditional mutual information:}& \quad   \I(X:Y~|~Z) \defeq \E_{z\leftarrow Z} \I(X : Y ~|~ Z=z) = \E_{z\leftarrow Z} \I(X^z : Y^z).
\end{align*}

 \label{fact:ID}
Let $XY \in \X \times \Y$ be correlated random variables. Then
$$\I(X:Y) \geq \VR^2(XY,X\otimes Y) \qquad \textrm{and} \qquad \I(X:Y) \geq \E_{x \leftarrow X} \VR^2(Y^x,Y).$$

\label{fact:I2}
	Let $AB$ be correlated random variables with $A \in \B$. Let $p \defeq \Pr(A=0)$,  $B^0 := (B~|~A=0)$, and $B^1 := (B~|~A=1)$. Then
	\[\I(A:B)\leq  2\log e \enspace  \VR(pB^0,(1-p)B^1).\]

