$$\HQIC (\Pi, \mu^{\otimes k}) \geq \frac{1}{40000 t}.$$

{theorem}{upperbound}
    \label{thm:upperbound}
    There is a quantum algorithm~$\alg$ that,    
    given black-box access to an unknown $\dd$-dimensional unitary channel $Z \in \UU(\dd)$ and any $\eps > 0$, outputs a classical description of a unitary. This output is probabilistic and can be viewed as a $\UU(\dd)$-valued random variable $\wh{\bZ}$. The algorithm satisfies the following properties:
\begin{enumerate}
    \item \textup{(Query complexity)} $\alg$ queries the black box $O(\dd^2/\eps)$ times.
    \item \textup{(Space complexity)} $\alg$ only uses one qudit of dimension $\dd$. Specifically, it only prepares states of the form $V_2 (Z V_1)^p V_0 \ket 0$, where the positive integer~$p$ and unitaries~$V_0, V_1, V_2 \in \UU(\dd)$ are adaptively chosen, and measures them in the computational basis.
    \item \textup{(Gate complexity)} If the $\dd$-dimensional qudit is embedded in $\nn = \lceil \log_2 \dd \rceil$ qubits, then $\alg$ uses $\poly(\dd,1/\eps)$ one- and two-qubit quantum gates in total beyond the queries to the black box, and the classical time complexity is $\poly(\dd,1/\eps)$.
    \item \textup{(Closeness of output unitary)} The unitary output by $\alg$ is $\eps$-close to the unknown $Z$ in diamond norm with high probability. Specifically, $\E[~\diamnorm{\calU(\wh{\bZ})- \calU(Z)}^2~] \le \eps^2$, which implies $\Pr[~ \diamnorm{\calU(\wh{\bZ}) - \calU(Z)} \le 3\eps~] \ge \tfrac 2 3$.
    \item \textup{(Closeness of output channel)} We can also view the output of $\alg$ as a channel. Let $\calM$ denote the mixed unitary channel induced by running~$\alg$ on~$Z$ and then applying its output $\wh{\bZ}$. Then $\diamnorm*{\calM  - \calU(Z)} \le \eps^2$. \label{item:upperbound-channel}
\end{enumerate}

{theorem}{lowerbound}
    \label{thm:lowerbound}
    Let $\alg$ be an algorithm that, for an unknown $\dd$-dimensional unitary $Z \in \UU(\dd)$ accessible through black box oracles that implement $Z$, $Z^\dagger$, $\controlled Z = \ket 0 \bra 0 \otimes \id + \ket 1 \bra 1 \otimes Z$, and $\controlled Z^\dagger = \ket 0 \bra 0 \otimes \id + \ket 1 \bra 1 \otimes Z^\dag$, can output a classical description of a unitary channel $\calU(\wh{\bZ})$ such that $\diamnorm{\calU(\wh{\bZ}) - \calU(Z)} < \eps < \frac{1}{8}$ with probability $\geq \tfrac 2 3$.
    Then $\alg$ must use $\Omega(\frac{\dd^2}{\eps})$ oracle queries.

\label{def:p-op-norm}
    For unitaries $U, V \in \UU(\dd)$ we define
    \begin{equation}
        \pudist{U}{V} = \min_{\phi \in \uone} \|\phi U - V\|_{\mathrm{op}}.
    \end{equation}

\label{def:pu-lie-norm}
    We consider the length of a path on the Lie group $\UU(\dd)$ with respect to the operator norm on the tangent space~$\uu(\dd)$.
    For unitaries $U, V \in \UU(\dd)$, we define $\dist(U, V)$ to be the length of a shortest smooth 
    path~$\gamma: [0,1] \to \UU(\dd)$ between them ($\gamma(0) = U, \gamma(1) = V$).
    As an equation,
    \begin{equation}
        \dist(U, V) = \inf_{\text{paths}\,\gamma} \operatorname{len}(\gamma),
        \qquad \text{where}\,\operatorname{len}(\gamma) = \int_0^1  \opnorm{\gamma'(t) \gamma(t)^{-1}} \rd t = \int_0^1  \opnorm{\gamma'(t)} \rd t .
    \end{equation}
    We further define the corresponding metric on the projective group $\PPUU(\dd)$ via this metric.
    \begin{equation}
        \dist(U, \uone V) = \inf_{\phi \in \uone} \dist(U, \phi V)
    \end{equation}

{proposition}{normeq} \label{prop:norm-equivalence}
    For unitaries $U, V \in \UU(\dd)$, the metrics $\diamnorm{\calU(U) - \calU(V)}$, $\pudist{U}{V}$, and $\dist(U, \UU(1)V)$ are equivalent up to constants.
    Specifically, the following inequalities hold.
    \begin{gather}
        \pudist{U}{V} \leq \dist(U, \uone V) \leq \tfrac{\pi}{2}\pudist{U}{V} \label{eq:pudist-lie} \\
        \half\diamnorm{\calU(U) - \calU(V)} \leq \pudist{U}{V} \leq \diamnorm{\calU(U) - \calU(V)} \label{eq:diam-pudist}
    \end{gather}

The \emph{entanglement infidelity} between $\dd$-dimensional channels $\calE_1, \calE_2$ is defined to be 
\begin{equation}
    \ol{F}(\calE_1,\calE_2) = 1 - F(J(\calE_1), J(\calE_2)),
\end{equation}
where $F$ is squared quantum state fidelity $F(\rho,\sigma) = (\onenorm{\sqrt \rho \sqrt \sigma})^2$
and $J(\calE)$ is the Choi state~$(\calE_A \otimes \id_B)(\tfrac{1}{\dd}\sum_{i,j} \ket{ii}\bra{jj})$ of~$\calE$.

{proposition}{fiddiam} \label{prop:ineq1}
    For all $\dd$ and any unitaries $U,V \in \UU(\dd)$,
    \begin{equation}
        4\, \ol{F}(\calU(U),\calU(V)) \leq \diamnorm{\calU(U) - \calU(V)}^2 \leq 2\dd\cdot\ol{F}(\calU(U),\calU(V)).
    \end{equation}
    The left-hand side is sharp for $\dd$ even and the right-hand side is sharp for all~$\dd \ge 2$:
    \begin{equation}
    \sup_{U \notin \uone V} \frac{\ol{F}(\calU(U),\calU(V))}{\diamnorm{\calU(U) - \calU(V)}^2} = \frac 1 4 \text{ if $\dd$ is even, and}\quad
    \sup_{U \notin \uone V} \frac{\diamnorm{\calU(U) - \calU(V)}^2}{\ol{F}(\calU(U),\calU(V))} = 2\dd.
    \end{equation}

The \emph{estimation task for unitary channels} is the following:  One is given black-box access to a unitary channel by~$Z \in \UU(\dd)$.
After applying the unitary channel some~$Q$ times, the algorithm should output a classical description\footnote{
    \label{foot:tedium}
    Throughout this paper, for ease of exposition we will be treating these descriptions as if they have infinite precision. To formalize our results when numbers can only be specified up to a machine precision $\macheps$, we consider the sets of unit vectors and unitary matrices that can be generated from $O(\log^3(1/\eps))$-depth quantum circuits.
    This discretizes these spaces into $O(\macheps)$-nets by the Solovay--Kitaev theorem. Then, a \emph{classical description} of a unitary matrix or a unit vector is a list of numbers defining a matrix or vector that need not exactly satisfy the desired constraints, but is $\macheps$-close to an element of the net. When we need to implement a unitary from its classical description, we implement this element. We only care about vectors and matrices up to $\poly(\eps/\dd)$ error, since this is the magnitude of sampling error from state tomography, which is where these classical descriptions come from. So, if we set $\macheps$ to be smaller than this, then the errors from working in finite precision are negligible, and we incur a $\polylog(1/\macheps)$ overhead (which is only $\polylog(\dd/\eps)$) in time complexity. This issue only affects constant factors in our proofs in a very minor way, and we trust the diligent reader to take note of the required changes.
} of a unitary~$\wh{\bZ} \in \UU(\dd)$.

The algorithm may be probabilistic and hence $\wh{\bZ}$ should be thought of as a random variable.
The goal is to achieve 
\begin{equation}    
    \E[\emeasure(\calU(Z),\calU(\wh{\bZ}))] < \eps.
\end{equation}
Here, $\emeasure({\cdot},{\cdot})$ is some accuracy measure between unitary channels.

\label{def:sar}
   The \emph{SAR task for unitary channels} (Storage-And-Retrieval) involves developing two quantum algorithms~\cite{Bisio2009}.  The ``storage'' algorithm~$\calS$ is given black-box access to a unitary $Z \in \UU(\dd)$; after applying the unitary some $Q$~times, $\calS$  should output a possibly mixed quantum state~$\psi$.  The ``retrieval''  algorithm~$\calR$ takes as input~$\psi$ and implements a possibly nonunitary qudit channel $\boldsymbol \calC$, which may be random with some distribution.
   This retrieval may destroy $\psi$.
   The goal is to achieve the following:
   \begin{equation}
       \Pr_{\boldsymbol \calC} [
               \emeasure(\calU(Z), \boldsymbol\calC ) > \eps
           ] \leq \eta.
   \end{equation}
   Note that here $\emeasure({\cdot},{\cdot})$ is measuring the error between a unitary channel and a possibly nonunitary channel.
   The \emph{storage complexity} of the algorithm is the number of qubits used for~$\psi$.

If $\bU$ is a $\UU(\dd)$-valued classical random variable, we denote by $\calM(\bU)$ the mixed-unitary channel associated to~$\bU$
\begin{equation}
    \calM(\bU) = \sum_X \Pr[\bU = X] ~\calU(X).
\end{equation}

{proposition}{yrcmixing} \label{prop:conv-to-SAR}
    If a unitary estimation algorithm~$\alg$ with an output distribution~$\varphi(\wh \bZ|Z)\rd \wh \bZ$
    is unitarily covariant, i.e., $\varphi(A \wh \bZ B | A Z B ) = \varphi( \wh \bZ | Z )$ for all $A,B \in \UU(\dd)$,            
    then
    \begin{equation}
            \ol F(\calU(Z), \calM(\wh \bZ) ) = \diamnorm{ \calU(Z) - \calM(\wh \bZ) }.
    \end{equation}
    Therefore, by \cref{rem:SpecialEntFid,prop:ineq1},
    \begin{equation}
            \diamnorm{ \calU(Z) - \calM(\wh \bZ) }
            = \ol F(\calU(Z), \calM(\wh \bZ) )
            = \E_{\wh \bZ} \ol F(\calU(Z), \calU(\wh \bZ) )
            \le \tfrac 1 4 \E_{\wh \bZ} [ \diamnorm{\calU(Z) - \calU(\wh \bZ) }^2 ]. \label{mixingIneq}
    \end{equation}

\label{thm:base}
   There is a tomography algorithm that, given access to an unknown unitary $Z \in \UU(\dd)$, as well as parameters $\eps, \eta > 0$, applies $Z$ at most $O(\dd^2/\eps^2) \cdot \log(1/\eta)$ times and outputs an estimate~$\bV$ satisfying $\pudist{Z}{\bV} \leq \eps$ except with probability at most~$\eta$.
   The algorithm uses only a $\dd$-dimensional Hilbert space (in particular, only $\nn$~qubits when $\dd = 2^{\nn}$).

\label{prop:puretomog}
There is a pure state tomography algorithm with the following behavior.  Given access to copies of a pure state $\ket{z} \in \CC^{\dd}$, 
it sequentially and nonadaptively makes von Neumann measurements
on~$O(\dd/\eps_0)$ copies of $\ket{z}$ (using only $\dd$-dimensional Hilbert space).
Then, after classically collating and processing the measurement outcomes, it outputs (a classical description of) an estimate pure state
\begin{equation}    \label{eqn:puretomog}
    \ket{\bu} = \bphi \sqrt{1-\beps}\ket{z} + \sqrt{\beps}\ket{\bw}
\end{equation}
such that: (i)~$\bphi$ is a complex phase; (ii)~the infidelity~$\beps$ is at most $\eps_0$ except with probability at most~$\exp(-5\dd) \leq \frac{1}{100\dd}$; (iii)~the vector~$\ket{\bw}$ is distributed Haar-randomly\footnote{Perfect Haar-randomness is only possible by making idealized assumptions about the algorithm's hardware; such technical issues of algorithmic complexity are deferred to \cref{foot:tedium}.} among all states orthogonal to~$\ket{z}$.

\label{prop:weaker-base}
   Let $\tomalg$ be a tomography algorithm as in \Cref{thm:base}, except with the following weaker guarantee about~$\bV$:
   \begin{equation}    \label{eqn:weaker-base}
       \exists \text{ a diagonal unitary~$\Phi$ such that } \opnorm{Z \Phi - \bV} \leq \eps \leq \tfrac{1}{8}.
   \end{equation}
   Then there is a tomography algorithm (using~$\tomalg$ twice) that achieves \Cref{thm:base}, with~$25\eps$ and $2\eta$ in place of $\eps$ and~$\eta$, and $O(\dd^3)$ additional classical time complexity.

\label{lem:sqrt}
    For any $U, V \in \PPBB(\tfrac{1}{3\pi})$ and $p \geq 1$,
    \begin{equation} \label{eq:root-lipschitz-proj}
        \dist(U^{1/p}, V^{1/p}\uone) \leq \frac{\pi^2}{2p} \dist(U, V\uone).
    \end{equation}

\label{lem:Szarek}
For any~$U \in \UU(\dd)$, there is~$X \in \uu(\dd)$ with~$\opnorm X \le \pi$
such that~$U = e^X$. If~$e^X = e^Y$ with~$\opnorm X , \opnorm Y < \pi$, then~$X=Y$.
Further, the following hold:
\begin{enumerate}[label=\emph{(\alph*)},ref=\ref{lem:Szarek}(\alph*)]
\item For any~$X \in \uu(\dd)$ such that~$\opnorm X \le \pi$,
$\dist(\id, e^X) = \opnorm{X}$. \label{eq:dist-by-eigenvalues}

\item For any~$U,V \in \UU(\dd)$,
    $\opnorm{U-V} \le \dist(U,V) \le \frac \pi 2 \opnorm{U - V}$. \label{eq:metricEq}

\item
For any $X,Y \in \uu(\dd)$,
    $\opnorm{e^X - e^Y} \le \opnorm{X-Y}$. \label{eq:exp-bound}

\item 
For any $X, Y \in \uu(\dd)$ such that $\opnorm X , \opnorm Y \le \frac{1}{\pi}$,
    $\opnorm{X-Y} \le \pi \opnorm{e^X - e^Y}$. \label{eq:inv-exp-bound}
\end{enumerate}

\label{thm:error-boosting}
   Suppose we have an oracle capable of applying an unknown unitary channel $Z \in \UU(\dd)$.
   Further suppose we have an algorithm $\alg$ that, given such an oracle, can output a unitary $\bU$ such that $\dist(Z, \bU\uone) \leq \eps_0 \leq \frac{1}{600}$ with probability $> 0.51$.
   Then, given error parameters $\eps, \eta \in (0,1)$, \cref{algo:theboot} outputs a unitary $\bU$ such that
   \begin{enumerate}[label=(\alph*),ref=\thetheorem (\alph*)]
       \item $\dist(Z, \bU\uone) \leq \eps$ with probability $\geq 1-\eta$;\label{thm:error-boosting-highprob}
       \item and $\E[\dist(Z, \bU\uone)^2] \leq (1+32\eta)\eps^2$.\label{thm:error-boosting-expectation}
   \end{enumerate}
   \cref{algo:theboot} has the further property that, if $\alg$ uses $Q$ queries to $Z$, then \cref{algo:theboot} requires only $O(\frac{Q}{\eps}\log\frac{1}{\eta})$ queries to $Z$.

\label{ChannelLearningConfidenceBound}
Let $U,\ldots, U_N \in \UU(\dd)$ by any unitary channels.
For any unitary estimation algorithm $\alg$ 
that queries an input unitary channel $Q$ times 
and outputs an index~$\hat x$ given $U_x$ with probability $\Pr[\hat x | x]$ where $x,\hat x \in [N]$,
it holds that
\begin{align}
    \frac 1 N \sum_{x=1}^N \Pr[\hat x = x | x] \le \frac 1 N \binom{ Q + \dd^2 - 1 }{Q} .
\end{align}

\label{BinomBound}
    If $\frac 1 N \binom{Q + \dd^2 -1}{Q} \ge \exp(- c Q)$ 
    where $Q \ge 1$, $\dd \ge 100/c' \ge 1$ and $N \ge \exp( c' \dd^2 )$ 
    for some constants $c, c' > 0$,
    then~$Q \ge c'' \dd^2$ for some constant $c''$ that depends only on $c,c'$.

For a reflection $R \in \UU(\dd)$ (i.e., $R^2 = \id$) and $\alpha \in [-1,1]$, we define
\begin{align}
    R^\alpha \coloneqq \frac12(\id + R) + e^{-\ii\pi\alpha}\frac12(\id - R)
    = e^{-\ii\pi\alpha/2}\left(\id \cos \frac{\pi\alpha}{2} + \ii R \sin \frac{\pi\alpha}{2} \right). \label{eq:PiToAlpha}
\end{align}

\label{lem:bad-bccks}
   Let $\circuit \in \UU(D)$ be implemented by a quantum circuit that uses $Q$ queries to $Z$ or $Z^\dagger$, with $Z = R^\alpha$ for $R \in \UU(\dd)$ a reflection and $\alpha \in (0,1]$.

   Then there is a circuit $\circuit_R \in \UU(2^Q D)$ with $Q$ ancilla qubits, 
   which uses $50 + 100\alpha Q$ queries to the controlled unitary $\controlled R$ and such that, 
   for all $\ket{\psi} \in \mathbb{C}^D$,
   \begin{gather}
       \circuit_R\ket{0}^{\otimes Q}\ket{\psi} = \nu\ket{0}^{\otimes Q}\ket{\widetilde{\mathrm{out}}} + \ket{\Phi^\perp}, \\
   \intertext{where $\ket{\widetilde{\mathrm{out}}}$ is normalized, $\nu \in \mathbb C$ is a scalar, $(\bra{0}^{\otimes Q} \otimes I) \ket{\Phi^\perp} = 0$  and }
       \abs{\nu} \geq 0.99\exp(-\alpha\pi \tfrac{Q}{2}) \qquad \text{ and }\qquad \twonorm{\ket{\widetilde{\mathrm{out}}} - \circuit\ket{\psi}} < \exp(-99\alpha \pi Q - 20).
   \end{gather}

\label{thm:esteigs}
   There is an eigenvalue estimation algorithm that, given $\eps > 0$ and access to an unknown unitary $Z \in \UU(\dd)$, applies $Z$ at most $O(\dd/\eps)\cdot \log^2 \dd$ times and outputs the classical description of a set~$\wh{\Theta} \subset [0,2\pi)$ such that $\dH{\Theta}{\wh{\Theta}} \leq \eps$ except with probability at most~$\dd^{-100}$, where $\Theta$ is the set of $Z$'s eigenphases.  (That is, $\Theta = \{ \theta \in [0,2\pi) : e^{\ii \theta} \text{ is an eigenvalue of } Z\}$.)
   Moreover, the quantum space requirement for the algorithm is only $2$~qudits plus $1$-qubit, and the gate complexity beyond the uses of~$Z$ is only $\poly\log(\dd/\eps)$.

\label{prop:est2}
   There is an algorithm that, given $\eps > 0$, access to an unknown $Z \in \UU(\dd)$, and an eigenvector $\ket{a}$, has the following behavior:  
   The algorithm uses one additional qudit and one additional qubit, applies $Z$ at most $O(\dd/\eps) \cdot \log^2 \dd$ times, and outputs the classical description of a set~$\wh{\Theta} \subset [0,2\pi)$ such that $\dH{\Theta}{\wh{\Theta}} \leq \eps$ except with probability at most~$\dd^{-100}$, where $\Theta$ is the set of $Z$'s eigenphases.

{theorem}{TheoremAlgorithm}
\label{thm:algorithm}
The \MainAlg algorithm outputs an exact minimum degree ordering in $O(nm)$~time.

{corollary}{CorollaryHardness}
\label{cor:hardness}
Assuming the strong exponential time hypothesis,
there does not exist an~$O(nm^{1-\varepsilon})$ time algorithm for computing
a minimum degree elimination ordering,
for any $\varepsilon > 0$.

{lemma}{LemmaCorrectness}
  \label{lem:correctness}
  \alg{FastMinimumDegree} produces a correct minimum degree ordering $\var{elimination\_ordering}$.
  Furthermore, suppose  $(G_0^+,G_1^+,\dots,G_n^+)$ is the sequence of fill graphs
  induced by $\var{elimination\_ordering}$.
  Then, at the end of each iteration $i \in [n]$ of the \alg{FastMinimumDegree} algorithm:
  \begin{enumerate}
  \item The state of $\var{fill\_graph}$ corresponds to the fill graph $G_{i}^+$.
  \item The list of hyperedges $U_1,U_2,\dots,U_k$
    satisfies $K_{U_1}\cup K_{U_2}\cup \cdots \cup K_{U_k}=G_i^+$
      (i.e., the hypergraph representation is maintained).
  \end{enumerate}

{lemma}{LemmaMinDegreeQuery}
  \label{lem:min-degree-query}
  The $\var{fill\_graph}$ adjacency structure
  can be augmented to support
  the selection of the minimum degree vertex,
  increasing the total running time by at most $O(m^+)$.

{lemma}{LemmaCliqueSet}
  \label{lem:clique-set}
  Let $k$ be the total number of edge insertion attempts,
  and let $c$ be the cost of querying, inserting, or deleting an edge.
  Then the algorithm can be implemented to run in $O(c(m^++k))$ time.

\label{lem:sum-min-degree-bound}
The number of edge insertion attempts is at most $\sum_{\set{u,v}\in E^+}\min(\deg(u),\deg(v))$,
where the $\deg(v)$ is the degree of $v$ in the original graph.

\label{cor:constant-degree}
There are $O(\Delta m^+)$ edge insertion attempts,
where $\Delta$ is the maximum degree of the input graph.

{fact}{FactVertexFunction}
  \label{fact:vertex-function}
  Let $G=(V,E)$ be a simple graph and $m=\abs{E}$.
  For any vertex function $f : V\to \R_{\ge 0}$, we have
  \[
    \sum_{\set{u,v}\in E}\min\parens*{f(u),f(v)}
    \le \sqrt{2m}\sum_{v\in V} f(v).
  \]

{corollary}{CorCleanInsertionAttempts}
\label{cor:clean-insertion-attempts}
  The number of edge insertion attempts is $O(m\sqrt{m^+})$.
  In particular, it is at most $O(nm)$.

A $U$-filler is \emph{$d$-bounded}
if after eliminating any subset of extra vertices $X \subseteq W$,
all remaining extra vertices have degree at most $d$ in $G_{X}^+$.

\label{clm:amp:FE}
    There exists a set $F \subset E$ of edges violated by $\psi$ such that
    \begin{align}
    \label{eq:amp:FE}
        \min\left\{ \delta, \frac{1}{\rep}-\frac{1}{|E|} \right\} \leq \frac{|F|}{|E|} \leq \frac{1}{\rep}.
    \end{align}

\label{lem:amp:pow:N1}
    It holds that
    \begin{align}
        \E[N] \geq \rep \frac{|F|}{|E|} \cdot \approxone^2 \cdot (\sqrt{2}-1)^2,
    \end{align}
    where $\approxone \coloneq 1-\rme^{-100}$.

\label{clm:amp:pow:consistent}
    Conditioned on the event that ``$\vv{e} \text{ appears } k \text{ times}$,''
    the following hold\textup{:}
    \begin{align}
        \label{eq:amp:consistent:v}
        \Pr_{x,y}\Bigl[\psi'(x)[v] \text{ and } \psi'(y)[v] \text{ are consistent} \Bigr] & \leq 2p_v, \\
        \label{eq:amp:consistent:w}
        \Pr_{x,y}\Bigl[\psi'(x)[w] \text{ and } \psi'(y)[w] \text{ are consistent} \Bigr] & \leq 2p_w.
    \end{align}

\label{lem:amp:pow:N2}
    It holds that
    \begin{align}
        \E[N^2] \leq \rep \frac{|F|}{|E|} \cdot \left(3 + 2\frac{d}{d-\lambda}\right).
    \end{align}

\label{lem:amp:pow:expander-walk}
    For a $(d,\lambda)$-expander graph $G = (V,E)$ and 
    a set $F \subseteq E$ of edges without self-loops,
    let $\vec{W} = ( \vv{e_1}, \vv{e_2}, \ldots )$ denote
    an ASRW starting from a vertex chosen from $V$ uniformly at random.
    Then, for any $j > i \geq 1$, it holds that
    \begin{align}
        \Pr \Bigl[e_j \in F \Bigm| e_i \in F \Bigr] \leq
        \left(1-\frac{1}{\rep}\right)^{j-i} \left(\frac{|F|}{|E|} + \left(\frac{\lambda}{d}\right)^{j-i-1}\right).
    \end{align}

\label{lem:amp:pow:truncated-N1}
    It holds that
    \begin{align}
        \E[N'] \geq 0.1715 \cdot \rep \frac{|F|}{|E|}.
    \end{align}

\label{lem:expander-mixing}
    Let $G$ be a $(d,\lambda)$-expander graph over $n$ vertices.
    Then, for any two sets $S$ and $T$ of vertices,
    it holds that
    \begin{align}
        \left|e_G(S,T) -  \frac{d|S| \cdot |T|}{n} \right| \leq \lambda \sqrt{|S|\cdot|T|}.
    \end{align}

For a dynamic graph $ \cG = (G_i)_{0 \leq i \leq k} $ we say for an edge $ (u, v) $ that
\begin{itemize}
\item $ (u, v) $ is \emph{deleted} at time $ t $ if $ (u, v) $ is contained in $ G_{t-1} $ but not in $ G_t $;
\item $ (u, v) $ is \emph{inserted} at time $ t $ if $ (u, v) $ contained in $ G_t $ but not in $ G_{t-1} $.
\end{itemize}
For a dynamic weighted graph $ \cH = (H_i, w_i)_{0 \leq i \leq k} $, we additionally say for an edge $ (u, v) $ that
\begin{itemize}
\item the weight of $ (u, v) $ is \emph{increased} at time $ t $ if $ w_t (u, v) > w_{t-1} (u, v) $ (and $ (u, v) $ is contained in both $ G_{t-1} $ and $ G_t $);
\item the weight of $ (u, v) $ is \emph{decreased} at time $ t $ if $ w_t (u, v) < w_{t-1} (u, v) $ (and $ (u, v) $ is contained in both $ G_{t-1} $ and $ G_t $).
\end{itemize}
Every deletion, insertion, weight increase, or weight decrease is called an \emph{update}.
The \emph{total number of updates up to time $ t $} of a dynamic (weighted) graph $ \cG $ is denoted by $ \phi_t (\cG) $.

\label{def:approximate_APSP}
An \emph{$ (\alpha, \beta) $-approximate decremental all-pairs shortest paths (APSP) data structure} for a decremental graph $ \cG = (G_i)_{0 \leq i \leq k} $ maintains, for all nodes $ x $ and $ y $ and all $ 0 \leq i \leq k $, an estimate $ \delta_i (x, y) $ of the distance between $ x $ and $ y $ in $ G_i $.
After the $i$-th edge deletion (where $ 0 \leq i \leq k $), it provides the following operations:
\begin{itemize}
\item \Delete{$u$, $v$}: Delete the edge $ (u, v) $ from $ G_i $.
\item \Distance{$x$, $y$}: Return an estimate $ \delta_i (x, y) $ of the distance between $ x $ and $ \treeroot $ in $ G_i $ such that $ \dist_{G_i} (x, y) \leq \delta_i (x, y) \leq \alpha \dist_{G_i} (x, y) + \beta $.
\end{itemize}
The \emph{total update time} is the total time needed for performing all $ k $ delete operations and the initialization, and the \emph{query time} is the worst-case time needed to answer a single distance query.
The data structure is \emph{exact} if $ \alpha = 1 $ and $ \beta = 0 $.

\label{def:approximate_SSSP}
An \emph{$ (\alpha, \beta) $-approximate decremental single-source shortest paths (SSSP) data structure} with \emph{source (or: root) node $ \treeroot $} and \emph{distance range parameter $ \Q $} for a decremental graph $ \cG = (G_i)_{0 \leq i \leq k} $ maintains, for every node $ x $ and all $ 0 \leq i \leq k $, an estimate $ \delta_i (x, \treeroot) \in \{ 0, 1, \ldots, \lfloor \alpha \Q + \beta \rfloor, \infty \} $ of the distance between $ x $ and $ \treeroot $ in $ G_i $.
After the $i$-th edge deletion (where $ 0 \leq i \leq k $), it provides the following operations:
\begin{itemize}
\item \Delete{$u$, $v$}: Delete the edge $ (u, v) $ from $ G_i $ and return the set of all nodes $ x $ such that $ \delta_i (x, \treeroot) \leq \alpha \Q + \beta $ and $ \delta_{i+1} (x, \treeroot) > \alpha \Q + \beta $.
\item \Distance{$x$}: Return an estimate $ \delta_i (x, \treeroot) $ of the distance between $ x $ and $ \treeroot $ in $ G_i $ such that $ \delta_i (x, \treeroot) \geq \dist_{G_i} (x, \treeroot) $, and if $ \dist_{G_i} (x, \treeroot) \leq \Q $, then also $ \delta_i (x, \treeroot) \leq \alpha \dist_{G_i} (x, \treeroot) + \beta $.
\end{itemize}
The \emph{total update time} is the total time needed for performing all $ k $ delete operations and the initialization, and the \emph{query time} is the worst-case time needed to answer a single distance query.
The data structure is \emph{exact} if $ \alpha = 1 $ and $ \beta = 0 $.

\label{thm:king}
The ES-tree is an exact decremental SSSP data structure for shortest paths up to a given length $ \Q $.
It has constant query time, and in a decremental graph $ \cG = (G_i, w_i)_{0 \leq i \leq k} $ its total update time can be bounded by
\begin{equation*}
O \left(\phi_k(\cG) + t_{\mathrm{SP}} + \sum_{1 \leq i \leq k} \sum_{v \in V} \deg_{G_i} (v) \left(\min(\Q, \ell_{i} (v)) - \min(\Q, \ell_{i-1} (v))\right) \right) \, ,
\end{equation*}
where $ t_{\mathrm{SP}} $ is the time needed for computing an SSSP tree up to depth $ \Q $ and, for $ 0 \leq i \leq k $, $ \ell_i (v) $ is the level of $ v $ after the ES-tree has processed the $i$-th deletion or weight increase.

\label{cor:ES_running_time_distance_increase}
There is an exact decremental SSSP data structure for paths up to a given length $ \Q $ that has constant query time, and in a decremental graph $ \cG = (G_i, w_i)_{0 \leq i \leq k} $ with source node $ \treeroot $ its total update time can be bounded by
\begin{equation*}\label{eq:ES running time simplified}
O \left(\phi_k(\cG) + t_{\mathrm{SP}} + \sum_{v \in V} \deg_{G_0} (v) \cdot \left( \min(\Q, \dist_{G_k}(v, \treeroot)) - \min(\Q, \dist_{G_0}(v, \treeroot)) \right) \right)
\end{equation*}
and $ O (m \Q) $,
where $ t_{\mathrm{SP}} $ is the time needed for computing an SSSP tree up to depth $ \Q $, and $ \dist_{G_0}(v, \treeroot) $ is the initial distance of $ \treeroot $ to $ v $ and $ \dist_{G_k}(v, \treeroot) $ is the distance of $ v $ to $ \treeroot $ after all $ k $ edge deletions.

\label{lem:centers_data_structure_to_APSP}
Assume that for all parameters $ \q $ and $ \Q $ such that $ \q \leq \Q $ there is a center cover data structure that has constant query time and a total update time of $ T (\q, \Q) $.
Then, for every $ \epsilon \leq 1 $, there is a $ (1 + \epsilon, 0) $-approximate decremental APSP data structure with $ O(\log{\log n}) $ query time and a total update time of $ \sum_p T (\qp, \Qp) $ where $ \qp = \epsilon 2^p $ and $ \Qp = 2^{p+2} $ (for $ 0 \leq p \leq \lfloor \log{n} \rfloor $).

\label{def:locally decremental emulator}
Consider parameters $ \alpha \geq 1 $, $\beta \geq 0 $ and $ \tau \geq 1$, a dynamic graph $ \cG = (G_i)_{0 \leq i \leq k} $, and a dynamic weighted graph $ \cH = (H_i, w_i)_{0 \leq i \leq k} $. 

For every $ i \leq k $, we say that a path $ \pi $ in $ G_i $ is {\em contained} in $ (H_i, w_i) $ if every edge of $ \pi $ is contained in $ H_i $ and has weight $ 1 $.

We say that $\cH$ is an {\em ($\alpha$, $\beta$, $\tau$)-locally persevering emulator of $ \cG $} if for all nodes $ x $ and $ y $ we have 

\begin{enumerate}[label=(\arabic{*})]
\item \label{item:emulator one} $ \dist_{G_i} (x, y) \leq \dist_{H_i, w_i} (x, y) $ for all $ 0 \leq i \leq k $, and 
\item \label{item:emulator two} there are $ t_1 $ and $ t_2 $ with $ 0 \leq t_1 < t_2 \leq k+1 $ such that the following hold:
\begin{enumerate}
\item There is a path $ \pi $ from $ x $ to $ y $ in $ \cH $ that is persevering (at least) up to time $ t_1 $ and satisfies $ w_t (\pi) \leq \alpha \dist_{G_t} (x, y) + \beta $.\label{item:emulator a}
\item For every $ t_1 < i \leq t_2 $, a shortest path from $ x $ to $ y $ in $ G_i $ is contained in $ (H_i, w_i) $. \label{item:emulator b}
\item For every $ i \geq t_2 $, $ \dist_{G_i} (x, y) > \tau $.\label{item:emulator c}
\end{enumerate}
\end{enumerate}

\label{thm:emulator}
For every $ 0 < \epsilon \leq 1 $ and every decremental graph $ \cG = (G_i)_{0 \leq i \leq k} $, there is data structure that maintains a dynamic weighted graph $ \cH = (H_i, w_i)_{0 \leq i \leq k} $ in $ O (m n^{1/2} \log{n} / \epsilon) $ total time such that $ \cH $ is a $ (1, 2, \lceil 2 / \epsilon \rceil) $-locally persevering emulator with high probability. 

Moreover, the number of edges ever contained in the emulator is $ | E_k (\cH) | = O (n^{3/2} \log{n}) $, and the total number of updates in $ \cH $ is $ \phi_k (\cH) = O (n^{3/2} \log{n} / \epsilon) $.

\label{thm:monotone ES tree}
For every distance range parameter $ \Q $, every source node $ \treeroot $, and every decremental graph $ \cG = (G_i)_{0 \leq i \leq k} $ with an $ (\alpha, \beta, \tau) $-locally persevering emulator $ \cH = (H_i, w_i)_{0 \leq i \leq k} $, the monotone ES-tree on $ \cH $ is an $ (\alpha + \beta / \tau, \beta) $-approximate decremental SSSP data structure for $ \cG $.
It has constant query time and a total update time of 
\begin{equation*}
O(\phi_k(\cH) + |E_k (\cH) | \cdot ((\alpha + \beta/\tau) \Q + \beta) ) \, ,
\end{equation*}
where $ \phi_k(\cH) $ is the total number of updates in $ \cH $ up to time $ k $ and $ E_k (\cH) $ is the set of all edges ever contained in $ \cH $ up to time $ k $.

\label{lem:monotone_ES_correctness_stretched_nodes}
Let $ 0 < i \leq k $ and assume that $ \ell_{i-1} (x') \leq (\alpha + \beta / \tau) \cdot \dist_{G_{i-1}} (x', \treeroot) + \beta $ for every node $ x' $ with $ \ell_{i-1} (x') \neq \infty $.
Then $ \ell_i (x) \leq (\alpha + \beta / \tau) \cdot \dist_{G_i} (x, \treeroot) + \beta $ for every stretched node $ x $.

\label{lem:level_weight_inequality}
Consider any $ 0 \leq i \leq k $ and any $ (x, y) \in E (H_{i}) $. We have
\begin{equation*}
\ell_i (x) \leq \ell_i (y) + w_i (x, y)
\end{equation*}
if $ \ell_i (y) + w_i (x, y) \leq (\alpha + \beta / \tau) \Q + \beta $ and either (a) $ i = 0 $ or (b) $ i \geq 1 $, $ \ell_{i-1} (x) \neq \infty $ and $ (x, y) $ is not stretched.

\label{lem:approximate_SSSP_to_approximate_center_cover}
Let $ \q $ and $ \Q $ be parameters such that $ \q \leq \Q $.
If there are $ (\alpha, \beta) $-approximate decremental SSSP data structures with distance range parameters $ \q $ and $ \Q $ for some $ \alpha \geq 1 $ and $ \beta \geq 0 $ that have constant query times and total update times of $ T (\q) $ and $ T (\Q) $, respectively (where $ T (\Q) $ is $ \Omega (n) $), then there is an $ (\alpha, \beta) $-approximate center cover data structure that is correct with high probability and has constant query time and an expected total update time of $ O( (T (\Q) n \log{n}) / \q) $.

\label{lem:approximate_APSP_with_additive_error}
Assume that for some $ \alpha \geq 1 $ and $ \beta \geq 0 $, every $ 0 < \epsilon \leq 1 $, and all $ 0 \leq \Q $ there is an $ (\alpha+\epsilon, \beta) $-approximate decremental SSSP data structure with distance range parameter $ \Q $ that has constant query time and a total update time of $ T' (\Q, \epsilon) $.
Then there is an $ (\alpha+\epsilon, \beta) $-approximate decremental APSP data structure with a query time of $ O (\log{\log{n}}) $ and a total update time of
\begin{equation*}
\hat{T} = \sum_{p=0}^{\lfloor \log{n} \rfloor} (T' (\Qp, \hat{\epsilon}) n \log{n}) / \qp + n T' (\Qhat, \hat{\epsilon})
\end{equation*}
where $ \hat{\epsilon} = \epsilon / (18 \alpha^2) $, $ \Qhat = (4 \alpha + 8 \beta) / \hat{\epsilon} $, $ \qp = \hat{\epsilon} 2^p $, and $ \Qp = \alpha \hat{\epsilon} 2^p + \beta + 2^{p+1} $ (for $ 0 \leq p \leq \lfloor \log{n} \rfloor $).

The query time can be reduced to $ O (1) $ if there is an $ (\alpha', \beta') $-approximate decremental APSP data structure for some constants $ \alpha' $ and~$ \beta' $ with constant query time and a total update time of $ \hat{T} $.

\label{lem:existence_dynamic_centers_ds}
Let $ \q $ and $ \Q $ be parameters such that $ \q \leq \Q $.
Under the assumption that between two consecutive delete operations there can be at most one open or delete operation for each center, there is a moving centers data structure with a total deterministic update time of $ O ((\opens  \Q + \moves) m) $, where $ \opens $ is the number of open-operations and $ \moves $ is the total moving distance.\footnote{Note that the total moving distance might be $ \infty $ if, after some deletion $ i $, a center $ j $ is moved from $ \cen_i^j $ to $ \cen_{i+1}^j $ such that there is no path between $ \cen_i^j $ and $ \cen_{i+1}^j $ in $ G_i $. In this case our analysis cannot bound the total update time of the moving centers data structure.}
The data structure can answer each query in constant time.

\label{lem:center_too_small_consequence}
Let $ (u, v) $ be the $ (i+1) $-th deleted edge.
If $ | \comp_i (\cen_i^j) | \geq \radius_i^j $ and $ | \comp_{i+1} (\cen_i^j) | < \radius_i^j $, then $ u \in \ball_i^j $ and $ v \in \ball_i^j $.

\label{lem:at_most_one_center_moved}
Let $ (u, v) $ be the $ (i+1) $-th deleted edge.
If $ | \ball_i^j | \geq \radius_i^j $ for every center $ j $, then there is at most one center $ j $ such that $ | \comp_{i+1} (\cen_i^j) | < \radius_i^j $ and, in $ G_{i+1} $, either $ u $ is connected to $ \cen_i^j $ (and $ v $ is disconnected from $ \cen_i^j $) or $ v $ is connected to $ \cen_i^j $ (and $ u $ is disconnected from $ \cen_i^j $).

\label{lem:confinement}
For every move of center $ j $ from $ \cen_i^j $ to $ \cen_{i+1}^j $ after the $ (i+1) $-th edge deletion, let $ \pi_i^j $ be the set of nodes on a shortest path from $ \cen_i^j $ to $ \cen_{i+1}^j $ in $ G_i $.
Then, for every center $ j $ and every $ 0 \leq i < k $, $ \pi_i^j \setminus \{ \cen_{i+1}^j \} \subseteq \T_{i+1}^j \setminus \T_i^j $.

\label{lem:charepsilonbne}
	Fix an $\varepsilon \geq 0$. A strategy profile $\vec{\beta}$ is an $\varepsilon$-BNE of the FPA, if and only if, for every bidder $i$ and every non-degenerate bid $b$,
	\begin{equation}\label{eq:charepsilonbne1}
	u_i(b,\vec{\beta}_{-i};\alpha_i(b^-)) \geq
	u_i(b',\vec{\beta}_{-i};\alpha_i(b^-)) -\varepsilon
	\qquad\text{for all}\;\; b'<b
	\end{equation}
	and
	\begin{equation}\label{eq:charepsilonbne2}
	u_i(b,\vec{\beta}_{-i};\alpha_i(b)) \geq
	u_i(b',\vec{\beta}_{-i};\alpha_i(b)) -\varepsilon
	\qquad\text{for all}\;\; b'>b.
	\end{equation}

\label{lem:gcircuit-special}
Let $\mathcal{G} = \{G_{\times 2},G_{1-},G_\phi\}$.
There exists a constant $\gceps > 0$ such that the problem $\gceps$-\gcircuit with gate-types $\mathcal{G}$ is \ppad-complete. Furthermore, \exactgcircuit with gate-types $\mathcal{G}$ is \fixp-complete.

\label{clm:base-gadget}
Let $\gamma_\ell, \gamma_r, \ell, r \in [0,1]$ with $\gamma_\ell, \gamma_r \geq 1/20$, $\gamma_\ell + \gamma_r < 1$ and $\ell < r$.
Consider a base gadget with input bidder $j$ and output bidder $i$, and parameters $(\gamma_\ell, \gamma_r, \ell, r)$. It holds that:
\begin{itemize}
	\item If the input bidder $j$ is almost-valid, then the output bidder $i$ is also almost-valid.
	\item If $\gamma_\ell,\gamma_r \geq 1/3$ and $j$ is almost-valid, then $i$ is valid and
	$$\val[i] = (3\gamma_\ell-1) + 3(1-\gamma_\ell-\gamma_r) \frac{T_{[2+\ell,2+r]}(\alpha_j(1)) - (2+\ell)}{r-\ell} \pm 6\varepsilon.$$
\end{itemize}

\label{clm:projection-gadget}
The projection gadget with input bidder $j$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidder $j$ is valid, then $\val[i] = \val[j] \pm 18\varepsilon$.
\end{itemize}

\label{clm:mult-2-gadget}
The $G_{\times 2}$ gadget with input bidder $j$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidder $j$ is valid, then $\val[i] = \trunc(2\cdot \val[j]) \pm 24\varepsilon$.
\end{itemize}

\label{clm:complement-gadget}
The $G_{1-}$ gadget with input bidder $j$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidder $j$ is valid, then $\val[i] = 1 - \val[j] \pm 60\varepsilon$.
\end{itemize}

\label{clm:phi-gadget}
The $G_\phi$ gadget with input bidders $j_1,j_2$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidders $j_1$ and $j_2$ are valid, then
	$$\val[i] = \phi(\val[j_1],\val[j_2]) \pm 86\varepsilon = \frac{1}{4}(\val[j_1]+1)(\val[j_2]+1) \pm 86\varepsilon.$$
\end{itemize}

\label{prop:overbidnonmonotone}
Let $\vec{\beta}$ be an exact equilibrium of a FPA. For a bid $b_i$ by player $i$, let $H_i(b_i,\vec{\beta}_{-i})$ denote the (perceived) probability that player $i$ gets the item, given this bid and the bidding strategies by the other players.
Then, strategies will always be no over-bidding and monotone non-decreasing except only possibly when the probability of winning is zero. Formally,  

\begin{enumerate}
    \item let $v_i$ be a valuation by player $i$ and $b_i=\beta_i(v_i)$. If $b_i>v_i$, then $H_i(b_i,\vec{\beta}_{-i})=0$;
    \item let $v_i,v'_i$ be valuations by player $i$ and $b_i=\beta_i(v_i)$, $b'_i=\beta_i(v'_i)$. If $v_i<v'_i$ and $b_i>b'_i$, then $H_i(b_i,\vec{\beta}_{-i})=H_i(b'_i,\vec{\beta}_{-i})=0$.
\end{enumerate}

\label{th:classical-est}
Let $P\in\Real[x]$ be a constant-degree polynomial.
For any constant $\epsilon>0$, there is a $O(\poly(\log N,s))$-time classical algorithm that, given query-access to an $s$-sparse matrix $A\in\Comp^{N\times N}$ with $\norm{A}\le 1$, query-access to a vector $u\in\Comp^N$, and sampling-access to a vector $v\in \Comp^N$, outputs with high probability an estimate of the quantity $v^\dagger P(\sqrt{A^\dagger A})u$ with additive precision~$\epsilon$.

\label{th:SVT}
For any interval $[t_1,t_2]\subseteq [0,1]$, any constant $\theta>0$ and any $s$-sparse matrix $A\in\Comp^{N\times N}$ with $\norm{A}\le 1$ given by query-access, consider the problem of deciding whether
\begin{itemize}
\item[(i)]
$A$ has a singular value in interval $[t_1,t_2]$, or
\item[(ii)]
$A$ has no singular value in interval $(t_1-\theta,t_2+\theta)$.
\end{itemize}
In addition, we are given as input sampling-access to a vector $u\in\Comp^N$, which we are promised in case~$(i)$ satisfies $\norm{\Pi_A^{[t_1,t_2]}u}=\Omega(1)$. Then, there is a $O(\poly(\log N,s))$-time classical algorithm that decides with high probability which of $(i)$ and $(ii)$ holds.

\label{th:qPCP}
Consider problem $\LH(k,a,b)$ with the following additional promise: the ground state of $H$ has constant overlap with a complex vector that has a succinct representation allowing sampling-access.
For any $k=O(\log n)$, any $a,b\in[-1,1]$ such that $b-a=\Omega(1)$, this variant of $\LH(k,a,b)$ is in the complexity class $\MA$.

\label{def:query-access}


We say that we have query-access to a vector $u\in \Comp^{N}$ if there exists an $O(\poly(\log N))$-time classical algorithm $\Qq_u$ that

on input $i\in\{1,\ldots,N\}$, outputs the entry $u_i$.

\label{def:sparsequery}
We say that we have query-access to an $s$-sparse matrix $A\in \Comp^{M\times N}$ if we have access to two $O(\poly(\log MN))$-time classical algorithms $\Qq_A^{\mathrm{row}}$ and $\Qq_A^{\mathrm{col}}$ such that
\begin{itemize}
\item
on input $(i,\ell)\in\{1,\ldots,M\}\times\{1,\ldots,s\}$, the algorithm $\Qq_A^{\mathrm{row}}$ outputs the $\ell$-th non-zero entry of the $i$-th row of $A$ if this row has at least $\ell$ non-zero entries, and outputs an error message otherwise;
\item
on input $(j,\ell)\in\{1,\ldots,N\}\times\{1,\ldots,s\}$, the algorithm $\Qq_A^{\mathrm{col}}$ outputs the $\ell$-th non-zero entry of the $j$-th column of $A$ if this column has at least $\ell$ non-zero entries, and outputs an error message otherwise.
\end{itemize}

\label{def:sample}
For a parameter $\zeta\in[0,1)$, we say that we have $\zeta$-sampling-access to a vector $u\in \Comp^{N}$ if the following three conditions are satisfied:
\begin{itemize}
\item[(i)]
we have access to an $O(\poly(\log N))$-time classical algorithm $\Qq_u$ that on input $i\in\{1,\ldots,N\}$, outputs the entry $u_i$;
\item[(ii)]
we have access to an $O(\poly(\log N))$-time classical algorithm $\Sq_u$ that samples from a probability distribution $p\colon\{1,\ldots,N\}\to [0,1]$ such that
\[
p(j)\in\left[(1-\zeta)\frac{|u_j|^2}{\norm{u}^2},(1+\zeta)\frac{|u_j|^2}{\norm{u}^2}\right]
\]
for all $j\in\{1,\ldots,N\}$;




\item[(iii)]
we are given a real number $m$ satisfying $|m-\norm{u}|\le \zeta \norm{u}$.
\end{itemize}

We simply say that we have sampling-access to $u$ (without specifying $\zeta$) if we have $0$-sampling-access.

