  \end{displaymath}

\label{lem:independent-rounding}
  Let $f$ be a \lrvar4 over $\R^n$ and let $i\in [n]$ such that $f_i^2\sle f_i$.

  Then, there exists an \lrvar4 $(f,\bar f_i)$ over $\R^{n+1}$ such that
  $\pE_{f,\bar f_i} (\bar f_i^2-\bar f_i)^2 =0$ and for every polynomial
  $P$ which is linear in $\bar f_i$ and has degree at most $4$,
  \begin{displaymath}
    \pE_{f,\bar f_i} P(f,\bar f_i) = \pE_{f} P(f,f_i)\mper
  \end{displaymath}

\label{cor:independent-rounding}
  Let $f$ be a \lrvar4 over $\R^n$ and let $I\sse [n]$ such that $f_i^2\sle
  f_i$ for all $i\in I$.

  Then, there exists an \lrvar4 $(f,\bar f_I)$ over $\R^{n+\card I}$ such
  that $\pE_{f,\bar f_I} (\bar f_i^2-\bar f_i)^2 =0$ for all $i\in I$ and
  for every polynomial $P$ which is multilinear in the variables $\set{\bar
    f_i}_{i\in I}$ and has degree at most $4$,
  \begin{displaymath}
    \pE_{f,\bar f_I} P(f,\bar f_I) = \pE_{f} P(f,f_I)\mper
  \end{displaymath}

\label{lem:expansion-bound}
Let $f$ be a \lrvar4 over $L_2(\Omega^R)$.

Suppose $f^2\sle f$ (in terms of unspecified jointly-distributed
\lrvar4s).

Then for all $\lambda>0$,
\begin{displaymath}
  \pE_f \iprod{f,T_{1-\e} f}
  \le (\pE_f \E f)^{3/4} (\pE_f \E (P_{>\lambda}f)^4)^{1/4}
  + \lambda \pE_f \E f
  \mper
\end{displaymath}
Here, $P_{>\lambda}$ is the projector into the span of the eigenfunctions of
$T_{1-\e}$ with eigenvalue larger than $\lambda$.

\label{thm:ug-dictatorship-test}
Suppose $f^2\sle f$ and $\pE_f (\E f)^2\le \delta^2$.

Let $\tau=\pE_f \sum_{r} (\super \Inf{\le \ell}_r\bar f)^2$ for
$\ell=\Omega(\log(1/\delta))$.

Then,
\begin{displaymath}
  \pE_f \iprod{f,T'_{1-\e} f} \le \delta^{1+\Omega(\e)} +
  k^{O(\log(1/\delta))} \cdot \tau^{1/8}\mper
\end{displaymath}
(Here, we assume that $\e$, $\delta$ and $\tau$ are sufficiently small.)

\label{thm:ug-value-bound}
The optimal value of the level-$d$ SoS relaxation for the unique
game $\cW=\cW_{\e,k}(\cU)$ is bounded from above by
\begin{displaymath}
