A circuit class $\cC$ is learnable over the uniform disribution by circuits in $\cD$ up to error $\eps$ with confidence $\delta$ if there are randomized oracle $\cD$-circuits $L^f$ such that for every boolean function $f:\{0,1\}^n\mapsto\{0,1\}$ computable by a circuit from $\cC$, when given oracle access to $f$, input $1^n$ and the internal randomness $w \in \{0,1\}^*$, $L^f$ outputs the description of a circuit satisfying 
  \begin{equation*}
    \Pr_w \{ L^f(1^n, w) \text{ } (1-\eps) \text{-approximates } f \} \geq \delta.
  \end{equation*}


\noindent $L^f$ uses  non-adaptive membership queries if the set of queries which $L^f$ makes to the oracle does not depend on the answers to previous queries.  If $\delta=1$, we omit mentioning the confidence parameter.

  \label{def:nat_prop}
  Let $\mathfrak{R} = \{ \cR_n \}$ be a combinatorial property, $\cC$ be a circuit class and $\Gamma$ be a complexity class. Then,
  $\mathfrak{R}$ is a $\Gamma$-natural property useful against $\cC[s(n)]$, if there exists an $n_0 \in \N$ such that the following hold: 
\begin{itemize}
\item[$\bullet$] \textbf{Constructivity} : For any function $f_n \in \cF_n$, the predicate $f_n \stackrel{?}{\in} \cR_n$ is computable in $\Gamma$ in the size
  of the truth table of $f_n$.
\item[$\bullet$] \textbf{Largeness} : For every $n \geq n_0$, $\Pr_{f_n \sim \cF_n} \{f_n \in \cR_n \} \geq \frac{1}{2^{O(n)}}$.
\item[$\bullet$] \textbf{Usefulness} : For every $n \geq n_0$, $\cR_n \cap \cC[s(n)] = \emptyset$. 
\end{itemize}

  \label{thm:cikk_learn}
  Let $R$ be a $\Ppoly$-natural property useful against $\Circuit[n^d]$ for some $d \geq 1$. Then, for each $\gamma\in (0,1)$, there are randomized, oracle circuits $\{D_n\}_{n \geq 1} \in \Circuit[2^{O(n^{\gamma})}]$ 
that learn $\Circuit[n^k]$ up to error $\frac{1}{n^k}$ using non-adaptive oracle queries to $f_n$, where $k = \frac{d\gamma}{a}$ and $a$ is a universal constant that does not depend on $d$ and $\gamma$.

\label{def:ag_mcsp}
Let $s,t : \N \rightarrow \N$, where $s(n) \leq t(n)$ and $0 \leq \eps, \sigma < 1/2$. Define $\MCSP[(s,\sigma),(t, \eps)]$ on inputs of length $N = 2^n$, as the following promise problem :
\begin{itemize}
\item YES instances: $y \in \{0,1\}^{N}$ such that there exists a circuit of size $s(n)$ that $(1-\sigma)$-approximates $f_y$. 
\item NO instances: $y \in \{0,1\}^{N}$ such that no circuit of size $t(n)$ $(1-\eps)$-approximates $f_y$.
\end{itemize}

\label{def:prf}
For any circuit class $\cC$, size functions $s(n), t(n) \geq n$, family $\cG_n$ of $n$-bit Boolean functions and distribution $\cD_n$ over $\cG_n$, we say that a
pair $(\cG_n, \cD_n)$ is a $(t(n), \eps(n))$-pseudorandom function family (PRF) in $\cC[s(n)]$, if each function in $\cG_n$ is in $\cC[s(n)]$ and for every randomized circuit $A^O \in \Circuit^O[t(n)]$, where $O$ denotes oracle access to a fixed Boolean function over $n$ inputs, we have
\begin{equation*}
  \bigg \vert \Pr_{g \sim \cD_n, w} \{A^g(w) = 1\} - \Pr_{f \sim \cF_n, w} \{A^f(w) = 1 \} \bigg \vert \leq \eps(n)
\end{equation*}

\label{lem:hoeffding}
Let $X_1, \dots, X_n$ be independent random variables such that $0 \leq X_i \leq 1$ for every $i \in [n]$. Let $X = \sum_{i=1}^n X_i$. Then, for any $\eps > 0$, we
have
\begin{equation*}
  \Pr \{ \vert X - \textbf{E}{X} \vert \geq \eps n \} \leq 2\exp(-2 \eps^2 n)
\end{equation*}

