\label{lm:poly-LDT}
	Let $n,\Delta,p \in \N$ be such that $p \ge 20 \cdot (\Delta+1)^2 \cdot n^2$ and $p$ is a prime. There is a probabilistic non-adaptive oracle machine $\mathsf{LDT}$ such that the following holds. Let $g\colon \F_p^n\to \F_p$. Then for $\delta = 3 n^2 \cdot (\Delta+1) / p$, it holds that
	\begin{enumerate}
		\item if $\degmax(g)\leq \Delta$, then $\mathsf{LDT}^{g}(p,n,\Delta)$ accepts with probability $1$, 
		\item if $g$ is at least $\delta$-far from every polynomial with maximum individual degree at most $\Delta$, then $\mathsf{LDT}^{g}(p,n,\Delta)$ rejects with probability at least $2/3$, and
		\item $\mathsf{LDT}$ runs in $\poly(p)$ time.
	\end{enumerate}

\label{lm:comp-RM}
	Let $p$ be a prime. Let $m,\Delta \in \N$ be such that $m \cdot \Delta < p/2$. There is a probabilistic oracle algorithm $\Comp$ that takes two polynomials $f,g \colon \F_p^m \to \F_p$ as oracles, such that if both $\degmax(f)$ and $\degmax(g)$ are at most $\Delta$, then the following holds with probability at least $9/10$:
	\begin{itemize}
		\item If $f \ne g$, then $\Comp^{f,g}(p,m,\Delta)$ outputs the lexicographically smallest element $w$ in $H^m$ such that $f(w) \ne g(w)$, where $H = \{0,1,\dotsc,\Delta-1\}$.\footnote{Since both $f$ and $g$ have max degree at most $\Delta$, their values are completely determined by their restrictions on $H^m$. Hence, if $f\ne g$, then such $w$ must exist.}
		\item If $f = g$, then $\Comp^{f,g}(p,m,\Delta)$ outputs $\bot$.
		\item $\Comp$ makes at most $\poly(m \cdot \Delta)$ queries to both $f$ and $g$, and runs in $\poly(m \cdot \Delta \cdot \log p)$ time.
	\end{itemize}

\label{lemma:Kor-prop-s2}
	Let $n,T \in \N$ be such that $\log T \le n \le T$. Let $C\colon\{0, 1\}^n \to \{0, 1\}^{2n}$ be a circuit and $f\in\bs{T} \setminus \Range(\GGM_T[C])$. Let $h \coloneqq \EncHisKor(C, f)$ and $z \coloneqq \Kor(C, f)$.

