		\begin{enumerate}
			\item $\In_{T,n}$ makes a single query to its oracle; when given $h$ as the oracle, $\In_{T,n}$ takes an additional input $i \in \zeroUpto{T^6-1}$ and outputs $f_i$. \label{item: history-contain-input-S2}

			\item $\Out_{T,n}$ makes at most $4n$ queries to its oracle; when given $h$ as the oracle, $\Out_{T,n}$ outputs $z = \Kor(C, f)$. \label{item: history-contain-output-S2}
		\end{enumerate}

		\item {\bf ($\S_2\BPP$ verification of the history)} There is a randomized oracle algorithm $V$ with input parameters $T,n$ such that the following hold: \label{item: S2BPP-V}

