\label{thm:qszk-completeness}

 The following hold:
 \begin{enumerate}
 \item $(\alpha,\beta,l)$-\textsc{Product State} is in $\cls{QSZK}$ for all $l$ and all $\alpha < \beta^2/(l+1)$.
 \item $(\varepsilon,2-\varepsilon)$-\textsc{Bipartite Product State} is $\cls{QSZK}$-hard, even when $\varepsilon$ decays exponentially in the input length.
 \end{enumerate}
 Thus, the problem is $\cls{QSZK}$-complete for all $l\geq 2$ and all $0<\alpha<\beta^2/(l+1)$ and $\beta<2$.

\label{lm:reduced-product}
Let $\rho$ be a state of registers $A_1,\dots,A_l$ and suppose there is a product state $\sigma_1\ot\cdots\ot\sigma_l$ with
\begin{equation} \Tnorm{ \rho - \sigma_1\ot\cdots\ot\sigma_l } \leq \alpha. \end{equation}
Then it follows that
\begin{equation} \Tnorm{ \rho - \rho_{A_1}\ot\cdots\ot\rho_{A_l} } \leq (l+1)\alpha \end{equation}
where $\rho_{A_i}$ denotes the reduced state of $\rho$ on register $A_i$ for $i=1,\dots,l$.

