~\label{lem:degree upper bound for annihilating poly}
Let $\F$ be a field and let ${\cal Q} = \{Q_1, Q_2, \ldots, Q_t\}$ be a set of polynomials of degree-$d$ in $N$ variables over the field $\F$ having algebraic rank $k$. Then there exists a $\cal Q$-annihilating polynomial
of degree at most $(k+1)\cdot d^k$.

\label{def:homog components}
 For a polynomial $P$ and a positive integer $i$, we represent by $\h^i[P]$, the homogeneous component of $P$ of degree equal to $i$. 
By extension, we define $\h^{\leq i}[P]$ and $\h^{\geq i}[P]$ as follows. 
\begin{align*}
\h^{\leq i}[P] &\equiv \sum_{j = 0}^i \h^{j}[P]\,.\\
\h^{\geq i}[P] &\equiv \sum_{j = i}^{\deg(P)} \h^{j}[P]\,.
\end{align*}
We define $\h[P]$ as the ordered tuple of homogeneous components of $P$, \ie, 
\[\h[P] \equiv \left(\h^{d}[P], \h^{d-1}[P], \ldots, \h^{0}[P]\right)\, ,\] where $d$ is the degree of $P$.

~\label{lem:DSY main}
For a field $\F$, let $P \in \F[X_1, X_2, \ldots, X_N, Y ]$ be a non-zero polynomial of degree at most $k$ in $Y$. Let $f \in \F[X_1, X_2, \ldots, X_N]$ be a polynomial such that $P(X_1, X_2, \ldots, X_N, f) = 0$ and $\frac{\partial P}{\partial Y} (0, 0, \ldots, 0, f(0, 0, \ldots, 0))\neq 0$. Let 
$$P = \sum_{i = 0}^k C_i(X_1, X_2, \ldots, X_N)\cdot Y^i\,.$$ Then, for every $t \geq 0$, there exists a polynomial $R_t \in \F[Z_1, Z_2, \ldots, Z_{k+1} ]$ of degree at most $t$ such that 
\begin{equation}
\h^{\leq t}[f(X_1, X_2, \ldots, X_N)] = \h^{\leq t}[R_t(C_0, C_1, \ldots, C_k)]\,.
\end{equation}

~\label{lem:using algebraic dependence}
Let $\F$ be any  field of characteristic zero or sufficiently large. Let ${\cal Q} = \{Q_1, Q_2, \ldots, Q_t\}$ be a set of polynomials in $N$ variables such that the algebraic rank of ${\cal Q}$ equals $k$. Let $d_i=\deg(Q_i)$ ($i\in [t]$) and let  ${\cal B} = \{Q_1, Q_2, \ldots, Q_k\}$ be a maximal algebraically independent subset of ${\cal Q}$. Then, there exists an $\overline{a} = (a_1, a_2, \ldots, a_N)$ in $\F^N$ and polynomials $F_{k+1}, F_{k+2}, \ldots, F_{t}$  in $k$ variables such that $\forall i \in \{k+1, k+2, \ldots, t\}$
$$Q_i(\overline{X} + \overline{a}) = \h^{\leq d_i}\left[F_i(Q_1(\overline{X} + \overline{a}), Q_2(\overline{X} + \overline{a}), \ldots, Q_k(\overline{X} + \overline{a})) \right]\,.$$

~\label{obs:internal1}
$A'_i$ satisfies the following


conditions.
\begin{itemize}
\item $A'_i$ is not identically zero.
\item The $Y$ degree of $A'_i$ is at least one. 
\item $Q_i(\overline{X})$ is a root of the polynomial $A'_i$, when viewing it as a polynomial in the $Y$ variable with coefficients coming from $\F(\overline{X})$.
\end{itemize}

~\label{cor:using algebraic independence new}
Let $\F$ be any  field of characteristic zero or sufficiently large. Let ${\cal Q} = \{Q_1, Q_2, \ldots, Q_t\}$ be a set of polynomials in $N$ variables such that the for every $i \in [t]$, the degree of  $Q_i$ is equal to $d_i < d$ and  the algebraic rank of ${\cal Q}$ equals $k$. Let  ${\cal B} = \{Q_1, Q_2, \ldots, Q_k\}$ be a maximal algebraically independent subset of ${\cal Q}$. Then, there exists an $\overline{a} = (a_1, a_2, \ldots, a_N)$ in $\F^N$ and polynomials $F_{k+1}, F_{k+2}, \ldots, F_{t}$  in at most $k(d+1)$ variables such that $\forall i \in \{k+1, k+2, \ldots, t\}$
$$Q_i(\overline{X} + \overline{a}) = F_i(\h[Q_1(\overline{X} + \overline{a})], \h[Q_2(\overline{X} + \overline{a})], \ldots, \h[Q_k(\overline{X} + \overline{a})])\,.$$

~\label{lem:subadditive}
Let  $P$ and $Q$ be any two multivariate polynomials in $\F[X_1, X_2, \ldots, X_{N}]$.  Let ${\cal M}$ be any set of monomials and $m$ be any positive integer. Then, for all scalars $\alpha$ and $\beta$
$$\Phi_{{\cal M}, m} (\alpha\cdot P + \beta\cdot Q) \leq \Phi_{{\cal M}, m} (P) + \Phi_{{\cal M}, m} (Q)\,.$$

~\label{lem:measure of homogeneous components}
Let $P$ be a polynomial of degree at most $d$. Then for every $0 \leq i \leq d$, and for every choice of parameters $m, r$ and a set $\cal M$ of monomials of degree equal to $r$, the following inequality is true.

$$\phi_{{\cal M}, m}(P) \geq  \phi_{{\cal M}, m}(\h^i[P])\,.$$

\label{lem:KS-tight-bound}
For every $n$ and $r = O(\sqrt{n})$ there exists parameters $q,e,  \epsilon$ such that $q = \Omega(n^2)$, $N = qn$ and $\epsilon = \Theta({\log(n)}/{\sqrt{n}})$ with
\begin{align*}
  q^r & \geq  (1+\epsilon)^{2(n-r)},\\
  q^{e-r} & =   \left(\frac{2}{1+\epsilon}\right)^{n-r} \cdot \poly(q)\,. 
\end{align*}
For any $\{n,q,e,r,\epsilon \}$ satisfying the above constraints, and for $m = ({N}/2)(1 - \epsilon)$,  over any field $\F$, we have
\[
\Phi(\NW_{n,q,e}) \geq \binom{N}{m + n - r} \cdot \exp(-O(\log^2 n))\,.
\]

~\label{lem:low support monomial}
Let $\F$ be a field of characteristic zero. Let $P$ be a  homogeneous polynomial of degree-$\Delta$ in $N$ variables such that  $P$ can be represented as $$P = \sum_{i = 1}^T  C_{i}(Q_{i1}, Q_{i2}, \ldots, Q_{it})    $$
such that the following are true.  
\begin{itemize}
\item For each $i \in[T]$, $C_i$ is a polynomial in $t$ variables. 
\item For each $i \in [T]$ and $j \in [t]$, $Q_{ij}$ is a polynomial of degree at most $d$ in $N$ variables. 
\item For each $i \in [T]$, the algebraic rank of the set $\{Q_{ij} : j \in [t]\}$ of polynomials  is at most $k$. 
\end{itemize}
Then, the trailing monomial of $P$ has support at most $$2\eee^3d\cdot(\ln \left({T(\Delta + 1)}\right) + (d+1)k\ln {\left(2(d+1)k\right)} + 1)\,.$$ Here, $\eee$ is



Euler's constant.

