\item Soundness: if $x \not\in L$, then for any quantum witness state $|\psi\>$ on $\mathrm{poly}(|x|)$ qubits, $\Pr\left[V(x, |\psi\>) \text{ accepts}\right] \le \frac{1}{3}$.
\end{enumerate}

