\label{theorem:main-result-agnostic-quantum-fourier-sampling-learning}
    Let $\mathcal{D}=(\mathcal{U}_n, \varphi)$ be an unknown probability distribution over $\{0,1\}^n\times\{0,1\}$, with (known) uniform marginal over $\{0,1\}^n$ and with (unknown) conditional label expectation $\varphi:\{0,1\}^n\to [0,1]$.
    \begin{enumerate}
        \item \textbf{Distributional agnostic quantum Fourier sampling:} There is an efficient quantum algorithm that, given a single copy of $\rho_\mathcal{D}$, with success probability $\nicefrac{1}{2}$ outputs a sample from a probability distribution over $\{0,1\}^n$ that is inverse-exponentially close to the squares of the Fourier coefficients of $\phi = 1-2\varphi$. 
        \item \textbf{Distributional agnostic proper quantum parity learning:} There is an efficient quantum algorithm that properly $1$-agnostically learns parities from an efficient number of copies of $\rho_\mathcal{D}$.
        \item \textbf{Distributional 2-agnostic improper quantum Fourier-sparse learning:} There is an efficient quantum algorithm that improperly $2$-agnostically learns Fourier-sparse functions from an efficient number of copies of $\rho_\mathcal{D}$. 
    \end{enumerate}

\label{theorem:main-result-verification}
    There is a class $\mathfrak{D}$ of probability distributions over $\{0,1\}^n\times\{0,1\}$ with (known) uniform marginal over $\{0,1\}^n$ such that:
    \begin{itemize}
        \item[(a)] Distributional $1$-agnostic parity learning is classically hard from SQs or random examples, even if the unknown distribution is promised to lie in  $\mathfrak{D}$.
        \item[(b)] When promised that the unknown distribution lies in $\mathfrak{D}$, there is an efficient interactive verification procedure that allows a classical verifier, with SQ or random example access, to verify a distributional $1$-agnostic quantum parity learner, who has mixture-of-superpositions example or QSQ access. 
        \item[(c)] When promised that the unknown distribution lies in $\mathfrak{D}$, there is an efficient interactive verification procedure that allows a classical verifier, with SQ or random example access, to verify a distributional $2$-agnostic quantum Fourier-sparse learner, who has mixture-of-superpositions example or QSQ access.
    \end{itemize}

\label{definition:fourier-coefficients}
    Let $\phi:\mathcal{X}_n\to \mathbb{R}$.
    Then, for any $s\in \{0,1\}^n = \mathcal{X}_n^\ast = \mathcal{X}_n$, we define the Fourier coefficient $\hat{\phi}(s)\in [-\norm{\phi}_\infty, \norm{\phi}_\infty]$ as
    \begin{equation}\label{eq:fourier-coefficient}
        \hat{\phi}(s)
        \coloneqq \mathbb{E}_{x\sim\mathcal{U}_n} \left[ \phi(x) \chi_s(x) \right] ,
    \end{equation}
    with the parity functions $\chi_s : \mathcal{X}_n\to \{-1,1\}$ defined as $\chi_s(x) = (-1)^{s\cdot x}$. Here, the inner product $s\cdot x$ is taken modulo $2$, i.e., $s\cdot x\coloneqq \sum_{i=1}^n s_i x_i \mod 2$.

Let $\phi:\mathcal{X}_n\to \mathbb{R}$. We denote the set of non-zero Fourier coefficients of $\phi$ by
\begin{equation}
    \operatorname{supp}(\phi)
    \coloneqq \{s\in\mathcal{X}_n~|~ \hat{\phi}(s)\neq 0\}.
\end{equation}
If $\lvert \operatorname{supp}(\phi)\rvert = k$, then we say that $\phi$ is Fourier-$k$-sparse.

\label{def:agnostic-learning}
  We say that a learning algorithm $\mathcal{A}$ is an $\alpha$-agnostic learner for the benchmark class $\mathcal{B}$, via the model class $\mathcal{M}$, with respect to the distribution class $\mathfrak{D}$ over $\mathcal{X}_n\times\{0,1\}$, from oracle $\mathsf{O}$ if: 
    For all $\mathcal{D}\in\mathfrak{D}$, when given access to oracle $\mathsf{O}(\mathcal{D})$, as well as some $(\epsilon,\delta)\in (0,1)$, algorithm $\mathcal{A}$ outputs, with probability at least $1-\delta$, some model $m\in\mathcal{M}$ such that  
    \begin{equation}\label{eq:learning_criterion}
        \mathrm{err}_{\mathcal{D}}(m)\leq \alpha\cdot\mathrm{opt}_{\mathcal{D}}(\mathcal{B}) +\epsilon.
    \end{equation}

\label{definition:functional-superposition-quantum-examples}
    Let $\mathcal{D}_{\mathcal{X}_n}$ be some distribution over $\mathcal{X}_n$ and  $f:\mathcal{X}_n\to\{0,1\}$. The pure superposition oracle, when queried, will return a copy of the pure superposition state  given by
    \begin{equation}\label{eq:superposition-functional-example}
        \ket{\psi_{(\mathcal{D}_{\mathcal{X}_n}, f)}}
        = \sum_{x\in \mathcal{X}_n} \sqrt{\mathcal{D}_{\mathcal{X}_n}(x)} \ket{x,f(x)}.
    \end{equation}

\label{definition:noisy-functional-quantum-examples}
    Let $\mathcal{D} = (\mathcal{D}_{\mathcal{X}_n}, f)$ be a probability distribution over $\mathcal{X}_n\times \{0,1\}$ with deterministic labeling function $f:\mathcal{X}_n\to\{0,1\}$. Let $0\leq \eta < \nicefrac{1}{2}$ be a noise parameter. 
    \begin{itemize}
        \item[(i)] A \emph{mixed $\eta$-noisy functional quantum example for $\mathcal{D} = (\mathcal{D}_{\mathcal{X}_n}, f)$} is a copy of the mixed $(n+1)$-qubit state
        \begin{equation}\label{eq:mixed-noisy-functional-quantum-example}
            \rho_{(\mathcal{D}_{\mathcal{X}_n}, f),\eta}
            \coloneqq (1-\eta)\ket{\psi_{(\mathcal{D}_{\mathcal{X}_n},f)}}\bra{\psi_{(\mathcal{D}_{\mathcal{X}_n},f)}} + \eta\ket{\psi_{(\mathcal{D}_{\mathcal{X}_n},f\oplus 1)}}\bra{\psi_{(\mathcal{D}_{\mathcal{X}_n},f\oplus 1)}} ,
        \end{equation}
        where $\oplus$ denotes additional modulo $2$.
        \item[(ii)] A \emph{pure $\eta$-noisy functional quantum example for $\mathcal{D} = (\mathcal{D}_{\mathcal{X}_n}, f)$} is a pure superposition quantum example $\ket{\psi_{\mathcal{D}_\eta}}$ according to \Cref{definition:superposition-quantum-examples}, where $\mathcal{D}_\eta$ is the probability distribution over $\mathcal{X}_n\times \{0,1\}$ defined as
        \begin{equation}
            \mathcal{D}_\eta (x,f(x)) = (1-\eta)\mathcal{D}_{\mathcal{X}_n}(x) ,~
            \mathcal{D}_\eta (x,f(x)\oplus 1) = \eta\mathcal{D}_{\mathcal{X}_n}(x),\quad\forall x\in\mathcal{X}_n .
        \end{equation}
        That is, such a quantum example is a copy of the pure $(n+1)$-qubit state
        \begin{equation}\label{eq:pure-noisy-functional-quantum-example}
            \ket{\psi_{\mathcal{D}_\eta}}
            \coloneqq \frac{1}{\sqrt{2^n}}\sum_{x\in\{0,1\}^n} \left(\sqrt{1-\eta}\ket{x,f(x)}+\sqrt{\eta}\ket{x,f(x)\oplus 1}\right) ,
        \end{equation}
        where $\oplus$ denotes additional modulo $2$.
        \item[(iii)] A \emph{mixture-of-superpositions $\eta$-noisy functional quantum example for $\mathcal{D} = (\mathcal{D}_{\mathcal{X}_n}, f)$} is a copy of the mixed $(n+1)$-qubit state
        \begin{equation}\label{eq:mixture-of-superpositions-noisy-functional-quantum-example}
            \rho_{\mathcal{D}_\eta}
            \coloneqq \mathbb{E}_{\{e_x\}_{x\in\mathcal{X}_n}} \left[ \ket{\psi_{(\mathcal{D}_{\mathcal{X}_n},f \oplus e)}}\bra{\psi_{(\mathcal{D}_{\mathcal{X}_n},f\oplus e)}} \right] ,
        \end{equation}
        where the $e_x$, $x\in\mathcal{X}_n$, are i.i.d.~random variables with $\mathbb{P}[e_x = 0 ]=1-\eta=1-\mathbb{P}[e_x = 1 ]$ for all $x\in\mathcal{X}_n$.
    \end{itemize}

\label{definition:superposition-quantum-examples}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$.
    Then, a \emph{pure superposition example for $\mathcal{D}$} is a copy of the pure $(n+1)$-qubit state 
    \begin{equation}\label{eq:superposition-quantum-examples}
        \ket{\psi_{\mathcal{D}}}
        = \ket{\psi_{(\mathcal{D}_{\mathcal{X}_n}, \varphi)}}
        \coloneqq \sum_{x\in\{0,1\}^n}\sum_{y\in\{0,1\}} \sqrt{\mathcal{D}(x,y)}\ket{x,y}
        = \sum_{x\in\{0,1\}^n} \sqrt{\mathcal{D}\rvert_{\mathcal{X}_n}(x) }\left(\sqrt{1-\varphi(x)}\ket{x,0} + \sqrt{\varphi(x)}\ket{x,1} \right) .
    \end{equation}
    Accordingly, a \emph{pure superposition quantum example oracle for $\mathcal{D}$} is an oracle that when queried outputs a copy of $\ket{\psi_{\mathcal{D}}}$.

\label{definition:interactive-verification-of-learning}
    Let $\mathcal{F}\subseteq\{0,1\}^{\mathcal{X}_n}$ be a benchmark class.
    Let $\mathfrak{D}$ be a family of probability distributions over $\mathcal{X}_n\times\{0,1\}$.
    Let $\alpha\geq 1$.
    We say that \emph{$\mathcal{F}$ is $\alpha$-agnostic verifiable with respect to $\mathfrak{D}$ using classical or quantum oracles $\mathsf{O}_V$ and $\mathsf{O}_P$} if there exists a pair of classical or quantum algorithms $(V,P)$ that satisfy the following conditions for every input accuracy parameter $\varepsilon\in (0,1)$ and for every confidence parameter $\delta\in (0,1)$:
    \begin{itemize}
        \item \textbf{Completeness:} For any $\mathcal{D}\in\mathfrak{D}$, the random hypothesis $h:\mathcal{X}_n\to \{0,1\}$ that $V(\varepsilon,\delta)$ outputs after interacting with the honest prover $P$, assuming $V(\varepsilon,\delta)$ has access to $\mathsf{O}_V (\mathcal{D})$ and $P(\varepsilon,\delta)$ has access to $\mathsf{O}_P (\mathcal{D})$, satisfies
        \begin{equation}
            \mathbb{P}\left[h\neq\mathrm{reject}~\wedge ~ \left(\operatorname{err}_{\mathcal{D}}(h)\leq \alpha\cdot \operatorname{opt}_{\mathcal{D}}(\mathcal{F}) + \varepsilon\right)\right] 
            \geq 1-\delta .
        \end{equation}
        \item \textbf{Soundness:} For any $\mathcal{D}\in\mathfrak{D}$ and for any (possibly unbounded) dishonest prover $P'$, the random hypothesis $h:\mathcal{X}_n\to \{0,1\}$ that $V(\varepsilon,\delta)$ outputs after interacting with $P'$, assuming $V(\varepsilon,\delta)$ has access to $\mathsf{O}_V (\mathcal{D})$ and $P'(\varepsilon,\delta)$ has access to $\mathsf{O}_P (\mathcal{D})$, satisfies
        \begin{equation}
            \mathbb{P}\left[h\neq\mathrm{reject}~\wedge ~ \left(\operatorname{err}_{\mathcal{D}}(h)> \alpha\cdot \operatorname{opt}_{\mathcal{D}}(\mathcal{F}) + \varepsilon\right)\right] 
            \leq \delta .
        \end{equation}
    \end{itemize}
    Moreover:
    \begin{itemize}
        \item If the above can be achieved with a pair $(V,P)$ such that $V(\varepsilon,\delta)$ makes at most $\mathcal{O}(\poly (n, \nicefrac{1}{\varepsilon}, \nicefrac{1}{\delta}))$ queries to $\mathsf{O}_V (\mathcal{D})$, such that $P(\varepsilon,\delta)$ makes at most $\mathcal{O}(\poly (n, \nicefrac{1}{\varepsilon}, \nicefrac{1}{\delta}))$ queries to $\mathsf{O}_P (\mathcal{D})$, and such that both $V(\varepsilon,\delta)$ and $P(\varepsilon,\delta)$ have running time $\mathcal{O}(\poly (n, \nicefrac{1}{\varepsilon}, \nicefrac{1}{\delta}))$, then we say that \emph{$\mathcal{F}$ is efficiently $\alpha$-agnostic verifiable with respect to $\mathfrak{D}$ using oracles $\mathsf{O}_V$ and $\mathsf{O}_P$}.
        \item If additionally one can ensure that the random hypothesis $h:\mathcal{X}_n\to \{0,1\}$ that $V(\varepsilon,\delta)$ outputs after interacting with any (possibly unbounded) dishonest prover $P'$, assuming $V(\varepsilon,\delta)$ has access to $\mathsf{O}_V (\mathcal{D})$ and $P'(\varepsilon,\delta)$ has access to $\mathsf{O}_P (\mathcal{D})$, satisfies $h\in \{\mathrm{reject}\}\cup \mathcal{F}$ almost surely, then we say that \emph{$\mathcal{F}$ is proper $\alpha$-agnostic verifiable with respect to $\mathfrak{D}$ using oracles $\mathsf{O}_V$ and $\mathsf{O}_P$}.
    \end{itemize}

\label{definition:mixture-of-superpositions-quantum-example}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$.
    Let $F_\mathcal{D}$ be the probability distribution over $\{0,1\}^{\mathcal{X}_n}$ defined by sampling $f(x)$ from the conditional label distribution independently for each $x\in\mathcal{X}_n$. 
    That is, for any $\Tilde{f}:\mathcal{X}_n\to \{0,1\}$,
    \begin{equation}\label{eq:induced-distribution-over-functions}
        \mathbb{P}_{f\sim F_\mathcal{D}} [f=\Tilde{f}]
        = \prod_{z\in\mathcal{X}_n} \mathbb{P}_{(x,y)\sim \mathcal{D}}[ \tilde{f}(z)=y | x=z ]
        = \prod_{z\in\mathcal{X}_n} \left( (1-\varphi(z))(1-\tilde{f}(z)) + \varphi(z) \tilde{f}(z) \right) .
    \end{equation}
    Then, a \emph{mixture-of-superpositions quantum example for $\mathcal{D}$} is a copy of the mixed $(n+1)$-qubit state
    \begin{equation}\label{eq:mixture-of-superpositions-quantum-example}
        \rho_\mathcal{D}
        = \mathbb{E}_{f\sim F_\mathcal{D}} \left[ \ket{\psi_{(\mathcal{D}_{\mathcal{X}_n}, f)}}\bra{\psi_{(\mathcal{D}_{\mathcal{X}_n}, f)}} \right] .
    \end{equation}
    Accordingly, a \emph{mixture-of-superpositions quantum example oracle for $\mathcal{D}$} is an oracle that when queried outputs a copy of $\rho_\mathcal{D}$.

\label{lemma:sanity-check-reproduce-classical-sample}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$.
    Performing computational basis measurements on all $n+1$ qubits of a copy of $\rho_\mathcal{D}$ produces a sample from $\mathcal{D}$.

\label{lemma:functional-quantum-Fourier-sampling}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{U}_n, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$. 
    Consider the following quantum algorithm: 
    Given a single copy of $\ket{\psi_{(\mathcal{U}_n, f)}}$, first apply the unitary $H^{\otimes (n+1)}$, then measure all $n+1$ qubits in the computational basis.
    The measurement outcomes of this procedure satisfy the following:
    \begin{itemize}
        \item[(i)] The computational basis measurement on the last qubit gives outcome $0$ with probability $\nicefrac{1}{2}$ and outcome $1$ with probability $\nicefrac{1}{2}$.
        \item[(ii)] Conditioned on having observed outcome $1$ for the last qubit, the computational basis measurement on the first $n$ qubits outputs a string $s\in\{0,1\}^n$ with probability $(\hat{g}(s))^2$, with $g=(-1)^f$.
    \end{itemize}

\label{lemma:distribution-estimation-infty-norm}
    Let  $q:\{0,1\}^n\to [0,1]$ be a probability distribution and let $\tau,\delta \in (0,1)$.
    Then, there exists a classical algorithm that, given $m=\mathcal{O}\left(\tfrac{\log(1/\delta)}{\tau^2}\right)$ i.i.d.~samples from $q$, uses classical computation time $\mathcal{O}\left(n\tfrac{\log(1/\delta)}{\tau^2}\log\left(\tfrac{\log(1/\delta)}{\tau^2}\right)\right) = \tilde{\mathcal{O}}\left(n \tfrac{ \log(1/\delta)}{\tau^2}\right)$ and classical memory of size $\tilde{\mathcal{O}}\left(n\tfrac{\log(1/\delta)}{\tau^2}\right)$, and outputs, with success probability $\geq 1-\delta$, a succinctly represented empirical estimate $\tilde{q}_m : \{0,1\}^n\to [0,1]$ such that $\norm{q-\tilde{q}_m}_\infty\leq\tau$ and $\norm{\tilde{q}_m}_0\leq \mathcal{O}\left(\tfrac{\log(1/\delta)}{\tau^2}\right)$.

\label{corollary:quantum-functional-agnostic-parity-learning}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{U}_n, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$. 
    Let $\delta,\varepsilon\in (0,1)$.
    Then, there exists a quantum algorithm that, given $\mathcal{O}\left(\tfrac{\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ copies of $\ket{\psi_{\mathcal{D}}}$, uses $\mathcal{O}\left(n\tfrac{\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ single-qubit gates, classical computation time $\tilde{\mathcal{O}}\left(n\tfrac{\log(\nicefrac{1}{\delta \varepsilon^2})}{\varepsilon^4}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(n\tfrac{\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and outputs, with success probability $\geq 1-\delta$, a bit string $s\in\{0,1\}^n$ such that
    \begin{equation}
        \mathbb{P}_{x\sim\mathcal{U}_n}[f(x)\neq s\cdot x]
        \leq \min\limits_{t\in\{0,1\}^n} \mathbb{P}_{x\sim\mathcal{U}_n}[f(x)\neq t\cdot x] + \varepsilon\, .
    \end{equation}
    Thus, this quantum algorithm is a functional agnostic proper quantum parity learner, assuming a uniform marginal over inputs.

\label{corollary:quantum-functional-agnostic-fourier-sparse-learning}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{U}_n, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$. 
    Let $\delta,\varepsilon\in (0,1)$.
    Then, there is a quantum algorithm that, given $\mathcal{O}\left(\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ copies of $\rho_\mathcal{D}$, uses $\mathcal{O}\left(n\tfrac{k^4\log(\nicefrac{1}{\delta})}{\varepsilon^4}\right)$ single-qubit gates, classical computation time $\tilde{\mathcal{O}}\left(n\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(n\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and outputs, with success probability $\geq 1-\delta$, a randomized hypothesis $h:\mathcal{X}_n\to\{0,1\}$ such that
    \begin{equation}
        \mathbb{P}_{(x,b)\sim\mathcal{D}} \left[b\neq h(x)\right]
        \leq 2 \min\limits_{\substack{\tilde{f}:\mathcal{X}_n\to\{0,1\}\\\mathrm{Fourier-}k\mathrm{-sparse}}} \mathbb{P}_{(x,b)\sim\mathcal{D}}[b\neq \tilde{f}(x)] + \varepsilon\, .
    \end{equation}
    In particular, this quantum algorithm is a functional $2$-agnostic improper quantum Fourier-sparse learner, assuming a uniform marginal over inputs.

\label{lemma:noisy-functional-quantum-Fourier-sampling-v1}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{U}_n, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$. 
    Let $0\leq \eta <\nicefrac{1}{2}$.
    Consider the following quantum algorithm: 
    Given a single copy of $\rho_{(\mathcal{U}_n, f),\eta}$, first apply (the unitary channel for) the unitary $H^{\otimes (n+1)}$, then measure all $n+1$ qubits in the computational basis.
    The measurement outcomes of this procedure satisfy the following:
    \begin{itemize}
        \item[(i)] The computational basis measurement on the last qubit gives outcome $0$ with probability $\nicefrac{1}{2}$ and outcome $1$ with probability $\nicefrac{1}{2}$.
        \item[(ii)] Conditioned on having observed outcome $1$ for the last qubit, the computational basis measurement on the first $n$ qubits outputs a string $s\in\{0,1\}^n$ with probability $(\hat{g}(s))^2$, with $g=(-1)^f$.
    \end{itemize}

\label{lemma:noisy-functional-quantum-Fourier-sampling-v2}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{U}_n, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$. 
    Let $0\leq \eta <\nicefrac{1}{2}$.
    Consider the following quantum algorithm: 
    Given a single copy of $\ket{\psi_{\mathcal{D}_\eta}}$, first apply (the unitary channel for) the unitary $H^{\otimes (n+1)}$, then measure all $n+1$ qubits in the computational basis.
    The measurement outcomes of this procedure satisfy the following:
    \begin{itemize}
        \item[(i)] The computational basis measurement on the last qubit gives outcome $0$ with probability $\tfrac{1}{2}+ \sqrt{(1-\eta)\eta}$ and outcome $1$ with probability $\tfrac{1}{2} - \sqrt{(1-\eta)\eta}$.
        \item[(ii)] Conditioned on having observed outcome $1$ for the last qubit, the computational basis measurement on the first $n$ qubits outputs a string $s\in\{0,1\}^n$ with probability $(\hat{g}(s))^2$, with $g=(-1)^f$.
    \end{itemize}

\label{lemma:noisy-functional-quantum-Fourier-sampling-v3}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{U}_n, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$. 
    Let $0\leq \eta <\nicefrac{1}{2}$.
    Consider the following quantum algorithm: 
    Given a single copy of $\rho_{\mathcal{D}_\eta}$, first apply (the unitary channel for) the unitary $H^{\otimes (n+1)}$, then measure all $n+1$ qubits in the computational basis.
    The measurement outcomes of this procedure satisfy the following:
    \begin{itemize}
        \item[(i)] The computational basis measurement on the last qubit gives outcome $0$ with probability $\tfrac{1}{2}$ and outcome $1$ with probability $\tfrac{1}{2}$.
        \item[(ii)] Conditioned on having observed outcome $1$ for the last qubit, the computational basis measurement on the first $n$ qubits outputs a string $s\in\{0,1\}^n$ with probability $\tfrac{4\eta - 4\eta^2}{2^n} + (1-2\eta)^2\hat{g}(s)^2$, with $g=(-1)^f$.
    \end{itemize}

\label{definition:functional-qsq}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{D}_{\mathcal{X}_n}, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$.
    A \emph{(functional) quantum statistical query (QSQ) oracle for $\mathcal{D}$} produces, when queried with a bounded $(n+1)$-qubit observable $M=M^\dagger\in\mathcal{B}((\mathbb{C}^2)^{\otimes (n+1)})$ satisfying $\norm{M}\leq 1$ and with a tolerance parameter $\tau> 0$, a number $\mu\in\mathbb{R}$ such that
    \begin{equation}
        \left\lvert \mu - \bra{\psi_{(\mathcal{D}_{\mathcal{X}_n}, f)}} M \ket{\psi_{(\mathcal{D}_{\mathcal{X}_n}, f)}} \right\rvert
        \leq \tau ,
    \end{equation}
    where $\ket{\psi_{(\mathcal{D}_{\mathcal{X}_n}, f)}}$ is a (functional) pure superposition example as in \Cref{definition:functional-superposition-quantum-examples}.

\label{theorem:functional-agnostic-qsq-GL}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}=(\mathcal{U}_n, f)$ for some deterministic labeling function $f:\{0,1\}^n\to\{0,1\}$. 
    Let $\varepsilon\in (0,1)$. 
    Then, there exists an algorithm that, using $\mathcal{O}\left(\tfrac{n}{\varepsilon^2}\right)$ functional QSQs of tolerance $\nicefrac{\varepsilon^2}{8}$ for observables that can be implemented with $\mathcal{O}(n)$ single-qubit gates, classical computation time $\tilde{\mathcal{O}}\left(\tfrac{n}{\varepsilon^2}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(\tfrac{n^2}{\varepsilon^2}\right)$, and outputs a list $L=\{s_1,\ldots,s_{\lvert L\rvert}\}\subseteq\{0,1\}^n$ such that \begin{itemize}
        \item[(i)] if $\lvert \hat{g}(s)\rvert\geq \varepsilon$, then $s\in L$, and
        \item[(ii)] if $s\in L$, then $\lvert \hat{g}(s)\rvert\geq \nicefrac{\varepsilon}{2}$.
    \end{itemize}
    This list has length $\lvert L\rvert\leq \nicefrac{4}{\varepsilon^2}$ by Parseval.

\label{theorem:agnostic-quantum-fourier-sampling}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}_{\mathcal{X}_n}=\mathcal{U}_n$.
    Consider the following quantum algorithm:
    Given a single copy of $\rho_\mathcal{D}$, first apply (the unitary channel for) the unitary $H^{\otimes (n+1)}$, then measure all $n+1$ qubits in the computational basis. 
    The measurement outcomes of this procedure satisfy the following:
    \begin{itemize}
        \item[(i)] The computational basis measurement on the last qubit gives outcome $0$ with probability $\nicefrac{1}{2}$ and outcome $1$ with probability $\nicefrac{1}{2}$.
        \item[(ii)] Conditioned on having observed outcome $1$ for the last qubit, the computational basis measurement on the first $n$ qubits outputs a string $s\in\{0,1\}^n$ with probability 
        \begin{equation}
            \frac{1}{2^n}\left(1 - \mathbb{E}_{x\sim\mathcal{U}_n}[(\phi(x))^2]\right) + (\hat{\phi}(s))^2 .
        \end{equation}
    \end{itemize}

\label{corollary:agnostic-quantum-parity-learning}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}_{\mathcal{X}_n}=\mathcal{U}_n$.
    Let $\delta,\varepsilon\in (0,1)$. Assume that $\varepsilon > 2^{-(\tfrac{n}{2} - 2)}$.
    There is a quantum algorithm that, given $\mathcal{O}\left(\tfrac{\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ copies of $\rho_\mathcal{D}$, uses $\mathcal{O}\left(n\tfrac{\log(\nicefrac{1}{\delta \varepsilon^2})}{\varepsilon^4}\right)$ single-qubit gates, classical computation time $\tilde{\mathcal{O}}\left(n\tfrac{\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(n\tfrac{\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and outputs, with success probability $\geq 1-\delta$, a bit string $s\in\{0,1\}^n$ such that 
    \begin{equation}
        \mathbb{P}_{(x,b)\sim\mathcal{D}}[b\neq s\cdot x]
        \leq \min\limits_{t\in\{0,1\}^n} \mathbb{P}_{(x,b)\sim\mathcal{D}}[b\neq t\cdot x] + \varepsilon\, .
    \end{equation}
    Thus, this quantum algorithm is a distributional agnostic proper quantum parity learner up to inverse-exponen\-tial\-ly small accuracies, assuming a uniform marginal over inputs.

\label{corollary:agnostic-quantum-fourier-sparse-learning}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}_{\mathcal{X}_n}=\mathcal{U}_n$.
    Let $\delta,\varepsilon\in (0,1)$. Assume that $\varepsilon > 2^{-(\tfrac{n}{2} - 2)}$.
    Then, there is a quantum algorithm that, given $\mathcal{O}\left(\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ copies of $\rho_\mathcal{D}$, uses $\mathcal{O}\left(n\tfrac{k^4\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ single-qubit gates, classical computation time $\tilde{\mathcal{O}}\left(n\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(n\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and outputs, with success probability $\geq 1-\delta$, a randomized hypothesis $h:\mathcal{X}_n\to\{0,1\}$ such that
    \begin{equation}
        \mathbb{P}_{(x,b)\sim\mathcal{D}} \left[b\neq h(x)\right]
        \leq 2 \min\limits_{\substack{\tilde{f}:\mathcal{X}_n\to\{0,1\}\\\mathrm{Fourier-}k\mathrm{-sparse}}} \mathbb{P}_{(x,b)\sim\mathcal{D}}[b\neq \tilde{f}(x)] + \varepsilon\, .
    \end{equation}
    In particular, this quantum algorithm is a distributional $2$-agnostic improper quantum Fourier-sparse learner up to inverse-exponentially small accuracies, assuming a uniform marginal over inputs.

\label{corollary:agnostic-quantum-fourier-sparse-learning-L2}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with $\mathcal{D}_{\mathcal{X}_n}=\mathcal{U}_n$.
    Let $\delta,\varepsilon\in (0,1)$. Assume that $\varepsilon > 2^{-(\tfrac{n}{2} - 2)}$.
    There is a quantum algorithm that, given $\mathcal{O}\left(\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ copies of $\rho_\mathcal{D}$, uses $\mathcal{O}\left(n\tfrac{k^4\log(\nicefrac{1}{\delta\varepsilon^2})}{\varepsilon^4}\right)$ single-qubit gates, classical computation time $\tilde{\mathcal{O}}\left(n\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(n\tfrac{k^4\log(\nicefrac{k^2}{\delta\varepsilon^2})}{\varepsilon^4}\right)$, and outputs, with success probability $\geq 1-\delta$, a Fourier-$k$-sparse function $g:\mathcal{X}_n\to\mathbb{R}$ such that 
    \begin{equation}
        \mathbb{E}_{(x,b)\sim\mathcal{D}}[(y-g(x))^2]
        \leq \min\limits_{\substack{\tilde{f}:\mathcal{X}_n\to\{-1,1\}\\\mathrm{Fourier-}k\mathrm{-sparse}}} \mathbb{E}_{(x,b)\sim\mathcal{D}}[(y-\tilde{f}(x))^2] + \varepsilon\, .
    \end{equation}

\label{definition:distributional-agnostic-qsq}
    Let $\mathcal{D}$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$.
    A \emph{(distributional) quantum statistical query (QSQ) oracle for $\mathcal{D}$} produces, when queried with a bounded $(n+1)$-qubit observable $M=M^\dagger\in\mathcal{B}((\mathbb{C}^2)^{\otimes (n+1)})$ satisfying $\norm{M}\leq 1$ and with a tolerance parameter $\tau > 0$, a number $\mu\in\mathbb{R}$ such that
    \begin{equation}
        \left\lvert \mu - \tr[ M \rho_{\mathcal{D}}] \right\rvert
        \leq \tau ,
    \end{equation}
    where $\rho_{\mathcal{D}}$ is a (distributional) mixture-of-superpositions examples as in \Cref{definition:mixture-of-superpositions-quantum-example}.

\label{theorem:distributional-agnostic-qsq-GL}
    Let $\mathcal{D} = (\mathcal{U}_n, \varphi)$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with uniform marginal over $\mathcal{X}_n$.
    Let $\varepsilon\in (0,1)$. 
    Then, there exists an algorithm that, using $\mathcal{O}\left(\tfrac{n}{\varepsilon^2}\right)$ distributional QSQs of tolerance $\nicefrac{\varepsilon^2}{8}$ for observables that can be implemented with $\mathcal{O}(n)$ single-qubit gates, classical computation time $\tilde{\mathcal{O}}\left(\tfrac{n}{\varepsilon^2}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(\tfrac{n^2}{\varepsilon^2}\right)$, and outputs a list $L=\{s_1,\ldots,s_{\lvert L\rvert}\}\subseteq\{0,1\}^n$ such that \begin{itemize}
        \item[(i)] if $\lvert \hat{\phi}(s)\rvert\geq \varepsilon$, then $s\in L$, and
        \item[(ii)] if $s\in L$, then $\lvert \hat{\phi}(s)\rvert\geq \nicefrac{\varepsilon}{2}$.
    \end{itemize}
    This list has length $\lvert L\rvert\leq \nicefrac{4 \mathbb{E}_{x\sim\mathcal{U}_n}[(\phi(x))^2]}{\varepsilon^2}\leq \nicefrac{4}{\varepsilon^2}$ by Parseval.

\label{corollary:agnostic-qsq-learning}
    Let $\delta,\varepsilon\in (0,1)$. 
    \begin{itemize}
        \item There is an algorithm that uses $\mathcal{O}\left(\tfrac{n}{\varepsilon^2}\right)$ distributional agnostic QSQs with tolerance $\mathcal{O}(\varepsilon^2)$, classical computation time $\mathcal{O}\left(\tfrac{n}{\varepsilon^2}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(\tfrac{n^2}{\varepsilon^2}\right)$, and achieves distributional $1$-agnostic proper parity learning w.r.t.~uniformly random inputs.
        \item There is an algorithm that uses $\mathcal{O}\left(\tfrac{nk^2}{\varepsilon^2}\right)$ distributional agnostic QSQs with tolerance $\mathcal{O}\left(\tfrac{\varepsilon^2}{k^2}\right)$, classical computation time $\mathcal{O}\left(\tfrac{n k^2}{\varepsilon^2}\right)$, and classical memory of size $\tilde{\mathcal{O}}\left(\tfrac{n^2 k^2}{\varepsilon^2}\right)$, and achieves distributional $2$-agnostic improper Fourier-sparse learning w.r.t.~uniformly random inputs.
    \end{itemize}

\label{definition:functional-no-small-fourier-coefficients}
    Let $\vartheta\in (0,1)$.
    We denote the class of probability distributions $\mathcal{D} = (\mathcal{U}_n, f)$ over $\mathcal{X}_n\times\{0,1\}$ that have a uniform marginal over $\mathcal{X}_n$ and whose $\{-1,1\}$-labels are given by a deterministic function $g=(-1)^f$ that has no non-zero Fourier coefficients of magnitude $<\vartheta$ by 
    \begin{equation}
        \mathfrak{D}_{ \mathcal{U}_n; \geq \vartheta}^{\mathrm{func}}
        \coloneqq \left\{ (\mathcal{U}_n, f)~|~ f:\mathcal{X}_n\to\{0,1\}~\wedge (\hat{g}\neq 0~\Rightarrow \lvert \hat{g}\rvert \geq \vartheta ) \right\} .
    \end{equation}

\label{lemma:no-small-nonzero-Fourier-coeff-versus-sparsity}
    Let $\vartheta\in (0,1)$. 
    Then we have the inclusions
    \begin{equation}
        \left\{(\mathcal{U}_n, f)~|~ f:\mathcal{X}_n\to\{0,1\}~\textrm{s.t.}~g=(-1)^f~\textrm{is Fourier}~\left\lfloor\tfrac{2}{\vartheta}\right\rfloor\textrm{-sparse}\right\}
        \subseteq\mathfrak{D}_{ \mathcal{U}_n; \geq \vartheta}^{\mathrm{func}}    
    \end{equation}
    and 
    \begin{equation}
        \mathfrak{D}_{ \mathcal{U}_n; \geq \vartheta}^{\mathrm{func}}
        \subseteq \left\{(\mathcal{U}_n, f)~|~ f:\mathcal{X}_n\to\{0,1\}~\textrm{s.t.}~g=(-1)^f~\textrm{is Fourier}~\left(\tfrac{1}{\vartheta^2}\right)\textrm{-sparse}\right\}.
    \end{equation}

\label{{definition:noisy-functional-no-small-fourier-coefficients}}
    Let $\vartheta\in (0,1)$. Let $0\leq \eta <\nicefrac{1}{2}$.
    We denote the class of probability distributions $\mathcal{D} = (\mathcal{U}_n, \varphi)$ over $\mathcal{X}_n\times\{0,1\}$ that have a uniform marginal over $\mathcal{X}_n$ and whose $\{-1,1\}$-label is given as $\eta$-noisy version of deterministic function $g=(-1)^f$ that has no non-zero Fourier coefficients of magnitude $<\vartheta$ by 
    \begin{equation}
        \mathfrak{D}_{ \mathcal{U}_n; \geq \vartheta}^{\mathrm{func},\eta}
        \coloneqq \left\{ (\mathcal{U}_n, \varphi)~|~ \exists f:\mathcal{X}_n\to\{0,1\} \textrm{ s.t. } (\varphi = \eta + (1-2\eta)f)  \wedge ((\mathcal{U}_n,f)\in \mathfrak{D}_{ \mathcal{U}_n; \geq \vartheta}^{\mathrm{func}}) \right\} .
    \end{equation}

\label{definition:distributional-no-small-fourier-coefficients}
    Let $\vartheta\in (0,1)$.
    We denote the class of probability distributions $\mathcal{D} = (\mathcal{U}_n, \varphi)$ over $\mathcal{X}_n\times\{0,1\}$ that have a uniform marginal over $\mathcal{X}_n$ and whose $\{-1,1\}$-label expectation $\phi$ has no non-zero Fourier coefficients of magnitude $<\vartheta$ by 
    \begin{equation}
        \mathfrak{D}_{ \mathcal{U}_n; \geq \vartheta}
        \coloneqq \left\{ (\mathcal{U}_n, \varphi)~|~ \hat{\phi}\neq 0~\Rightarrow \lvert \hat{\phi}\rvert \geq \vartheta \right\} .
    \end{equation}

\label{definition:l2-bounded-bias}
    Let $0\leq a \leq b\leq 1$.
    We denote the class of probability distributions $\mathcal{D} = (\mathcal{U}_n, \varphi)$ over $\mathcal{X}_n\times\{0,1\}$ that have a uniform marginal over $\mathcal{X}_n$ and whose $\{-1,1\}$-label expectation $\phi$ has squared $L_2$ norm in $[a^2,b^2]$ by
    \begin{equation}
        \mathfrak{D}_{ \mathcal{U}_n; [a^2,b^2]}
        \coloneqq\left\{(\mathcal{U}_n, \varphi)~|~ \mathbb{E}_{x\sim\mathcal{U}_n}[(\phi(x))^2]\in [a^2,b^2]\right\} .
    \end{equation}

\label{theorem:distribution-independent-lower-bound}
    Let $\mathcal{F}\subseteq\{0,1\}^{\mathcal{X}_n}$ be a benchmark class with VC-dimension $\operatorname{VC}(\mathcal{F})=d\geq 1$.
    Then at least
    \begin{equation}
        m\geq \tilde{\Omega} \left( \frac{d + \log(1/\delta)}{\varepsilon^2} \right)
    \end{equation}
    copies of $\rho_\mathcal{D}$, with $\mathcal{D}$ an unknown probability distribution over $\{0,1\}^n\times\{0,1\}$, are necessary for distribution-independent quantum agnostic learning of $\mathcal{F}$ with accuracy $\varepsilon\in (0,\tfrac{1}{4})$ and confidence parameter $\delta \in (0,\tfrac{1}{2})$. 
    Here, the $\tilde{\Omega}$ hides prefactors logarithmic in $d$.

\label{lemma:general-loss-explicit-inner-product}
    Let $\mathcal{D}=(\mathcal{U}_n, \varphi)$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with uniform input marginal.
    Let $f:\{0,1\}^n\to\{0,1\}$ and $g=(-1)^f$. 
    Then,
    \begin{align}
        \mathbb{P}_{(x,b)\sim \mathcal{D}}[b\neq f(x)]
        &= \frac{1-\langle \phi,g\rangle_{\mathcal{U}_n}}{2}\\
        &= \frac{1-\sum_{s\in\{0,1\}^n}\hat{g}(s)\hat{\phi}(s)}{2}\\
        &= \frac{1}{4} \left(\sum_{s\in\{0,1\}^n} \left(\hat{\phi}(s)-\hat{g}(s)\right)^2 + \left(1 - \mathbb{E}_{x\sim \mathcal{U}_n} \left[(\phi(x))^2\right]\right)\right).
    \end{align}

\label{lemma:parity-loss-explicit}
    Let $\mathcal{D}=(\mathcal{U}_n, \varphi)$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with uniform input marginal.
    Let $s\in\{0,1\}^n$. 
    Then,
    \begin{equation}
        \mathbb{P}_{(x,b)\sim \mathcal{D}}[b\neq s\cdot x]
        = \frac{1-\hat{\phi} (s)}{2}\, .
    \end{equation}

\label{lemma:parity-learning-via-heaviest-Fourier-coefficient}
    Let $\mathcal{D}=(\mathcal{U}_n, \varphi)$ be a probability distribution over $\mathcal{X}_n\times\{0,1\}$ with uniform input marginal.
    Let $\varepsilon\in (0,1)$. 
    If $s\in\{0,1\}^n$ is such that $\max_{t\in\{0,1\}^n} \hat{\phi}(t) - \hat{\phi}(s) \leq 2\varepsilon$, then also
    \begin{equation}
        \mathbb{P}_{(x,b)\sim\mathcal{D}}[b\neq s\cdot x]
        \leq \min\limits_{t\in\{0,1\}^n} \mathbb{P}_{(x,b)\sim\mathcal{D}}[b\neq t\cdot x] + \varepsilon\, .
    \end{equation}
    In particular, any procedure that, given $\delta,\varepsilon\in (0,1)$, outputs, with success probability $\geq 1-\delta$, an $(2\varepsilon)$-approximately-heaviest Fourier coefficient of $\phi$, immediately gives rise to a distributional $1$-agnostic parity learner.

\label{theorem:distributional-to-functional-reduction-classical}
    Let $\mathcal{F}\subseteq\{0,1\}^{\{0,1\}^n}$ be a benchmark class, let $\delta,\varepsilon\in (0,1)$ and $m=m(n, \delta,\varepsilon)\in\mathbb{N}_{>0}$ .
    Suppose that there is a randomized algorithm $A$ that, given access to a set of $m$ random examples, $S^{f}_m=(x_1,f(x_1)),\ldots,(x_m,f(x_m))$ from $(\mathcal{U}_n,f)$ for any function $f:\{0,1\}^n\to\{0,1\}$, with success probability $\geq 1-\delta$, outputs a function $h:\{0,1\}^n\to\{0,1\}$ such that 
    \begin{equation}
        \mathbb{P}_{x\sim\mathcal{U}_n}[f(x)\neq h(x)]
        \leq \inf_{\Tilde{h}\in\mathcal{F}}\mathbb{P}_{x\sim\mathcal{U}_n}[f(x)\neq \tilde{h}(x)] + \varepsilon.
    \end{equation}
    Then there is a randomized algorithm $\tilde{\mathcal{A}}$ that, given access to a set of $\tilde{m}=m(n, \tfrac{\delta}{2},\tfrac{\varepsilon}{3})$ random examples, $S^{\mathcal{D}}_m=(x_1,y_1),\ldots,(x_{\tilde{m}},y_{\tilde{m}})$ from $\mathcal{D}$ for any distribution $\mathcal{D}$ over $\{0,1\}^n\times\{0,1\}$ with $\mathcal{D}\rvert_{\mathcal{X}_n}=\mathcal{U}_n$, with success probability $\geq 1- \tfrac{\delta}{2} - \mathcal{O}(\tilde{m}^2\cdot 2^{-n}) -  ( \lvert\mathcal{F}\rvert + 1) \cdot \exp\left( - \frac{2^{n+1} \varepsilon^2}{9}\right)$, outputs a function $h:\{0,1\}^n\to\{0,1\}$ such that
    \begin{equation}
        \mathbb{P}_{(x,y)\sim\mathcal{D}}[y\neq h(x)]
        \leq \inf_{\Tilde{h}\in\mathcal{F}} \mathbb{P}_{(x,y)\sim\mathcal{D}}[y\neq \tilde{h}(x)] + \varepsilon.
    \end{equation} 
    Moreover, if $\mathcal{A}$ has runtime $t=t(n,\varepsilon,\delta)$, then $\tilde{\mathcal{A}}$ has runtime $\tilde{t} = t(n,\tfrac{\delta}{2},\tfrac{\varepsilon}{3})$.
    Finally, if $\mathcal{A}$ is proper, then so is $\tilde{\mathcal{A}}$.

\label{lemma:technical}
    For any $a,b\in\mathbb{R}_{\geq 0}^n$, if $\pi\in S_n$ is a permutation such that $a^\downarrow = a_\pi$, then the corresponding permutation $b_\pi$ of $b$ satisfies
    \begin{equation}
        \norm{b^\downarrow - b_\pi}_\infty
        \leq 2 \norm{a-b}_\infty .
    \end{equation}

\label{lemma:fully-uniform-vs-random-noisy-parity}
    Let $\eta\in [0,\nicefrac{1}{2})$.
    Any (classical or quantum) algorithm that, given $m$ classical examples from an unknown distribution $\mathcal{D}\in \{\mathcal{U}_{n+1}\}\cup \{(\mathcal{U}_n, (1-2\eta) \chi_s)\}_{s\in\{0,1\}^n}$, decides whether $\mathcal{D} = \mathcal{U}_{n+1}$ or $\mathcal{D}\in \{(\mathcal{U}_n, (1-2\eta) \chi_s)\}_{s\in\{0,1\}^n}$ with success probability $\geq \nicefrac{7}{12}$ has to use at least $m\geq \Omega (n)$ random examples.

\label{lemma:fourier-modification-reduction}
    Let $0 < a\leq b \leq 1$ with $a<1$.
    Let $\alpha = a$ and $\beta=\sqrt{b^2-a^2}$.
    Let $s\in\{0,1\}^n$.
    Define
    \begin{equation}
        \mathfrak{D}_{\alpha, \beta}^{s}
        =\left\{(\mathcal{U}_n, \varphi')~|~\exists t\in\{0,1\}^n\setminus\{s\}: \phi'=1-2\varphi' = \alpha\chi_s + \beta\chi_t\right\}.
    \end{equation}
    Let $\eta\in [0,\tfrac{1-\nicefrac{\beta}{(1-\alpha)}}{2}]$.
    The problem of distinguishing between a uniformly random element of $\mathfrak{D}_{\alpha, \beta}^{s}$ and $(\mathcal{U}_n, \alpha\chi_s)$ from samples is at least as hard as distinguishing between a uniformly random $\eta$-noisy parity (acting on uniformly random inputs) and the uniform distribution $\mathcal{U}_{n+1}$ from samples.

