        \item $\QPipure_i(c, s) \subseteq \QPipureSEP_i(1/np(n)^2, 1/e^n)$
      \end{enumerate}
  \end{enumerate}

\label{def:QCSigmam}
	Let $A=(\ayes,\ano)$ be a promise problem. We say that $A$ is in $\QCSigma_i(c, s)$ for poly-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a poly-bounded function $p:\natural\mapsto\natural$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proofs ${y_1}\in \set{0,1}^{p(n)}, \ldots, {y_i}\in \set{0,1}^{p(n)}$ and outputs a single qubit, {such that:}
	\begin{itemize}
		\item Completeness: $x\in \ayes$ $\Rightarrow$ $\exists y_1 \forall y_2 \ldots Q_i y_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \geq c$.
		\item Soundness: $x\in \ano$ $\Rightarrow$ $\forall y_1 \exists y_2 \ldots \overline{Q}_i y_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \leq s$.
	\end{itemize}
	Here, $Q_i$ equals $\exists$ when $m$ is odd and equals $\forall$ otherwise and $\overline{Q}_i$ is the complementary quantifier to $Q_i$. Finally, define
	\begin{equation}
	\QCSigma_i := \bigcup_{{ c - s \in \Omega(1/\poly(n))}} \QCSigma_i(c, s).
	\end{equation}

\label{def:QCPim}
	Let $A=(\ayes,\ano)$ be a promise problem. We say that $A \in \QCPi_i(c, s)$ for poly-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proofs ${y_1}\in \set{0,1}^{p(n)}, \ldots, {y_i}\in \set{0,1}^{p(n)}$ and outputs a single qubit, {such that:}
	\begin{itemize}
		\item Completeness: $x\in \ayes$ $\Rightarrow$ $\forall y_1 \exists y_2 \ldots Q_i y_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \geq c$.
		\item Soundness: $x\in \ano$ $\Rightarrow$ $\exists y_1 \forall y_2 \ldots \overline{Q}_i y_i$ s.t. s.t. $\operatorname{Prob}[V_n \text{ accepts } (y_1, \ldots, y_i)] \leq s$.
	\end{itemize}
	Here, $Q_i$ equals $\forall$ when $m$ is odd and equals $\exists$ otherwise, and $\overline{Q}_i$ is the complementary quantifier to $Q_i$. Finally, define
	\begin{equation}
	\QCPi_i := \bigcup_{{c - s \in \Omega(1/\poly(n))}} \QCPi_i(c, s).
	\end{equation}

\label{def:QCPH}
	\begin{equation}
        \QCPH = \bigcup_{m \in \mathbb{N}} \; \QCSigma_i = \bigcup_{m \in \mathbb{N}} \; \QCPi_i.
    \end{equation}

\label{def:QSigmam}
	A promise problem $A=(\ayes,\ano)$ is in $\QSigma_i(c, s)$ for poly-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes $p(n)$-qubit density operators $\rho_1, \ldots, \rho_i$ as quantum proofs and outputs a single {qubit, then:}
	\begin{itemize}
		\item Completeness: $x\in\ayes$ $\Rightarrow$ $\exists \rho_1 \forall \rho_2 \ldots Q_i \rho_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } ({\rho_1 \otimes \rho_2 \otimes \cdots \otimes  \rho_i})] \geq c$.
		\item Soundness: If $x\in\ano$ $\Rightarrow$ $\forall \rho_1 \exists \rho_2 \ldots \overline{Q}_i \rho_i$, $\operatorname{Prob}[V_n \text{ accepts } ({\rho_1 \otimes \rho_2 \otimes \cdots \otimes  \rho_i})] \leq s$.
	\end{itemize}
	As before, $Q_i$ equals $\forall$ when $m$ is even and equals $\exists$ otherwise, and $\overline{Q}_i$ is the complementary quantifier to $Q_i$. Define
	\begin{equation}
	   \QSigma_i = \bigcup_{\substack{c-s \in \Omega(1/\poly(n))}} \QSigma_i(c, s).
	\end{equation}

\label{def:QPim}
	A promise problem $A=(\ayes,\ano)$ is in $\QPi_i(c, s)$ for poly-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes $p(n)$-qubit density operators $\rho_1, \ldots, \rho_i$ as quantum proofs and outputs a single {qubit, then:}
	\begin{itemize}
		\item Completeness: $x\in\ayes$ $\Rightarrow$ $\forall \rho_1 \exists \rho_2 \ldots \overline{Q}_i \rho_i$, $\operatorname{Prob}[V_n \text{ accepts } ({\rho_1 \otimes \rho_2 \otimes \cdots \otimes  \rho_i})] \geq c$.
		\item Soundness: $x\in\ano$ $\Rightarrow$ $\exists \rho_1 \forall \rho_2 \ldots Q_i \rho_i$ s.t. $\operatorname{Prob}[V_n \text{ accepts } ({\rho_1 \otimes \rho_2 \otimes \cdots \otimes  \rho_i})]\leq s$.
	\end{itemize}
	Again, $Q_i$ equals $\exists$ when $m$ is even and equals $\forall$ otherwise, and $\overline{Q}_i$ is the complementary quantifier to $Q_i$. Define
	\begin{equation}
	\QPi_i = \bigcup_{c-s \in \Omega(1/\poly(n))} \QPi_i(c, s).
	\end{equation}

\label{def:QPH}
	\begin{equation}
        \QPH = \bigcup_{m \in \mathbb{N}} \; \QSigma_i = \bigcup_{m \in \mathbb{N}} \; \QPi_i.
    \end{equation}

\label{def:QSigmam_pure}
	A promise problem $A=(\ayes,\ano)$ is in $\QSigmapure_i(c, s)$ for poly-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes $p(n)$-qubit states $\ket{\psi_1}, \ldots, \ket{\psi_i}$ as quantum proofs and outputs a single {qubit, then:}
	\begin{itemize}
		\item Completeness: If $x\in\ayes$, then $\exists \ket{\psi_1} \forall \ket{\psi_2} \ldots Q_i \ket{\psi_i}$ such that $V_n$ accepts $({\ket{\psi_1} \otimes \ket{\psi_2} \otimes \cdots \otimes  \ket{\psi_i}})$ with probability $\geq c$.
		\item Soundness: If $x\in\ano$, then $\forall \ket{\psi_1} \exists \ket{\psi_2} \ldots \overline{Q}_i \ket{\psi_i}$ such that $V_n$ accepts $({\ket{\psi_1} \otimes \ket{\psi_2} \otimes \cdots \otimes \ket{\psi_i}})$ with probability $\leq s$.
	\end{itemize}
	Here, $Q_i$ equals $\forall$ when $m$ is even and equals $\exists$ otherwise, and $\overline{Q}_i$ is the complementary quantifier to $Q_i$. Define
	\begin{equation}
    \QSigmapure_i = \bigcup_{\substack{c-s \in \Omega(1/\poly(n))}} \QSigmapure_i(c, s).
	\end{equation}

\label{def:QPimprime}
	A promise problem $A=(\ayes,\ano)$ is in $\QPipure_i(c, s)$ for poly-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes $p(n)$-qubit states $\ket{\psi_1}, \ldots, \ket{\psi_i}$ as quantum proofs and outputs a single {qubit, then:}
	\begin{itemize}
		\item Completeness: If $x\in\ayes$, then $\forall \ket{\psi_1} \exists \ket{\psi_2} \ldots Q_i \ket{\psi_i}$ such that $V_n$ accepts $({\ket{\psi_1} \otimes \ket{\psi_2} \otimes \cdots \otimes  \ket{\psi_i}})$ with probability $ \geq c$.
		\item Soundness: If $x\in\ano$, then $\exists \ket{\psi_1} \forall \ket{\psi_2} \ldots \overline{Q}_i \ket{\psi_i}$ such that $V_n$ accepts $({\ket{\psi_1} \otimes \ket{\psi_2} \otimes \cdots \otimes  \ket{\psi_i}})$ with probability $\leq s$.
	\end{itemize}
	Here, $Q_i$ equals $\exists$ when $m$ is even and equals $\forall$ otherwise, and $\overline{Q}_i$ is the complementary quantifier to $Q_i$. Define
	\begin{equation}
	  \QPipure_i = \bigcup_{c-s \in \Omega(1/\poly(n))} \QPipure_i(c, s).
	\end{equation}

\label{def:PrQCMA}
    A promise problem $A=(\ayes,\ano)$ is in $\PrQCMA(c,s)$ for poly-time computable functions $c,s:\natural\mapsto[0,1]$ if there exists poly-bounded functions $p,q:\natural\mapsto\natural$ such that $\forall \ell \in \natural, \ c(\ell) - s(\ell) \geq 2^{-q(\ell)}$, and there exists a poly-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ that takes a classical proof ${y}\in \set{0,1}^{p(n)}$ and outputs a single qubit. Moreover, for an $n$-bit input $x$:
    \begin{itemize}
     \item Completeness: If $x\in \ayes$, then $\exists\ y$ such that $V_n$ accepts $y$ with probability at least $c(n)$.
     \item Soundness: If $x\in \ano$, then $\forall\ y$, ${V_x}$ accepts $y$ with probability at most $s(n)$.
    \end{itemize}
    Define $\PrQCMA=\bigcup_{c,s} \PrQCMA(c,s)$.

  Let $A=(\ayes,\ano)$ be a promise problem. We say that $A \in \UQCMA(c,s)$ for polynomial-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a polynomial-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proof ${y_1}\in \set{0,1}^{p(n)}$ and outputs a single qubit, {such that:}
\begin{itemize}
    \item Completeness: $x\in \ayes$ $\Rightarrow$ $\exists y_1$ s.t. $\Pr[V_n(x, y_1) = 1] \geq c$ and $\forall y_1' \neq y_1 \Pr[V_n(x, y_1) = 1] \leq s$.
    \item Soundness: $x\in \ano$ $\Rightarrow$ $\forall y_1$ s.t. $\Pr[V_n(x, y_1) = 1] \leq s$.
\end{itemize}
  \begin{equation}
\text{Define } \; \UQCMA := \bigcup_{{c - s \in \Omega(1/\poly(n))}} \UQCMA(c, s).
\end{equation}

\label{def:tqcmapp}
Let $\tqcmapp$ = $(\tqcmappyes$, $\tqcmappno)$ denote the `trivial' complete problem for $\QCMA$ defined as follows. Every instance consists of a quantum circuit $U$, instance $x$, probabilities $p_1, p_2$, witness length $\ell$ (probabilities and witness length expressed in unary\footnote{We assume the probabilities are rationals, and the numerator and denominator are expressed in unary}). 

\begin{itemize}
    \item $(U, x, p_1, p_2, \ell) \in \tqcmappyes$ $\implies$ $ \exists d \in \bit^{\ell}$ s.t. 
    $\Pr\Brackets{U\brackets{\ket{x}, \ket{d}} = 1} \geq p_2$

    \item $(U, x, p_1, p_2, \ell) \in \tqcmappno$ $\implies$ $\forall d \in \bit^{\ell}$, 
    $\Pr\Brackets{U\brackets{\ket{x}, \ket{d}} = 1} \leq p_1$
\end{itemize}

\label{uqcma}
There is a probabilistic polynomial time reduction $f$ from $\TQCMAPP$ to $\UQCMAPP$ such that
\begin{itemize}
    \item $\phi = (U, x, p_1, p_2, \ell) \in \tqcmappyes \implies \Pr\Brackets{f(\phi) \in \uqcmappyes} \geq 1/32\ell^2$. 
    \item $\phi = (U, x, p_1, p_2, \ell) \in \tqcmappno \implies \Pr\Brackets{f(\phi) \in \uqcmappno} = 1$
\end{itemize}

Here the probabilities are over the random coins used by reduction $f$.

\label{qcsptwo}
Let $A=(\ayes,\ano)$ be a promise problem. We say that $A$ is in $\qcsptwo(c, s)$ for polynomial-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a polynomial-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit instance $x$, $V_n$ takes in classical proofs ${y_1}\in \set{0,1}^{p(n)}, {y_2}\in \set{0,1}^{p(n)}$ and outputs a single qubit, {such that:}
\begin{itemize}
    \item Completeness: $x\in \ayes$ $\Rightarrow$ $\exists y_1 \forall y_2$, $\Pr[V_n(x, y_1, y_2) = 1] \geq c$.
    \item Soundness: $x\in \ano$ $\Rightarrow$ $\exists y_2 \forall y_1$, $\Pr[V_n(x, y_1, y_2) = 1] \leq s$.
\end{itemize}


\begin{equation}
\text{Define } \; \qcsptwo := \bigcup_{{ c - s \in \Omega(1/\poly(n))}} \qcsptwo(c, s).
\end{equation}

Let $A=(\ayes,\ano)$ be a promise problem. We say that $A \in \QCAM(c,s)$ for polynomial-time computable functions $c, s: \natural \mapsto [0, 1]$ if there exists a polynomially bounded function $p:\natural\mapsto\natural$ and a polynomial-time uniform family of quantum circuits $\{V_n\}_{n \in \natural}$ such that for every $n$-bit input $x$, $V_n$ takes in classical proof ${y}\in \set{0,1}^{p(n)}$ and a random string $z \in \set{0,1}^{p(n)}$ and outputs a single qubit, {such that:}
\begin{itemize}
  \item Completeness: $x\in \ayes$ $\Rightarrow$ $\Pr_z[\exists y_1 \text{ s.t. } \Pr[V_n(x, z, y_1) = 1] \geq 1-\frac{1}{2^n}] \geq c$.
  \item Soundness: $x\in \ano$ $\Rightarrow$ $\Pr_z[\exists y_1 \text{ s.t. } \Pr[V_n(x, z, y_1) = 1] \geq 1-\frac{1}{2^n}] \leq s$.
\end{itemize}
\begin{equation}
    \text{Define } \; \QCAM := \bigcup_{{c' - s' \in \Omega(1/\poly(n))}} \QCAM(c, s).
\end{equation}

\label{l:apt}
  Define $d=d_1\cdots d_n$.
  Consider $\ket{\phi}_{BC}\in\C^{d^m}\otimes\C^{d'}$ for some $d'>0$.
  Suppose
  \begin{equation}
    \max_{\ket{\psi}:= \ket{\psi_1}\otimes\cdots\otimes\ket{\psi_n}\in\C^d}\quad\bra\phi_{BC}[(\ketbra{\psi}{\psi}^{\otimes m})_B\otimes I_C]\ket\phi_{BC}=1-\epsilon
  \end{equation}
  for $\epsilon\geq 0$.
  Then, given the state $\ket{\eta}_{ABC}:=\ket{\psi}_A\otimes \ket{\phi}_{BC}$, the APT accepts with probability at most $1-\epsilon/2mn$.

\label{l:qpi}
If $i$ is even, then
\begin{equation}
  \QPipure_i(c, s) \subseteq \QPipureSEP_i\left(1-\frac{1}{e^n}, 1-\frac{1}{np(n)^2}\right),
\end{equation}
for all functions $c$ and $s$ such that $c - s \geq$ 1/p(n) for some polynomial $p$.

\label{qpi_amp}
  For even $i$, if $\QPiSEP_i(c, s) = \QPipureSEP_i(c, s)$ with $c - s \geq 1/p(n)$ for some polynomial $p$, then
  \begin{align}
    \QPi_i(c,s) = \QPipure_i(c,s) = \QPipure_i(1-1/e^{r(n)},1/e^{r(n)}) = \QPi_i(1-1/e^{r(n)},1/e^{r(n)})
  \end{align}
  for some polynomial $r$.

If Q$\Sigma_i^{SEP}$(c,s) = Q$\Sigma_i^{'SEP}$(c,s) for odd i, and Q$\Pi_i^{SEP}$(c,s) = Q$\Pi_i^{'SEP}$(c,s) for even i and for all c, s such that c - s $\geq$ 1/p(n) for polynomial p, then the following holds true:
\begin{enumerate}
    \item Q$\Pi_i$(c,s) = $\QPipure$(c,s) = $\QPipure(1-1/e^{r(n)},1/e^{r(n)}$ = Q$\Pi_i(1-1/e^{r(n)},1/e^{r(n)}$)
    \item Q$\Sigma_i$(c,s) = $\QSigmapure$(c,s) = $\QSigmapure(1-1/e^{r(n)},1/e^{r(n)})$ = Q$\Sigma_i(1-1/e^{r(n)},1/e^{r(n)})$
\end{enumerate}
where r is a polynomial.

For a 
function $f \colon \{0,1\}^{\star} \rightarrow \{0,1\}$ and an algorithm $A$, a $\PTIME$-\emph{refuter} for $f$ against $A$ is a deterministic polynomial time algorithm $R$ that, given input $1^n$, prints a string $x\in \{0,1\}^n$,  such that for infinitely many $n$,  $A(x)\neq f(x)$.

We extend this definition to randomized refuters as follows:
\begin{itemize}
	\item A $\BPP$-\emph{refuter} for $f$ against $A$ is a randomized polynomial time algorithm $R$ that, given input $1^n$, prints a string $x\in \{0,1\}^n$,
	such that for infinitely many $n$,  $A(x)\neq f(x)$ with probability at least $2/3$.\footnote{We remark that here it is not necessarily possible to amplify the success probability, so the choice of the constant $2/3$ matters.}
	\item A $\ZPP$-\emph{refuter}
	for $f$ against $A$ is a randomized polynomial time algorithm $R$ that, given input $1^n$, prints $x\in \{0,1\}^n\cup \{\perp\}$, such that for infinitely many $n$, either $x= \perp$ or $A(x)\neq f(x)$ with probability $1$, and $x\neq \perp$ with probability at least $2/3$.
\end{itemize} 


For ${\cal D}\in \{\PTIME, \BPP, \ZPP\}$ and a typical complexity class ${\cal C}$, we say there is a \emph{${\cal D}$-constructive separation of $f \notin {\cal C}$}, if for every algorithm $A$ computable in ${\cal C}$, there is a refuter for $f$ against $A$ that is computable in ${\cal D}$. 
\label{defn:refuter}

{theorem}{theorefuterqc}\label{theo:refuter-qc-to-PNP} \theorestated
	Let $\eps$ be a function of $n$ satisfying $\eps \leq 1/(\log n)^{\omega(1)}$, and $1/\eps$ is a positive integer computable in $\poly(1/\eps)$ time given $n$ in binary.
	\begin{itemize}
		\item If there is a polylogtime-uniform-$\AC^0$-constructive separation of $\GapMAJ_{n,\eps}$ from randomized query algorithms $A$ using $o(1/\eps^2)$ queries and $\poly(1/\eps)$ time, then $\NP \ne \PTIME$.
		\item If there is a polylogtime-uniform-$\NC^1$-constructive separation of $\GapMAJ_{n,\eps}$ from randomized query algorithms $A$ using $o(1/\eps^2)$ queries and $\poly(1/\eps)$ time, then $\PSPACE \ne \PTIME$.
	\end{itemize}

{theorem}{theononp}
	\label{thm:no-np-refuter} \theorestated
	The following hold:
	\begin{itemize}
		\item 
		If $\NE \neq \E$, then there is a language in $\NP \setminus \PTIME$ that does not have $\PTIME$ refuters against the constant one function.\footnotenonpa
		\item 
		If $\NE \neq \RE$, then there is a language in $\NP \setminus \PTIME$ that does not have $\BPP$ refuters against the constant one function.\footnotenonpb
	\end{itemize}

\label{lemma:P-NP-small-circuit}
Let $s\colon \N \to \N$ be an increasing function. The following hold:


\begin{enumerate}
    \item Assuming $\E^\NP \subset \SIZE[s(n)]$, then for every $\PTIME^\NP$ algorithm $R$ such that $R(1^n)$ outputs $n$ bits, it holds that $R(1^n)$ has circuit complexity at most $s(O(\log n))$.
    \item Assuming $\E \subset \SIZE[s(n)]$, then for every $\PTIME$ algorithm $R$ such that $R(1^n)$ outputs $n$ bits, it holds that $R(1^n)$ has circuit complexity at most $s(O(\log n))$.
    \item Assuming $\SPACE[O(n)] \subset \SIZE[s(n)]$, then for every LOGSPACE algorithm $R$ such that $R(1^n)$ outputs $n$ bits, it holds that $R(1^n)$ has circuit complexity at most $s(O(\log n))$.
\end{enumerate}

 \label{lem:pnpac0} 
	The following hold:
   \begin{enumerate}
       \item 
   Assuming $\PTIME = \NP$, then for every polylogtime-uniform $\AC^0$ algorithm $R$ such that $R(1^n)$ outputs $n$ bits, it holds that $R(1^n)$ has circuit size complexity at most $\polylog(n)$.
   \item 
   Assuming $\PTIME = \PSPACE$, then for every polylogtime-uniform $\NC^1$ algorithm $R$ such that $R(1^n)$ outputs $n$ bits, it holds that $R(1^n)$ has circuit size complexity at most $\polylog(n)$.
   \end{enumerate}

\label{lm:McKayMW19-search-MCSP}
	Assuming $\NP \subseteq \BPP$, for a time-constructive $s \colon \mathbb{N} \to \mathbb{N}$, there is a randomized streaming algorithm for $\sMCSP[s(n)]$ on $N$-bit instances (where $N=2^n$) with $O(N \cdot s(n)^c)$ time and $O(s(n)^c)$ space for a constant $c$ such that the following holds.
	\begin{itemize}
		\item If the input $x \in \MCSP[s(n)]$, the algorithm outputs a circuit $C$ of size at most $s(n)$ computing $x$ with probability at least $1 - 1/N$.
		\item If the input $x \notin \MCSP[s(n)]$, the algorithm always outputs NO.
	\end{itemize}

	Alternatively, if we assume $\NP = \PTIME$ instead, the above randomized streaming algorithm can be made deterministic.

 \label{thm:pal}
	The following hold:
	\begin{itemize}
	    \item A $\PTIME^{\NP}$-constructive separation of $\PAL$ from nondeterministic $O(n^{1.1})$ time one-tape Turing machines implies $\E^{\NP} \not \subset \SIZE[2^{\delta n}]$ for some constant $\delta >0$.

        \item A $\PTIME$-constructive separation of $\PAL$ from nondeterministic $O(n^{1.1})$ time one-tape Turing machines implies $\E \not \subset \SIZE[2^{\delta n}]$ for some constant $\delta >0$.

        \item A LOGSPACE-constructive separation of $\PAL$ from nondeterministic $O(n^{1.1})$ time one-tape Turing machines implies $\PSPACE \not \subset \SIZE[2^{\delta n}]$ for some constant $\delta >0$.
	\end{itemize}

	\label{rem:list}
		For function $f \colon \{0,1\}^{\star} \rightarrow \{0,1\}$ and algorithm $A$,
  \begin{itemize}
      \item 
  A constant-size $\PTIME$-list-refuter for $f$ against $A$ implies that there exists a $\PTIME$-refuter for $f$ against~$A$.
  \item 
	For $\caD \in \{\BPP,\ZPP\}$,	 a pseudo-deterministic constant-size $\caD$-list-refuter (i.e., for each input length $n$ there is a canonical list such that the refuter outputs the canonical list with $1-o(1)$ probability given input $1^n$) for $f$ against $A$ implies that there exists a $\caD$-refuter for $f$ against~$A$.
  \end{itemize}

\label{thm:pp}
Let $\caC\in \{\PTIME,\BPP,\ZPP\}$.
If $\PP \nsubseteq \caC$,  then for every paddable $\PP$-complete language~$L$, there is a $\caC$-constructive separation of $L \notin \caC$.
